window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0040", [{"word":"capitalization","ipa_uk":"/ˌkæpɪtəlaɪˈzeɪʃn/","ipa_us":"/ˌkæpɪtələˈzeɪʃn/","definition_zh":"资本化；资本总额；市值；大写（首字母大写）；利用","definition_en":"the act of turning something into capital, the total capital of a company, or the use of capital letters","core_image":"把某物抬到“头”的位置：字母抬到词首，金钱抬成资本","scene":"编辑部里，编辑把每一段的第一个字母改成大写，并在页边写下三条规则。In the editorial office, the editor changes the first letter of every paragraph and writes three capitalization rules in the margin.","sceneCN":"这里 capitalization 是「大写、首字母大写」（第 1、8 个义项：正字法与字母用法）；句意：编辑把每段第一个字母改为大写，并在页边写下三条大写规则。图中可辨识物件：稿件、红笔、页边批注、字母表。","pos":[{"tag":"n.","zh":"资本化；资本总额；大写"}],"collocations":[{"phrase":"market capitalization","zh":"市值；市场资本总额"},{"phrase":"capitalization rate","zh":"资本化率"},{"phrase":"capitalization of interest","zh":"利息资本化"},{"phrase":"proper capitalization","zh":"正确的大写用法"},{"phrase":"total capitalization","zh":"资本总额"},{"phrase":"capitalization of knowledge","zh":"知识资本化"}],"forms":[{"label":"单数","form":"capitalization"},{"label":"复数（多种资本化／大写方式）","form":"capitalizations"},{"label":"英式拼写","form":"capitalisation"}],"derivatives":[{"word":"capitalize","pos":"vt.","zh":"资本化；用大写字母书写；利用"},{"word":"capital","pos":"n.","zh":"资本；首都；大写字母"},{"word":"capitalism","pos":"n.","zh":"资本主义"},{"word":"capitalist","pos":"n.","zh":"资本家"}],"senses":[{"no":"01","title":"Writing a letter as a capital","titleCN":"把字母写成大写","definition":"the use of capital letters at the beginning of a word or sentence","definitionCN":"在词首或句首使用大写字母","example":"Check the capitalization of every proper noun in the essay.","exampleCN":"检查文章中每个专有名词的大写。","why":"A capital letter was once the letter 'of the head', standing at the head of a sentence. Capitalization names the act of putting that head-letter in place.","whyCN":"大写字母原本是“头部的字母”，站在句子的开头。capitalization 命名的是把这个“头字母”放到位的行为。"},{"no":"02","title":"Writing a whole word in capitals","titleCN":"整词大写","definition":"the practice of setting an entire word or phrase in capital letters, as in headlines","definitionCN":"把整个词或短语排成大写字母的做法，如标题中","example":"The headline uses full capitalization for emphasis.","exampleCN":"标题用全大写来强调。","why":"Once the head-letter idea is established, the same device can spread to the whole word. Emphasis, not grammar, now drives the choice.","whyCN":"一旦“头字母”的观念建立起来，同一种手段就能扩展到整个词。此时驱动选择的是强调，而不是语法。"},{"no":"03","title":"The total capital of a company","titleCN":"公司的资本总额","definition":"the total amount of money and other capital invested in a business","definitionCN":"投入一家企业的资金与其他资本的总量","example":"The firm has a total capitalization of about two billion dollars.","exampleCN":"这家公司的资本总额约为二十亿美元。","why":"Capital is the 'principal sum', the chief amount at the head of an account. Capitalization turns that sum into a measured total.","whyCN":"capital 是“本金”，账目顶端的那个主要数额。capitalization 把这个数额变成一个被计量的总量。"},{"no":"04","title":"Market value of a listed company","titleCN":"上市公司的市值","definition":"the total value of a company's shares on the stock market","definitionCN":"一家公司股票在证券市场上的总价值","example":"Its market capitalization fell by a third in one week.","exampleCN":"它的市值一周内跌去三分之一。","why":"The market, not the accountant, now decides the size of the principal. Capitalization becomes a price times a number of shares, a public measure of value.","whyCN":"现在由市场而非会计决定本金的大小。资本化变成价格乘以股数，是一种公开的价值度量。"},{"no":"05","title":"Turning a cost into an asset","titleCN":"把支出转为资产（会计）","definition":"in accounting, the treatment of a cost as a long-term asset rather than an immediate expense","definitionCN":"会计中把某项支出作为长期资产而非当期费用处理","example":"The capitalization of the new equipment spread its cost over ten years.","exampleCN":"新设备的资本化把成本分摊到十年。","why":"To capitalize a cost is to place it at the head of the balance sheet instead of writing it off at once. The accounting sense is a spatial promotion.","whyCN":"把成本资本化，就是把它放到资产负债表的前端，而不是一次核销。这个会计义是一种空间上的“提拔”。"},{"no":"06","title":"Supplying a business with capital","titleCN":"为企业注资","definition":"the act of providing a company with money or capital to start or expand","definitionCN":"为公司提供资金或资本以启动或扩张","example":"The bank required a detailed plan before capitalization.","exampleCN":"银行在注资前要求一份详细计划。","why":"Here the word names the act that creates the principal. Money is not merely counted as capital; it is made into capital by being put in.","whyCN":"这里这个词命名的是创造本金的行为。钱不只是被算作资本，它是因为被投入才成为资本。"},{"no":"07","title":"Converting income into value","titleCN":"把收益折算为价值（估值）","definition":"in valuation, the conversion of a stream of future income into a present capital value","definitionCN":"估值中把未来收入流折算为当前资本价值","example":"The appraiser used income capitalization to value the building.","exampleCN":"评估师用收益资本化法给这栋楼估值。","why":"Future rent is imagined as a flow that can be gathered into one principal sum. Capitalization is the formula that gathers it.","whyCN":"未来租金被想象成一条可以聚成一个本金总额的流。资本化就是把这条流聚起来的公式。"},{"no":"08","title":"Turning a chance into an advantage","titleCN":"把机会转为优势","definition":"the act of taking advantage of a situation, from the verb phrase capitalize on","definitionCN":"利用某种局面，来自动词短语 capitalize on","example":"The capitalization of the crisis by rivals was swift.","exampleCN":"对手对这场危机的利用十分迅速。","why":"Capitalize on means to turn an event into capital. The noun extends the financial metaphor to any situation that can be made profitable.","whyCN":"capitalize on 意为把某件事变成资本。这个名词把金融比喻扩展到任何可以被“变现”的局面。"},{"no":"09","title":"The rate used in income valuation","titleCN":"资本化率","definition":"the multiplier or rate used to convert expected income into capital value","definitionCN":"把预期收益换算成资本价值所用的比率或乘数","example":"A lower capitalization rate raises the estimated value.","exampleCN":"较低的资本化率会抬高估算价值。","why":"Once income is gathered into capital, the gathering needs a rate. Capitalization then names the number that governs the conversion, not the conversion itself.","whyCN":"一旦收益被聚成资本，这个聚拢就需要一个比率。于是 capitalization 命名的是支配换算的那个数字，而不是换算本身。"}],"etymology":{"intro":{"en":"Capitalization is a two-storey derivative: capital plus the verb suffix -ize, then plus the noun suffix -ation. Capital itself goes back to Latin caput, 'head', and the whole family turns on the idea of something chief being placed at the top.","cn":"capitalization 是两层派生：capital 先加动词后缀 -ize，再加名词后缀 -ation。capital 本身上溯拉丁语 caput“头”，整个词族都围绕“把主要的东西放到顶端”这一想法转动。"},"items":[{"era":"PIE *kaput-","en":"The root *kaput- meant 'head'. It gave Latin caput and English head is a different formation, but the Latin branch supplies capital, captain, chapter and cattle.","cn":"词根 *kaput- 意为“头”。它给出拉丁语 caput；英语 head 是另一支，但拉丁这一支提供了 capital、captain、chapter、cattle。"},{"era":"LATIN caput / capitalis","en":"Caput was the head of a person or an object. Capitalis, formed with -alis, meant 'of the head' and then 'chief, principal', because what is at the head leads the rest.","cn":"caput 是人或物的头。capitalis 由 -alis 构成，先指“属于头的”，后指“首要的、主要的”，因为位于头部的部分引领其余部分。"},{"era":"LATIN capitulum","en":"The diminutive capitulum meant 'little head' and came to name a division of a book, a chapter. English chapter descends from it, showing how 'head' became a unit of text.","cn":"指小词 capitulum 意为“小头”，后来用来命名书中的一个部分，即一章。英语 chapter 由此而来，展示“头”如何变成一个文本单位。"},{"era":"12C.–14C. FRENCH AND ITALIAN","en":"Old French and Italian capitale named the principal sum of a loan and the chief city of a region. Both senses grew from 'chief thing', not from 'money' as such.","cn":"古法语与意大利语 capitale 指贷款的本金以及一个地区的主要城市。两者都从“首要之物”生长出来，而不是直接来自“钱”。"},{"era":"17C. ENGLISH capital","en":"English capital is established in the 17th century for the principal sum of money. The phrase capital letter, a letter at the head of a sentence, gives the later orthographic branch.","cn":"英语 capital 在 17 世纪确立为“本金”。短语 capital letter 指句子开头的字母，给出后来正字法这一支。"},{"era":"18C.–19C. capital + -ize + -ation","en":"Capitalize appears in the 18th century with both the money sense and the letter sense; capitalization follows in the 19th. The suffixes are Greek -izein through Latin -izare, and Latin -atio.","cn":"capitalize 出现于 18 世纪，兼具金钱义与字母义；capitalization 随后在 19 世纪出现。后缀是希腊语 -izein 经拉丁语 -izare，以及拉丁语 -atio。"}]},"similar":{"note":{"en":"The look-alike group separates the verb, the base noun and the British spelling. The meaning group compares words from finance and writing that sit close by.","cn":"形近组区分动词、基础名词与英式拼写；词义组比较金融与书写领域中相邻的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"capitalisation","ipa":"/ˌkæpɪtəlaɪˈzeɪʃn/","tag":"British spelling","definition":"the same word spelled with -s- instead of -z-, standard in British English.","definitionCN":"同一个词，用 -s- 代替 -z-，是英式英语的标准拼写。"},{"word":"capitalize","ipa":"/ˈkæpɪtəlaɪz/","tag":"derived verb","definition":"the verb behind the noun: to write in capitals, to convert into capital, or to exploit.","definitionCN":"名词背后的动词：用大写书写、转为资本，或利用。"},{"word":"capital","ipa":"/ˈkæpɪtl/","tag":"base noun","definition":"money, a chief city, or a capital letter. It is the base from which capitalization is built.","definitionCN":"资本、首都或大写字母。它是构成 capitalization 的基础词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"funding","ipa":"/ˈfʌndɪŋ/","tag":"money supplied","definition":"money provided for a project or organization. It names the money itself, while capitalization names the act or the total.","definitionCN":"为项目或组织提供的钱。它指钱本身，而 capitalization 指行为或总额。"},{"word":"valuation","ipa":"/ˌvæljuˈeɪʃn/","tag":"value estimate","definition":"an estimate of how much something is worth. Market capitalization is one kind of valuation.","definitionCN":"对某物价值的估算。市值是估值的一种。"},{"word":"equity","ipa":"/ˈekwəti/","tag":"ownership","definition":"the value of a company's shares, or ownership in it. It is a component of capitalization, not the whole measure.","definitionCN":"公司股份的价值，或其中的所有权。它是资本化的组成部分，而不是全部度量。"},{"word":"orthography","ipa":"/ɔːˈθɒɡrəfi/","tag":"writing system","definition":"the conventions of writing a language, including capitals. Capitalization is one small part of orthography.","definitionCN":"一种语言的书写惯例，包括大写。大写只是正字法的一小部分。"}]}]},"mnemonics":{"normalIntro":{"en":"These hooks build the word from capital and its two suffixes, then attach the two large meaning fields: money and letters.","cn":"这些记忆钩从 capital 与两个后缀搭起这个词，再挂上两大义场：金钱与字母。"},"normal":[{"en":"See the layers: capital + -ize + -ation. The noun is the action of the verb.","cn":"看见层级：capital 加 -ize 再加 -ation。名词就是动词的动作。"},{"en":"Link capital to caput, head: capital is the head-sum of an account.","cn":"把 capital 连到 caput“头”：资本是账目的“头款”。"},{"en":"For writing, remember that a capital letter stands at the head of a sentence.","cn":"在书写方面，记住大写字母站在句子的头部。"},{"en":"Pair market capitalization with share price: price times shares gives the total.","cn":"把市值与股价配对：价格乘以股数得到总额。"},{"en":"Keep capitalize on in mind: to capitalize is to turn an event into capital.","cn":"记住 capitalize on：capitalize 就是把一件事变成资本。"}],"abstract":[{"en":"Hold one vertical image: something is lifted to the head. Letters, costs and money are all lifted.","cn":"抓住一个垂直意象：某物被抬到头部。字母、成本、金钱都被抬起。"},{"en":"Sort the senses into two towers: the money tower and the letter tower, joined by the same 'head' idea.","cn":"把义项分成两座塔：金钱塔与字母塔，由同一个“头”的观念连接。"},{"en":"Remember the suffix chain: -ize makes the verb, -ation makes the process noun.","cn":"记住后缀链：-ize 造动词，-ation 造过程名词。"}]},"examples":[{"en":"Please follow the house style for capitalization in headings.","cn":"标题中的大写请遵循本刊体例。"},{"en":"The company's market capitalization passed one trillion dollars.","cn":"这家公司的市值突破了一万亿美元。"},{"en":"The capitalization of research costs changed the reported profit.","cn":"研发成本的资本化改变了报告的利润。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音“资本头来则神”：把“资本”抬到“头”上，字母也抬到词首——capitalization 就是资本化与大写。","word":"capitalization"},"root":"拉丁语 caput“头”及其形容词 capitalis“头部的、首要的”，经古法语与意大利语 capitale“本金、首城”进入英语作 capital；再加希腊—拉丁动词后缀 -ize 与拉丁名词后缀 -ation，构成 capitalization。","sensesIntro":{"en":"Capitalization keeps one gesture across two very different fields: lifting something to the head. In writing, a letter is lifted to the head of a sentence; in finance, a sum is lifted to the head of an account and becomes capital. The nine senses are variations on that promotion, plus the modern extension in which any opportunity can be turned into capital.","cn":"capitalization 在两个很不同的领域保持同一个动作：把某物抬到头部。在书写中，字母被抬到句首；在金融中，一笔钱被抬到账目前端，成为资本。九个义项都是这种“提拔”的变体，再加上现代延伸——任何机会都能被转化为资本。"},"semanticMap":{"core":{"en":"Lifting something to the head: making a letter, a cost or a sum into 'capital'.","cn":"把某物抬到头部：使字母、成本或款项成为“资本”。"},"chain":["HEAD","CHIEF","PRINCIPAL","CAPITAL","PROCESS","MEASURE"],"branches":[{"senses":"S1 · S2","en":"LETTERS: single capitals and whole words set in capitals.","cn":"字母：单个大写字母与整词大写。"},{"senses":"S3 · S4 · S6","en":"CAPITAL STOCK: total capital, market value, and the act of supplying it.","cn":"资本存量：资本总额、市值，以及注资行为。"},{"senses":"S5","en":"ACCOUNTING: a cost promoted to an asset.","cn":"会计：成本被提升为资产。"},{"senses":"S7 · S9","en":"VALUATION: income gathered into capital, and the rate that governs it.","cn":"估值：收益被聚成资本，以及支配它的比率。"},{"senses":"S8","en":"METAPHOR: any situation turned into an advantage.","cn":"比喻：任何局面被转为优势。"}]},"affixes":{"intro":{"en":"Capitalization shows two suffixes stacked on one base: -ize turns capital into a verb, and -ation turns that verb into a process noun. The family below also shows -ism and -ist on the same base.","cn":"capitalization 展示同一个词基上叠了两层后缀：-ize 把 capital 变成动词，-ation 再把动词变成过程名词。下列词族也展示同一词基上的 -ism 与 -ist。"},"latinIntro":{"en":"The Latin entries go back to the head itself and to the adjective of 'chief'. They explain why the financial and typographic senses share one word.","cn":"拉丁语条目回到“头”本身以及“首要的”形容词。它们解释了为什么金融义与排版义共用同一个词。"},"items":[{"word":"capitalization","structure":"capital + -ize + -ation","meaning":"the act of capitalizing; total capital; use of capitals","meaningCN":"资本化；资本总额；大写","example":"Capitalization rules vary between languages.","exampleCN":"大写规则因语言而异。"},{"word":"capitalize","structure":"capital + -ize (verb suffix)","meaning":"to write in capitals, convert into capital, or exploit","meaningCN":"用大写书写；转为资本；利用","example":"You should capitalize the first word.","exampleCN":"你应该把第一个词大写。"},{"word":"capital","structure":"Latin capitalis, through French","meaning":"money; chief city; capital letter","meaningCN":"资本；首都；大写字母","example":"They raised capital for the factory.","exampleCN":"他们为工厂筹集了资本。"},{"word":"caput","structure":"Latin root noun","meaning":"head","meaningCN":"头","example":"Caput is the root behind capital.","exampleCN":"caput 是 capital 背后的词根。"},{"word":"capitalis","structure":"caput + -alis (adjective suffix)","meaning":"of the head; chief, principal","meaningCN":"头部的；首要的","example":"The Latin adjective capitalis meant chief.","exampleCN":"拉丁形容词 capitalis 意为首要的。"},{"word":"capitulum","structure":"caput + -ulum (diminutive)","meaning":"little head; a chapter","meaningCN":"小头；一章","example":"Capitulum became English chapter.","exampleCN":"capitulum 演变为英语 chapter。"},{"word":"capitalism","structure":"capital + -ism (system suffix)","meaning":"an economic system based on private capital","meaningCN":"资本主义","example":"Industrial capitalism changed the city.","exampleCN":"工业资本主义改变了这座城市。"},{"word":"capitalist","structure":"capital + -ist (person suffix)","meaning":"a person who owns or invests capital","meaningCN":"资本家","example":"The factory was built by a local capitalist.","exampleCN":"这座工厂由一位本地资本家兴建。"},{"word":"capital letter","structure":"capital + letter (compound noun)","meaning":"a letter at the head of a word or sentence","meaningCN":"大写字母","example":"Names begin with a capital letter.","exampleCN":"姓名以大写字母开头。"},{"word":"capitalize on","structure":"capitalize + on (phrasal verb)","meaning":"to use an event or chance to gain an advantage","meaningCN":"利用（机会或局面）","example":"They capitalized on the confusion.","exampleCN":"他们利用了那场混乱。"}],"latinEntries":[{"word":"caput","structure":"root noun (3rd declension, capitis)","meaning":"head","meaningCN":"头"},{"word":"capitalis","structure":"caput + -alis","meaning":"of the head; chief, principal","meaningCN":"头部的；首要的"},{"word":"capitulum","structure":"caput + -ulum (diminutive)","meaning":"little head; chapter","meaningCN":"小头；章"}]}},{"word":"carbon","ipa_uk":"/ˈkɑːbən/","ipa_us":"/ˈkɑːrbən/","definition_zh":"碳；碳元素；复写纸；复写副本；碳棒","definition_en":"the chemical element with the symbol C, or a carbon copy or carbon paper","core_image":"一块乌黑的炭：轻，能烧，烧完后留下灰，却是有机世界的骨架","scene":"实验台上放着一小片石墨和一根碳棒，老师用它们在纸上画出电路：This is carbon, the element behind all life. ","sceneCN":"这里 carbon 是「碳元素」（第 1、2 个义项：化学元素与碳原子）；句意：这就是碳，所有生命背后的元素。图中可辨识物件：石墨片、碳棒、电路图、护目镜。","pos":[{"tag":"n.","zh":"碳；碳元素；复写纸；碳棒"},{"tag":"adj.","zh":"碳的；含碳的（多用于复合词）"}],"collocations":[{"phrase":"carbon dioxide","zh":"二氧化碳"},{"phrase":"carbon emissions","zh":"碳排放"},{"phrase":"carbon footprint","zh":"碳足迹"},{"phrase":"carbon dating","zh":"碳定年法"},{"phrase":"carbon fiber","zh":"碳纤维"},{"phrase":"carbon copy","zh":"复写副本；抄送件"}],"forms":[{"label":"单数","form":"carbon"},{"label":"复数（碳原子／复写副本）","form":"carbons"},{"label":"元素符号","form":"C"}],"derivatives":[{"word":"carbonic","pos":"adj.","zh":"碳的；碳酸的"},{"word":"carbonate","pos":"n.","zh":"碳酸盐"},{"word":"carbonize","pos":"vt.","zh":"使碳化；烧成炭"},{"word":"carbonated","pos":"adj.","zh":"含二氧化碳的；充气的"}],"senses":[{"no":"01","title":"The element carbon","titleCN":"化学元素碳","definition":"the non-metallic chemical element with atomic number 6 and the symbol C","definitionCN":"原子序数为 6、符号为 C 的非金属化学元素","example":"Diamond and graphite are both forms of carbon.","exampleCN":"金刚石与石墨都是碳的形式。","why":"The element was named after Latin carbo, 'charcoal', because it was first known in the form of soot and charcoal. The name of a material became the name of an element.","whyCN":"这种元素以拉丁语 carbo“木炭”命名，因为人类最早认识它时，它就是烟炱与木炭的形态。一个材料的名字变成了一种元素的名字。"},{"no":"02","title":"A carbon atom","titleCN":"碳原子","definition":"a single atom of carbon, especially as a unit in chemical formulas and structures","definitionCN":"单个碳原子，尤作为化学式与结构中的单位","example":"Each carbon atom in methane is bonded to four hydrogens.","exampleCN":"甲烷中的每个碳原子都与四个氢相连。","why":"Once the element is named, the same word counts its smallest unit. The material term becomes an atomic term without any suffix.","whyCN":"元素被命名之后，同一个词也开始计数它最小的单位。这个材料词不加任何后缀就变成了原子词。"},{"no":"03","title":"Carbon paper","titleCN":"复写纸","definition":"thin paper coated with a dark pigment, used to transfer writing through pressure","definitionCN":"涂有深色颜料、靠压力把字迹转印到下一层的薄纸","example":"She inserted a sheet of carbon between the two forms.","exampleCN":"她在两份表格之间夹了一张复写纸。","why":"The pigment was historically carbon black, a soot of nearly pure carbon. The material named the tool, and the tool kept the name after other pigments replaced it.","whyCN":"这种颜料历史上是炭黑，一种近乎纯碳的烟炱。材料命名了工具，后来即使别的颜料替代了它，工具仍保留这个名字。"},{"no":"04","title":"A carbon copy","titleCN":"复写副本","definition":"a copy of a document made with carbon paper, or any exact duplicate","definitionCN":"用复写纸制成的文件副本，或任何一模一样的复制品","example":"The letter was sent as a carbon copy to the manager.","exampleCN":"这封信以抄送件形式发给了经理。","why":"The copy exists because carbon pressed through the sheet. By extension, any exact duplicate, or any email copied to a second person, is called a carbon copy.","whyCN":"副本之所以存在，是因为碳透过纸面压了下去。引申开来，任何一模一样的复制品，或抄送给第二个人的邮件，都叫 carbon copy。"},{"no":"05","title":"A carbon rod or electrode","titleCN":"碳棒、碳电极","definition":"a rod of carbon used as an electrode or as the core of a dry cell battery","definitionCN":"用作电极或干电池芯的碳棒","example":"The old battery contained a carbon rod in the centre.","exampleCN":"这种旧电池中央有一根碳棒。","why":"Carbon conducts electricity and resists heat, so industry made it into rods. The element name is used directly for the shaped object.","whyCN":"碳导电且耐热，工业便把它做成棒状。元素名被直接用在成形物件上。"},{"no":"06","title":"Carbon black as a pigment","titleCN":"炭黑颜料","definition":"a fine black powder of carbon used in ink, paint and rubber","definitionCN":"用于油墨、涂料与橡胶的细黑碳粉","example":"The ink gets its deep black from carbon black.","exampleCN":"这种油墨的深黑来自炭黑。","why":"This is the oldest material sense: the soot that gave the element its Latin name. Here carbon is not an abstract element but a pigment you can hold.","whyCN":"这是最古老的材料义：给这种元素取拉丁名的烟炱。这里的碳不是抽象元素，而是可以拿在手里的颜料。"},{"no":"07","title":"Carbon dating","titleCN":"碳定年法","definition":"in archaeology and geology, the use of radiocarbon to estimate the age of organic remains","definitionCN":"考古与地质中利用放射性碳估算有机物年代的方法","example":"Carbon dating placed the bones at about 9,000 years old.","exampleCN":"碳定年把这些骨头的年代定在约九千年前。","why":"The adjective form names the method by its tool. Carbon is not the object dated; it is the clock inside the object.","whyCN":"形容词形态以工具命名方法。碳不是被定年的对象，而是对象内部的时钟。"},{"no":"08","title":"Carbon emissions and footprints","titleCN":"碳排放与碳足迹","definition":"in climate usage, carbon compounds released by human activity, especially carbon dioxide","definitionCN":"气候语境中指人类活动释放的碳化合物，尤指二氧化碳","example":"The city aims to cut its carbon footprint by half.","exampleCN":"这座城市目标是把碳足迹减半。","why":"Climate policy shortened 'carbon dioxide emissions' to 'carbon'. The element name now stands for the greenhouse gas, a common pattern of metonymy.","whyCN":"气候政策把“二氧化碳排放”缩略为 carbon。元素名现在代指温室气体，这是常见的转喻。"},{"no":"09","title":"Carbon-based life","titleCN":"碳基生命","definition":"in biology and science fiction, describing life whose molecules are built on carbon chains","definitionCN":"生物学与科幻中指分子建立在碳链之上的生命","example":"All known life on Earth is carbon-based.","exampleCN":"地球上已知的生命都是碳基的。","why":"Carbon forms four bonds and long chains, which is why it can build the molecules of life. The word becomes a label for a whole chemistry of living things.","whyCN":"碳能形成四个键与长链，因此能构建生命分子。这个词成了一整套生命化学的标签。"}],"etymology":{"intro":{"en":"Carbon is a Latin word for charcoal that was promoted to an element name at the end of the 18th century. The deepest Indo-European link is uncertain, so the earliest layer is marked as doubtful.","cn":"carbon 原本是拉丁语里“木炭”的词，在 18 世纪末被提升为元素名。它最深的印欧语联系并不确定，所以最早的一层标为存疑。"},"items":[{"era":"LATIN carbo","en":"Carbo, carbonis meant 'charcoal, a piece of burning coal, an ember'. It named the black residue of fire, not a chemical element, which did not yet exist as a concept.","cn":"carbo（属格 carbonis）意为“木炭、燃烧的煤块、余烬”。它命名的是火留下的黑色残余，而不是化学元素——当时还没有元素这个概念。"},{"era":"ORIGIN UNCERTAIN","en":"The deeper origin of carbo is not settled. Some references connect it with a root for burning or heat, but the reconstruction is not secure. This layer is source uncertain.","cn":"carbo 更深层的来源没有定论。有些资料把它连到表示“燃烧、热”的词根，但重构并不可靠。这一层来源存疑。"},{"era":"LATIN carbonarius","en":"Carbonarius meant 'of charcoal' and named the charcoal burner. The suffix -arius, 'belonging to a trade', is the ancestor of English -ary in words like ordinary.","cn":"carbonarius 意为“木炭的”，用来指烧炭人。后缀 -arius 表示“属于某种行业”，是英语 ordinary 等词中 -ary 的祖先。"},{"era":"FRENCH carbone 1789","en":"French chemists, including Lavoisier, needed a name for the newly identified element. They took Latin carbo and formed carbone, naming the element after the material it came from.","cn":"包括拉瓦锡在内的法国化学家需要给新确认的元素命名。他们取拉丁语 carbo 造出 carbone，以它所来自的材料命名这种元素。"},{"era":"1789 ENGLISH","en":"English carbon enters through the French term at the end of the 18th century. The symbol C comes from the Latin initial, keeping the old word visible in the periodic table.","cn":"英语 carbon 在 18 世纪末经法语术语进入。元素符号 C 取自拉丁词首字母，让这个古老的词在周期表中仍然可见。"},{"era":"19C.–MODERN ENGLISH","en":"Carbon paper and the carbon copy belong to the 19th century office. Carbon dating appears in the 1950s, and carbon footprint and carbon emissions become everyday climate terms at the end of the 20th century.","cn":"复写纸与复写副本属于 19 世纪的办公室。碳定年出现于 20 世纪 50 年代，碳足迹与碳排放则在 20 世纪末成为日常气候词汇。"}]},"similar":{"note":{"en":"The first group holds words close in spelling, including one true relative. The second group compares carbon with the materials and elements it is often confused with.","cn":"第一组是拼写接近的词，其中一个是真正的亲属。第二组把 carbon 与容易被混淆的材料和元素作比较。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"carbine","ipa":"/kɑːˈbiːn/","tag":"different root","definition":"a short rifle. It comes from French carabine, probably from carabin 'soldier', with no link to charcoal.","definitionCN":"短步枪。它来自法语 carabine，可能出自 carabin“士兵”，与木炭无关。"},{"word":"carbuncle","ipa":"/ˈkɑːbʌŋkl/","tag":"same root","definition":"a red gemstone, or a painful skin infection. Latin carbunculus was a diminutive of carbo, 'little coal', because the gem glowed like an ember.","definitionCN":"红色宝石，或疼痛的皮肤感染。拉丁语 carbunculus 是 carbo 的指小形式“小炭”，因为宝石像余烬一样发光。"},{"word":"carbonate","ipa":"/ˈkɑːbəneɪt/","tag":"derived","definition":"a salt containing the carbonate group. It is carbon plus -ate, a chemical suffix, not a separate root.","definitionCN":"含碳酸根的盐。它是 carbon 加化学后缀 -ate，不是另一个词根。"}]},{"heading":"NEAR MEANING","entries":[{"word":"charcoal","ipa":"/ˈtʃɑːkəʊl/","tag":"material","definition":"black porous material made by burning wood without air. It is mostly carbon, but the word names the material, not the element.","definitionCN":"隔绝空气烧木得到的黑色多孔材料。它主要是碳，但这个词命名材料，不是元素。"},{"word":"graphite","ipa":"/ˈɡræfaɪt/","tag":"form of carbon","definition":"a soft black form of carbon used in pencils. It is one allotrope of carbon, not a synonym for the element.","definitionCN":"用于铅笔的柔软黑色碳形态。它是碳的一种同素异形体，不是元素的同义词。"},{"word":"soot","ipa":"/suːt/","tag":"material","definition":"fine black particles from incomplete burning. It is largely carbon and was the old source of the element's name.","definitionCN":"不完全燃烧产生的细黑颗粒。它主要是碳，也是这种元素名称的古老来源。"},{"word":"coal","ipa":"/kəʊl/","tag":"fuel","definition":"a black rock used as fuel, rich in carbon. It is the substance, while carbon is the element extracted from it.","definitionCN":"用作燃料的黑色岩石，富含碳。它是物质，而 carbon 是从中提取的元素。"}]}]},"mnemonics":{"normalIntro":{"en":"These hooks move from the Latin charcoal word to the modern element and its compounds.","cn":"这些记忆钩从拉丁语的“木炭”走到现代元素及其化合物。"},"normal":[{"en":"Anchor in carbo, charcoal: carbon was named after the black stuff left by fire.","cn":"锚定 carbo“木炭”：碳是以火留下的黑色东西命名的。"},{"en":"Remember the symbol C is just the first letter of carbo.","cn":"记住元素符号 C 就是 carbo 的首字母。"},{"en":"Picture a pencil: graphite is carbon in a soft, layered form.","cn":"想象一支铅笔：石墨是碳的一种柔软层状形态。"},{"en":"Use the pair carbon paper and carbon copy: the copy exists because carbon pressed through.","cn":"用复写纸与复写副本这一对：副本之所以存在，是因为碳压了过去。"},{"en":"For climate, read carbon as shorthand for carbon dioxide.","cn":"在气候语境中，把 carbon 读作二氧化碳的简称。"}],"abstract":[{"en":"Hold one substance and watch it split into two histories: the material (charcoal, paper, rods) and the element (atoms, bonds, dating).","cn":"抓住一种物质，看它分成两条历史：材料（木炭、复写纸、碳棒）与元素（原子、化学键、定年）。"},{"en":"Sort the nine senses by scale: atom, element, material object, copy, pigment, method, gas, life.","cn":"按尺度分组九个义项：原子、元素、实物、副本、颜料、方法、气体、生命。"},{"en":"Remember the naming direction: material first, element second, metaphor last.","cn":"记住命名方向：先材料，再元素，最后比喻。"}]},"examples":[{"en":"Carbon is the fourth most abundant element in the universe.","cn":"碳是宇宙中含量第四高的元素。"},{"en":"The receipt was typed with carbon paper in triplicate.","cn":"收据用复写纸打了一式三份。"},{"en":"The government pledged to reduce carbon emissions by 2030.","cn":"政府承诺到 2030 年减少碳排放。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音“卡本”：想象一张“卡”在“本”子里，压一下留下黑印——那就是复写纸上的碳，carbon。","word":"carbon"},"root":"拉丁语 carbo（属格 carbonis）“木炭、余烬”，派生形容词 carbonarius“木炭的”；1789 年法国化学家据以造出 carbone，英语随后借入作元素名。更深的印欧语来源存疑。","sensesIntro":{"en":"Carbon has a double life: it is a material you can hold and an element you cannot see. Charcoal, paper, rods and pigment belong to the first life; atoms, dating, emissions and carbon-based life belong to the second. The word never needed a suffix to cross between them.","cn":"carbon 有双重生命：它是可以拿在手里的材料，也是看不见的元素。木炭、复写纸、碳棒、颜料属于第一种生命；原子、定年、排放、碳基生命属于第二种。这个词不需要任何后缀就在两者之间穿行。"},"semanticMap":{"core":{"en":"The black element of fire and life: charcoal in the hand, carbon in the atom.","cn":"火与生命的黑色元素：手里是木炭，原子里是碳。"},"chain":["CHARCOAL","ELEMENT","ATOM","MATERIAL","COPY","CLIMATE"],"branches":[{"senses":"S1 · S2 · S9","en":"THE ELEMENT: atoms, bonds, and the chemistry of living things.","cn":"元素：原子、化学键，以及生命的化学。"},{"senses":"S3 · S5 · S6","en":"THE MATERIAL: paper, rods and black pigment.","cn":"材料：复写纸、碳棒与黑色颜料。"},{"senses":"S4","en":"THE COPY: pressure transferred through carbon, then any duplicate.","cn":"副本：压力透过碳转印，随后泛指任何复制品。"},{"senses":"S7","en":"THE CLOCK: radiocarbon as a way of measuring time.","cn":"时钟：放射性碳作为测量时间的方式。"},{"senses":"S8","en":"THE GAS: carbon as shorthand for carbon dioxide in climate talk.","cn":"气体：气候话语中 carbon 作为二氧化碳的简称。"}]},"affixes":{"intro":{"en":"Carbon takes the chemical suffixes -ic, -ate and -ize, and combines with -ferous and with nouns such as copy and footprint. The list shows both the Latin base and the modern compounds.","cn":"carbon 接化学后缀 -ic、-ate、-ize，也能与 -ferous 以及 copy、footprint 等名词组合。清单同时展示拉丁词基与现代复合词。"},"latinIntro":{"en":"The Latin entries give charcoal, the charcoal-burner's adjective, and the diminutive 'little coal' that survives in carbuncle.","cn":"拉丁语条目给出木炭、烧炭人的形容词，以及在 carbuncle 中存活的指小形式“小炭”。"},"items":[{"word":"carbon","structure":"Latin carbo (charcoal), through French carbone","meaning":"the element carbon; carbon paper; a copy","meaningCN":"碳元素；复写纸；副本","example":"Carbon forms long chains.","exampleCN":"碳能形成长链。"},{"word":"carbonic","structure":"carbon + -ic (adjective suffix)","meaning":"relating to carbon, especially in carbonic acid","meaningCN":"碳的；碳酸的","example":"Carbonic acid forms when carbon dioxide dissolves.","exampleCN":"二氧化碳溶解时形成碳酸。"},{"word":"carbonate","structure":"carbon + -ate (chemical noun and verb suffix)","meaning":"a salt of carbonic acid; to add carbon dioxide","meaningCN":"碳酸盐；使碳酸化","example":"Limestone is largely calcium carbonate.","exampleCN":"石灰石主要是碳酸钙。"},{"word":"carbonize","structure":"carbon + -ize (verb suffix)","meaning":"to turn into carbon or charcoal","meaningCN":"使碳化；烧成炭","example":"Heat carbonizes the wood.","exampleCN":"高温使木材碳化。"},{"word":"carbonization","structure":"carbonize + -ation (process noun)","meaning":"the process of becoming carbon","meaningCN":"碳化过程","example":"Carbonization preserves the shape of the original plant.","exampleCN":"碳化保留了原植物的形状。"},{"word":"carbonated","structure":"carbonate + -ed (past participle adjective)","meaning":"containing dissolved carbon dioxide","meaningCN":"含二氧化碳的；充气的","example":"She prefers carbonated water to still water.","exampleCN":"比起无气泡的水，她更喜欢气泡水。"},{"word":"carboniferous","structure":"carbon + -ferous (bearing, from ferre)","meaning":"coal-bearing; also the geological period named for coal beds","meaningCN":"含煤的；石炭纪的","example":"The Carboniferous period left vast coal deposits.","exampleCN":"石炭纪留下了大量煤层。"},{"word":"carbon copy","structure":"carbon + copy (compound noun)","meaning":"a copy made with carbon paper; an exact duplicate","meaningCN":"复写副本；一模一样的复制品","example":"Send a carbon copy to the archive.","exampleCN":"把副本抄送到档案室。"},{"word":"carbon footprint","structure":"carbon + footprint (compound noun)","meaning":"the amount of greenhouse gas a person or activity produces","meaningCN":"碳足迹","example":"Flying increases your carbon footprint.","exampleCN":"乘飞机会增加你的碳足迹。"},{"word":"carbon dating","structure":"carbon + dating (compound noun)","meaning":"radiocarbon dating of organic material","meaningCN":"碳定年法","example":"Carbon dating confirmed the age of the wood.","exampleCN":"碳定年确认了这块木头的年代。"}],"latinEntries":[{"word":"carbo","structure":"root noun (3rd declension, carbonis)","meaning":"charcoal, ember","meaningCN":"木炭；余烬"},{"word":"carbonarius","structure":"carbo + -arius (trade suffix)","meaning":"of charcoal; a charcoal burner","meaningCN":"木炭的；烧炭人"},{"word":"carbunculus","structure":"carbo + -unculus (diminutive)","meaning":"small coal; a glowing gem","meaningCN":"小炭；发光的宝石"}]}},{"word":"catalyst","ipa_uk":"/ˈkætəlɪst/","ipa_us":"/ˈkætəlɪst/","definition_zh":"催化剂；触媒；促进因素；引发变革的人或事","definition_en":"a substance that speeds up a chemical reaction without being consumed, or a person or event that causes change","core_image":"一块垫脚石：它自己不走路，却让别人跨过原本过不去的高墙","scene":"老师往双氧水里撒了一小撮二氧化锰，液体立刻翻腾起来。她说：The powder is a catalyst; it is still there when the reaction ends.","sceneCN":"这里 catalyst 是「催化剂」（第 1、5 个义项：化学催化与不被消耗的物质）；句意：这粉末是催化剂，反应结束时它还在。图中可辨识物件：试管、气泡、黑色粉末、护目镜。","pos":[{"tag":"n.","zh":"催化剂；触媒；促进因素"}],"collocations":[{"phrase":"a catalyst for change","zh":"变革的催化剂"},{"phrase":"chemical catalyst","zh":"化学催化剂"},{"phrase":"act as a catalyst","zh":"起催化作用"},{"phrase":"enzyme catalyst","zh":"酶催化剂"},{"phrase":"catalyst surface","zh":"催化剂表面"},{"phrase":"catalyst for reform","zh":"改革的催化剂"}],"forms":[{"label":"单数","form":"catalyst"},{"label":"复数","form":"catalysts"}],"derivatives":[{"word":"catalysis","pos":"n.","zh":"催化作用"},{"word":"catalytic","pos":"adj.","zh":"催化的"},{"word":"catalyze","pos":"vt.","zh":"催化；促成"},{"word":"catalytically","pos":"adv.","zh":"以催化方式"}],"senses":[{"no":"01","title":"A substance that speeds a reaction","titleCN":"加快反应的物质","definition":"a substance that increases the rate of a chemical reaction without being used up by it","definitionCN":"能加快化学反应速率、而自身不被消耗的物质","example":"Platinum is an effective catalyst for this reaction.","exampleCN":"铂是这一反应的有效催化剂。","why":"Greek katalyein meant 'to dissolve down', to loosen what holds something together. A catalyst loosens the barrier between reactants, so the reaction runs without it being consumed.","whyCN":"希腊语 katalyein 意为“向下溶解”，把束缚某物的东西松开。催化剂松开反应物之间的障碍，因此反应得以进行，而它自己不被消耗。"},{"no":"02","title":"A biological catalyst: an enzyme","titleCN":"生物催化剂：酶","definition":"a protein or other molecule in a living cell that speeds up a biochemical reaction","definitionCN":"活细胞中加快生化反应的蛋白质或其他分子","example":"The enzyme acts as a catalyst for the breakdown of starch.","exampleCN":"这种酶作为催化剂促进淀粉分解。","why":"Living cells perform the same trick at body temperature. The word transfers from the laboratory bench to the cell, but the function is identical.","whyCN":"活细胞在体温下做着同样的把戏。这个词从实验台转移到细胞里，但功能完全相同。"},{"no":"03","title":"A person who makes things happen","titleCN":"促成事情发生的人","definition":"a person who causes or speeds up a change without being the main actor","definitionCN":"促成或加速变化、而自身并非主角的人","example":"She was the catalyst who brought the two sides together.","exampleCN":"她正是把双方拉到一起的促成者。","why":"The chemical image transfers cleanly to people: someone lowers the barrier between parties, then steps aside. The person is not the reaction, only its enabler.","whyCN":"化学意象干净地转移到人身上：某人降低双方之间的障碍，然后退到一旁。这个人不是反应本身，只是它的促成者。"},{"no":"04","title":"An event that sets off change","titleCN":"引发变化的事件","definition":"an event or development that triggers a larger process of change","definitionCN":"触发更大变化过程的事件或发展","example":"The report became a catalyst for new legislation.","exampleCN":"这份报告成了新立法的催化剂。","why":"The event plays the role of the substance: it starts something larger without being the substance of that larger thing. History is imagined as a reaction waiting for a spark.","whyCN":"事件扮演物质的角色：它启动了更大的事情，而自身并不构成那件事的实体。历史被想象成一个等待火花的反应。"},{"no":"05","title":"Something that is not consumed","titleCN":"自身不被消耗的催化剂","definition":"a substance whose mass and composition remain essentially unchanged after the reaction","definitionCN":"反应之后质量与成分基本不变的物质","example":"The catalyst can be filtered out and used again.","exampleCN":"催化剂可以滤出并再次使用。","why":"This is the defining property: the looser is not loosened. The word's usefulness in chemistry depends on this distinction from a reactant, which is consumed.","whyCN":"这是定义性的特征：松开别的物质者本身不被松开。这个化学术语的有用之处，正在于它区别于会被消耗的反应物。"},{"no":"06","title":"The core of a catalytic converter","titleCN":"催化转化器的催化芯","definition":"the active material inside a device that cleans exhaust gases, often platinum or another metal","definitionCN":"净化废气装置中的活性材料，常为铂等金属","example":"The mechanic replaced the catalyst in the exhaust system.","exampleCN":"修理工更换了排气系统中的催化芯。","why":"The device is named for its function, and the catalyst is its functional centre. Everyday car repair made the laboratory term into a replaceable part.","whyCN":"这个装置以功能命名，而催化剂是它的功能核心。日常修车把一个实验室术语变成了可更换的零件。"},{"no":"07","title":"A policy catalyst","titleCN":"政策催化剂","definition":"in policy and economics, a measure designed to encourage investment or activity that would not otherwise occur","definitionCN":"政策与经济中，为鼓励原本不会发生的投资或活动而设计的措施","example":"The tax credit was intended as a catalyst for private investment.","exampleCN":"这项税收抵免意在成为私人投资的催化剂。","why":"Government money is meant to lower the barrier, not to do the investing itself. The term gives policy a chemical shape: small input, large reaction.","whyCN":"政府的钱意在降低障碍，而不是亲自投资。这个术语给政策一个化学形状：小投入，大反应。"},{"no":"08","title":"A character who drives the plot","titleCN":"推动情节的角色","definition":"in literature and drama, a character whose action sets the main conflict in motion","definitionCN":"文学与戏剧中，其行动启动主要冲突的角色","example":"The messenger is the catalyst of the tragedy.","exampleCN":"那个报信人是这场悲剧的催化剂。","why":"A play needs someone to lower the barrier between ordinary life and conflict. Critics borrowed the chemical word because it describes function, not importance.","whyCN":"戏剧需要有人降低日常与冲突之间的障碍。评论家借用这个化学词，因为它描述的是功能，而不是重要性。"},{"no":"09","title":"A spark for a chain of events","titleCN":"连锁事件的导火索","definition":"a small trigger that sets off a sequence of much larger consequences","definitionCN":"引发一连串更大后果的小触发点","example":"A single rumour proved to be the catalyst of the riot.","exampleCN":"一则谣言成了那场骚乱的导火索。","why":"This is the loosest but most vivid extension: the catalyst is small, the chain is large. The word now measures disproportion between cause and effect.","whyCN":"这是最宽松也最生动的延伸：催化剂很小，链式后果很大。这个词如今度量的是因与果之间的不对称。"}],"etymology":{"intro":{"en":"Catalyst is a modern scientific coinage built from Greek parts. Its second element is not Latin and not English; it is Greek lyein, 'to loosen', the same root seen in analysis and electrolysis.","cn":"catalyst 是一个现代科学造词，由希腊语部件构成。它的第二成分不是拉丁语，也不是英语，而是希腊语 lyein“松开”，与 analysis、electrolysis 共享同一词根。"},"items":[{"era":"GREEK kata-","en":"Kata- meant 'down, downwards, against'. It is the prefix in catalogue, catastrophe and category, and it gives the first element of katalysis.","cn":"kata- 意为“向下、向下、对着”。它是 catalogue、catastrophe、category 中的前缀，也构成 katalysis 的第一部分。"},{"era":"GREEK lyein","en":"Lyein meant 'to loosen, untie, dissolve'. Its noun lysis, 'a loosening', is the second element of catalyst and the whole of the suffix -lysis in analysis and paralysis.","cn":"lyein 意为“松开、解开、溶解”。其名词 lysis“松开”是 catalyst 的第二部分，也是 analysis、paralysis 中整个后缀 -lysis 的来源。"},{"era":"GREEK katalysis","en":"Katalysis meant 'a dissolving, a dissolution'. It described something being loosened down, not yet a chemical accelerator.","cn":"katalysis 意为“溶解、消解”。它描述某物被向下松开，还不是化学上的加速剂。"},{"era":"1835 CHEMISTRY","en":"The Swedish chemist Berzelius coined French and German terms for the phenomenon from Greek katalysis. The idea was that a substance loosens the bonds of others without being loosened itself.","cn":"瑞典化学家贝采利乌斯在 1835 年据希腊语 katalysis 造出法语与德语术语来命名这一现象。其想法是：某物质松开别的物质的键，而自身不被松开。"},{"era":"LATE 19C. catalyst","en":"Catalyst was formed on the model of analysis and analyst, adding -ist for the agent. The exact date of the English coinage is approximate; it enters general use around 1900.","cn":"catalyst 仿照 analysis 与 analyst 的模型，用 -ist 表示施动者。英语造词的确切年代为大致估计，约在 1900 年前后进入通用。"},{"era":"MODERN ENGLISH","en":"The chemical term spread into economics, politics and literary criticism in the 20th century. The metaphor is always the same: a small, unchanged enabler of a large change.","cn":"这个化学术语在 20 世纪扩散到经济、政治与文学批评。比喻始终如一：一个自身不变的小小促成者，带来巨大的变化。"}]},"similar":{"note":{"en":"The first group separates catalyst from its own derivatives and from a Greek-look-alike that comes from a different root. The second group compares things that cause change.","cn":"第一组把 catalyst 与自身派生词、以及来自另一词根的希腊式形近词分开。第二组比较引发变化的事物。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"catalysis","ipa":"/kəˈtæləsɪs/","tag":"derived noun","definition":"the process of accelerating a reaction, named before the agent. It is the process, while catalyst is the substance.","definitionCN":"加快反应的过程，先于施动者被命名。它是过程，而 catalyst 是物质。"},{"word":"catalytic","ipa":"/ˌkætəˈlɪtɪk/","tag":"derived adjective","definition":"relating to catalysis. It describes the process or a device, not the substance itself.","definitionCN":"与催化有关的。它描述过程或装置，而不是物质本身。"},{"word":"catapult","ipa":"/ˈkætəpʌlt/","tag":"different root","definition":"a device for throwing stones. Its second element is peltē 'shield' or pallein 'to hurl', not lyein.","definitionCN":"投石装置。其第二成分是 peltē“盾”或 pallein“投掷”，不是 lyein。"}]},{"heading":"NEAR MEANING","entries":[{"word":"enzyme","ipa":"/ˈenzaɪm/","tag":"biological","definition":"a protein that catalyses a biochemical reaction. It is a kind of catalyst, but only in living systems.","definitionCN":"催化生化反应的蛋白质。它是催化剂的一种，但只存在于生命系统中。"},{"word":"trigger","ipa":"/ˈtrɪɡə(r)/","tag":"sudden cause","definition":"an event that sets something off at once. It stresses the sudden start, while catalyst stresses the enabling role.","definitionCN":"立刻引发某事的事件。它强调突然启动，而 catalyst 强调促成作用。"},{"word":"spark","ipa":"/spɑːk/","tag":"metaphor","definition":"a small thing that starts a large process. It is more literary and more sudden than catalyst.","definitionCN":"启动大过程的小事物。它比 catalyst 更文学化、更突然。"},{"word":"reagent","ipa":"/riˈeɪdʒənt/","tag":"chemistry","definition":"a substance used in a reaction, which is consumed. It is the opposite role to a catalyst, which is not consumed.","definitionCN":"参与反应并被消耗的物质。它与催化剂角色相反，后者不被消耗。"}]}]},"mnemonics":{"normalIntro":{"en":"These hooks separate the Greek parts kata and lysis, and keep the two roles, substance and enabler, distinct.","cn":"这些记忆钩把希腊部件 kata 与 lysis 分开，也把“物质”与“促成者”两种角色分清。"},"normal":[{"en":"Split it as kata + lyst: a downward loosener, not a cat and not a list.","cn":"拆成 kata 加 lyst：向下的松开者，既不是猫，也不是清单。"},{"en":"Link it to analysis: the -lysis part means loosening, so a catalyst loosens a barrier.","cn":"把它连到 analysis：-lysis 表示松开，所以 catalyst 松开障碍。"},{"en":"Remember the defining test: it comes out unchanged, ready to be used again.","cn":"记住定义性检验：它出来时不变，可以再次使用。"},{"en":"For people, picture someone holding a door open and then stepping aside.","cn":"用在人身上，想象某人把门撑开，然后退到一旁。"},{"en":"Keep catalyst and reactant apart: one is reused, the other is used up.","cn":"把 catalyst 与 reactant 分开：一个被重复使用，一个被用尽。"}],"abstract":[{"en":"Hold one function: lower the barrier, do not become the reaction.","cn":"抓住一个功能：降低障碍，不成为反应本身。"},{"en":"Sort the senses by field: chemistry, biology, people, events, devices, policy, drama, chains of consequence.","cn":"按领域分组义项：化学、生物、人、事件、装置、政策、戏剧、连锁后果。"},{"en":"Remember the direction of the metaphor: from a substance to a role, never to a mere cause.","cn":"记住比喻方向：从一种物质到一种角色，而不只是“原因”。"}]},"examples":[{"en":"The catalyst lowers the activation energy of the reaction.","cn":"催化剂降低了反应的活化能。"},{"en":"Her speech was the catalyst for a nationwide debate.","cn":"她的演讲引发了全国性的讨论。"},{"en":"Enzymes are catalysts that work at body temperature.","cn":"酶是在体温下工作的催化剂。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音“开特利斯特”：想象“开”一扇“特”别重的门，靠一块“利”器“斯特”别省力——它就是 catalyst 催化剂。","word":"catalyst"},"root":"希腊语 katalysis“溶解、消解”，由 kata-“向下、对着”加 lyein“松开、溶解”构成；1835 年贝采利乌斯据以造出催化术语，英语 catalyst 仿 analysis／analyst 加 -ist。与 analysis、electrolysis、paralysis 共享 -lysis。","sensesIntro":{"en":"A catalyst is defined by a role, not by a substance: it lowers a barrier without becoming the thing that crosses it. Chemistry gave the word its precision, and every later use, from enzymes to reformers to plot devices, keeps that role intact. The nine senses differ mainly in what is being enabled.","cn":"catalyst 由角色而非物质定义：它降低障碍，而不成为跨越障碍的那件事。化学给了这个词精确性，后来从酶到改革者再到情节装置，每次使用都保留这个角色。九个义项的主要差别在于“被促成的是什么”。"},"semanticMap":{"core":{"en":"Lower the barrier but stay outside the reaction: the unchanged enabler.","cn":"降低障碍而置身反应之外：自身不变的促成者。"},"chain":["LOOSEN","LOWER","ACCELERATE","ENABLE","TRIGGER","CHANGE"],"branches":[{"senses":"S1 · S5","en":"CHEMISTRY: the substance that speeds a reaction and survives it.","cn":"化学：加快反应并在反应后存留的物质。"},{"senses":"S2","en":"BIOLOGY: the enzyme doing the same work inside a cell.","cn":"生物：在细胞内做同样工作的酶。"},{"senses":"S3 · S7 · S8","en":"AGENTS: a person, a policy or a character who enables others to act.","cn":"施动者：促成他人行动的人、政策或角色。"},{"senses":"S4 · S9","en":"IGNITION: an event or rumour that starts a much larger chain.","cn":"点火：启动更大链条的事件或谣言。"},{"senses":"S6","en":"THE DEVICE: the active core of a catalytic converter.","cn":"装置：催化转化器中的活性核心。"}]},"affixes":{"intro":{"en":"Catalyst is not built with Latin affixes but with Greek combining elements. The list shows -lysis across its relatives, and the modern suffixes -ic, -ize and -ly that grew on the English word.","cn":"catalyst 不是用拉丁词缀构成的，而是用希腊语组合成分。清单展示 -lysis 在各亲属词中的形态，以及英语词上长出的现代后缀 -ic、-ize、-ly。"},"latinIntro":{"en":"There is no native Latin ancestor. The entries below are Latinized Greek borrowings: the learned Latin forms of lysis, analysis and catalysis, which carried the Greek root into European scientific vocabulary.","cn":"没有本族拉丁语祖先。下列条目是拉丁化的希腊借词：lysis、analysis、catalysis 的学术拉丁形式，它们把希腊词根带进了欧洲科学词汇。"},"items":[{"word":"catalyst","structure":"kata- (down) + lysis (loosening) + -ist (agent)","meaning":"a substance or agent that speeds up change","meaningCN":"加快变化的物质或施动者","example":"The catalyst remained unchanged.","exampleCN":"催化剂保持不变。"},{"word":"catalysis","structure":"kata- + lysis (process noun)","meaning":"the process of accelerating a reaction","meaningCN":"催化作用；催化过程","example":"Catalysis is central to industrial chemistry.","exampleCN":"催化是工业化学的核心。"},{"word":"catalytic","structure":"catalyst + -ic (adjective suffix)","meaning":"relating to catalysis","meaningCN":"催化的","example":"The car has a catalytic converter.","exampleCN":"这辆车装有催化转化器。"},{"word":"catalyze","structure":"catalyst + -yze (verb suffix, from lyein)","meaning":"to act as a catalyst for","meaningCN":"催化；促成","example":"The enzyme catalyzes the reaction.","exampleCN":"这种酶催化该反应。"},{"word":"catalytically","structure":"catalytic + -ally (adverb suffix)","meaning":"by means of catalysis","meaningCN":"以催化方式","example":"The gas is cleaned catalytically.","exampleCN":"这种气体经催化净化。"},{"word":"analysis","structure":"ana- (up, apart) + lysis","meaning":"a loosening apart; a detailed examination","meaningCN":"分解；分析","example":"The analysis broke the problem into parts.","exampleCN":"分析把问题拆成了几个部分。"},{"word":"electrolysis","structure":"electro- (electricity) + lysis","meaning":"chemical decomposition by electric current","meaningCN":"电解","example":"Electrolysis splits water into hydrogen and oxygen.","exampleCN":"电解把水分解成氢和氧。"},{"word":"hydrolysis","structure":"hydro- (water) + lysis","meaning":"chemical breakdown by water","meaningCN":"水解","example":"Hydrolysis breaks the polymer into monomers.","exampleCN":"水解把聚合物分解为单体。"},{"word":"biocatalyst","structure":"bio- (life) + catalyst","meaning":"a catalyst produced by a living system","meaningCN":"生物催化剂","example":"The biocatalyst works at low temperature.","exampleCN":"这种生物催化剂在低温下工作。"},{"word":"catalyst bed","structure":"catalyst + bed (compound noun)","meaning":"the layer of catalyst material in a reactor","meaningCN":"催化剂床层","example":"Gas passes through the catalyst bed.","exampleCN":"气体通过催化剂床层。"}],"latinEntries":[{"word":"lysis","structure":"Latinized Greek noun","meaning":"a loosening, dissolution","meaningCN":"松开；溶解"},{"word":"analysis","structure":"ana- + lysis (Latinized Greek)","meaning":"a loosening up; resolution into parts","meaningCN":"分解；分析"},{"word":"catalysis","structure":"kata- + lysis (Latinized Greek)","meaning":"a dissolving down; catalytic action","meaningCN":"消解；催化作用"}]}},{"word":"catalytic","ipa_uk":"/ˌkætəˈlɪtɪk/","ipa_us":"/ˌkætəˈlɪtɪk/","definition_zh":"催化的；起催化作用的；催化性的；有促进作用的","definition_en":"relating to or acting as a catalyst, or describing a device or process that uses catalysis","core_image":"一层薄薄的金属涂层：废气穿过它，分子被拆开重组，涂层本身却毫发无损","scene":"修车厂里，师傅指着排气管中段说：This is the catalytic converter; the honeycomb inside is coated with platinum. ","sceneCN":"这里 catalytic 是「催化的、催化式的」（第 1、2 个义项：催化作用与催化转化器）；句意：这是催化转化器，里面的蜂窝状载体镀了铂。图中可辨识物件：排气管、蜂窝载体、铂涂层、扳手。","pos":[{"tag":"adj.","zh":"催化的；起催化作用的"},{"tag":"adj.","zh":"（比喻）有促进作用的；促成变化的"}],"collocations":[{"phrase":"catalytic converter","zh":"催化转化器"},{"phrase":"catalytic cracking","zh":"催化裂化"},{"phrase":"catalytic activity","zh":"催化活性"},{"phrase":"catalytic reaction","zh":"催化反应"},{"phrase":"catalytic site","zh":"催化位点"},{"phrase":"catalytic properties","zh":"催化性质"}],"forms":[{"label":"原级（形容词）","form":"catalytic"},{"label":"比较级（更具催化作用）","form":"more catalytic"},{"label":"最高级（最具催化作用）","form":"most catalytic"},{"label":"异体拼写（较少用）","form":"catalytical"}],"derivatives":[{"word":"catalytically","pos":"adv.","zh":"以催化方式；通过催化作用"},{"word":"catalysis","pos":"n.","zh":"催化作用"},{"word":"catalyst","pos":"n.","zh":"催化剂"},{"word":"catalyze","pos":"vt.","zh":"催化；促成"}],"senses":[{"no":"01","title":"Relating to catalysis","titleCN":"与催化作用有关的","definition":"concerning the process by which a substance speeds up a reaction without being consumed","definitionCN":"关于某物质加快反应而自身不被消耗这一过程的","example":"The team studies catalytic processes for making fertilizer.","exampleCN":"这个团队研究制造肥料的催化过程。","why":"Catalytic is simply catalyst plus the adjective suffix -ic. Its first job is to name the whole domain of catalysis, without pointing to any particular substance.","whyCN":"catalytic 就是 catalyst 加形容词后缀 -ic。它最初的任务是命名催化这一整个领域，而不指向某种具体物质。"},{"no":"02","title":"The catalytic converter","titleCN":"催化转化器","definition":"describing an exhaust device that uses a catalyst to turn harmful gases into less harmful ones","definitionCN":"描述用催化剂把有害气体转为较无害气体的排气装置","example":"Cars sold here must have a catalytic converter.","exampleCN":"这里销售的汽车必须装有催化转化器。","why":"The adjective became a fixed part of the device's name. A converter is not itself a catalyst; it is a container whose work is catalytic.","whyCN":"这个形容词成了装置名称的固定部分。转化器本身不是催化剂，它是一个容器，而它的工作是催化的。"},{"no":"03","title":"Catalytic cracking in refining","titleCN":"炼油中的催化裂化","definition":"describing the refinery process that breaks heavy oil into lighter fuels with the help of a catalyst","definitionCN":"描述炼油中借助催化剂把重油裂解为轻质燃料的过程","example":"Catalytic cracking increased the yield of petrol.","exampleCN":"催化裂化提高了汽油产率。","why":"The process is named by its means, not its product. Cracking was already a thermal process; adding a catalyst changed the name and the economics.","whyCN":"这个过程以手段而非产物命名。裂化原本是热过程；加入催化剂改变了名称，也改变了经济性。"},{"no":"04","title":"Acting as an enabler","titleCN":"起促成作用的（比喻）","definition":"in general usage, describing something that makes a change possible without being the main cause","definitionCN":"一般用法中描述使变化成为可能、而自身不是主因的事物","example":"The treaty had a catalytic effect on regional trade.","exampleCN":"这项条约对区域贸易产生了催化作用。","why":"The metaphor keeps the chemistry exact: the adjective describes a role, not a magnitude. A catalytic event is small relative to what it sets off.","whyCN":"这个比喻保持了化学的精确：形容词描述的是角色，不是大小。一个催化性事件相对于它所启动的事情而言是小的。"},{"no":"05","title":"Having catalytic properties","titleCN":"具有催化性质的","definition":"of a material or surface, able to accelerate a reaction because of its own structure","definitionCN":"指材料或表面因自身结构而能加快反应","example":"The nanoparticles have strong catalytic properties.","exampleCN":"这些纳米颗粒具有很强的催化性质。","why":"Here the adjective moves from the process to the material. A surface is catalytic when the reaction happens on it, at its active sites.","whyCN":"这里形容词从过程转向材料。当反应在其活性位点上发生时，这个表面就是催化的。"},{"no":"06","title":"Driving economic growth","titleCN":"推动经济增长的","definition":"in economics, describing an investment or sector that stimulates further activity","definitionCN":"经济中指刺激更多活动的投资或部门","example":"Infrastructure spending has a catalytic role in the economy.","exampleCN":"基础设施支出在经济中具有催化作用。","why":"Investment is imagined as a substance that lowers the barrier to other investment. The adjective marks leverage rather than size.","whyCN":"投资被想象成一种降低其他投资障碍的物质。这个形容词标示的是杠杆作用，而不是规模。"},{"no":"07","title":"Setting off social change","titleCN":"触发社会变化的","definition":"describing an event, person or idea that starts a wider movement","definitionCN":"描述启动更广泛运动的事件、人或观念","example":"The photograph played a catalytic role in the reform movement.","exampleCN":"这张照片在改革运动中起了催化作用。","why":"The barrier here is social inertia. A catalytic idea does not do the organising; it makes organising possible.","whyCN":"这里的障碍是社会惰性。一个催化性的观念并不亲自组织，它使组织成为可能。"},{"no":"08","title":"Enzyme-catalysed","titleCN":"酶催化的","definition":"in biochemistry, describing a reaction that takes place with the help of an enzyme","definitionCN":"生物化学中描述在酶帮助下发生的反应","example":"The pathway consists of several enzyme-catalytic steps.","exampleCN":"这条途径由若干酶催化的步骤组成。","why":"The adjective attaches to the step, not the enzyme. A catalytic step is one whose rate is governed by a biological catalyst.","whyCN":"形容词附着在步骤上，而不是酶上。一个催化步骤，就是速率由生物催化剂支配的步骤。"},{"no":"09","title":"Taking place under catalysis","titleCN":"在催化作用下发生的","definition":"describing a reaction or transformation that requires a catalyst to proceed at a useful rate","definitionCN":"描述需要催化剂才能以有用速率进行的反应或转化","example":"The industrial route is entirely catalytic.","exampleCN":"这条工业路线完全是催化式的。","why":"This sense is the most technical and the least metaphorical: the adjective classifies a reaction by its mechanism. Without the catalyst, the rate would be impractically slow.","whyCN":"这一义最技术化、最少比喻：形容词按机理给反应分类。没有催化剂，速率会慢到无法实用。"}],"etymology":{"intro":{"en":"Catalytic is one step downstream from catalyst: the noun plus the adjective suffix -ic. Its history is therefore shorter than the history of catalysis, and its interest lies in how a suffix turned a substance into a whole class of processes and devices.","cn":"catalytic 是 catalyst 下游的一步：名词加形容词后缀 -ic。因此它的历史比 catalysis 短，而它的趣味在于：一个后缀如何把一种物质变成一整类过程与装置。"},"items":[{"era":"GREEK lyein","en":"The root lyein 'to loosen' supplies the -lyt- inside catalytic. The same root appears in analysis, electrolysis and hydrolysis.","cn":"词根 lyein“松开”提供了 catalytic 内部的 -lyt-。同一词根出现在 analysis、electrolysis、hydrolysis 中。"},{"era":"1835 catalysis","en":"Berzelius coined catalysis from Greek katalysis for the phenomenon of accelerating a reaction without being consumed. The process was named before any single agent had a name.","cn":"贝采利乌斯在 1835 年据希腊语 katalysis 造出 catalysis，命名“加快反应而自身不被消耗”的现象。过程先于任何单一施动者获得名称。"},{"era":"LATE 19C. catalyst","en":"Catalyst was formed later, on the model of analysis and analyst, to name the substance itself. Only after the noun existed could an adjective be built on it.","cn":"catalyst 更晚出现，仿照 analysis 与 analyst 的模型，用来命名物质本身。只有名词存在之后，才能在其上构成形容词。"},{"era":"19C. catalyst + -ic","en":"Catalytic is catalyst plus -ic, from Greek -ikos through Latin -icus, meaning 'belonging to, having the nature of'. The adjective first meant simply 'of a catalyst'.","cn":"catalytic 是 catalyst 加 -ic，后者经拉丁语 -icus 来自希腊语 -ikos，意为“属于……的、具有……性质的”。这个形容词最初只表示“属于催化剂的”。"},{"era":"20C. TECHNICAL COMPOUNDS","en":"The adjective became a fixed element in names of hardware and processes: catalytic converter, catalytic cracking, catalytic site. Each compound names an object or step by the role catalysis plays in it.","cn":"这个形容词成了硬件与工艺名称中的固定成分：催化转化器、催化裂化、催化位点。每个复合词都按催化在其中扮演的角色来命名对象或步骤。"},{"era":"MODERN ENGLISH","en":"Since the mid-20th century catalytic has also worked outside chemistry, describing investments, policies and people that enable change. The suffix now marks a role rather than a substance.","cn":"自 20 世纪中期起，catalytic 也走出化学，用来描述促成变化的投资、政策与人。这个后缀如今标示的是一种角色，而不是一种物质。"}]},"similar":{"note":{"en":"The first group is mostly family: base noun, rare variant, and one Greek-look-alike from a different root. The second group compares words for enabling change.","cn":"第一组主要是同族词：基础名词、罕见异体，以及一个来自别的词根的希腊式形近词。第二组比较“促成变化”类词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"catalyst","ipa":"/ˈkætəlɪst/","tag":"base noun","definition":"the substance or agent itself. Catalytic describes it or its role; catalyst names it.","definitionCN":"物质或施动者本身。catalytic 描述它或其角色，catalyst 命名它。"},{"word":"catalytical","ipa":"/ˌkætəˈlɪtɪkl/","tag":"rare variant","definition":"an older and rarer adjective form with -al added to -ic. It means the same as catalytic.","definitionCN":"在 -ic 上再加 -al 的较旧、较罕见形容词形式，意义与 catalytic 相同。"},{"word":"catapult","ipa":"/ˈkætəpʌlt/","tag":"different root","definition":"a stone-throwing engine. Its second element has nothing to do with loosening, despite the shared kata- beginning.","definitionCN":"投石机。尽管同样以 kata- 开头，其第二成分与“松开”无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"instrumental","ipa":"/ˌɪnstrəˈmentl/","tag":"role","definition":"important in causing something to happen. It stresses usefulness to an outcome, while catalytic stresses the enabling mechanism.","definitionCN":"在促成某事上起重要作用的。它强调对结果的用处，而 catalytic 强调促成机制。"},{"word":"causative","ipa":"/ˈkɔːzətɪv/","tag":"cause","definition":"acting as the cause of something. It is stronger and more direct than catalytic, which implies a lowered barrier rather than a sole cause.","definitionCN":"作为某事的成因起作用的。它比 catalytic 更强、更直接，后者暗示降低障碍而非唯一原因。"},{"word":"conducive","ipa":"/kənˈdjuːsɪv/","tag":"favourable","definition":"tending to help something happen. It describes a favourable condition, not an active agent.","definitionCN":"有助于某事发生的。它描述有利条件，而非主动施动者。"},{"word":"enabling","ipa":"/ɪˈneɪblɪŋ/","tag":"permission","definition":"giving someone the means or authority to act. It is broader than catalytic and often institutional.","definitionCN":"给某人行动的手段或权限。它比 catalytic 更宽，常带制度色彩。"}]}]},"mnemonics":{"normalIntro":{"en":"These hooks show the suffix step from noun to adjective and attach the adjective to its fixed technical phrases.","cn":"这些记忆钩展示从名词到形容词的后缀一步，并把形容词系到固定的技术搭配上。"},"normal":[{"en":"See the build: catalyst + -ic. The adjective adds nothing but 'of or having the nature of'.","cn":"看见构成：catalyst 加 -ic。形容词只加了“属于……的、具有……性质的”。"},{"en":"Remember the -lyt- core: it is the loosening root shared with analysis.","cn":"记住 -lyt- 核心：它与 analysis 共享“松开”词根。"},{"en":"Pair it with converter: a catalytic converter is a box whose job is catalytic.","cn":"与 converter 配对：催化转化器是一个工作性质为催化的盒子。"},{"en":"Use cracking for the refinery image: heavy oil broken into lighter fuel over a catalyst.","cn":"用 cracking 记炼油意象：重油在催化剂上裂解为轻质燃料。"},{"en":"For the metaphor, say 'catalytic role': the word marks a role, not a size.","cn":"记比喻时用 catalytic role：这个词标示角色，不标示大小。"}],"abstract":[{"en":"Hold one step: noun to adjective by -ic, substance to role by metaphor.","cn":"抓住两步：名词靠 -ic 变形容词，物质靠比喻变角色。"},{"en":"Sort the senses by what is described: process, device, material, economy, society, enzyme, mechanism.","cn":"按被描述的对象分组：过程、装置、材料、经济、社会、酶、机理。"},{"en":"Remember that catalytic never names the catalyst; it names what the catalyst does.","cn":"记住 catalytic 从不命名催化剂本身，它命名催化剂所做的事。"}]},"examples":[{"en":"The catalytic activity of the surface depends on its structure.","cn":"该表面的催化活性取决于其结构。"},{"en":"Modern refineries rely on catalytic cracking.","cn":"现代炼油厂依赖催化裂化。"},{"en":"Her early work had a catalytic effect on the field.","cn":"她的早期工作对该领域产生了催化作用。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音“开特利提克”：想象“开”一扇门靠“特”别“利”害的“提克”小装置——它只帮忙开门，自己不进门，就是 catalytic 催化的。","word":"catalytic"},"root":"英语名词 catalyst 加形容词后缀 -ic（经拉丁语 -icus 来自希腊语 -ikos“属于……的”）；catalyst 出自希腊语 katalysis“消解”，由 kata-“向下”加 lyein“松开”构成。","sensesIntro":{"en":"Catalytic is the adjective of a role. In chemistry it classifies processes, surfaces and devices by how they use a catalyst; outside chemistry it classifies people, policies and events by how they enable change. In every sense the word answers 'in what way is catalysis involved', never 'which catalyst'.","cn":"catalytic 是一个角色的形容词。在化学中，它按“如何使用催化剂”来分类过程、表面与装置；在化学之外，它按“如何促成变化”来分类人、政策与事件。无论哪一义，这个词回答的都是“催化以何种方式介入”，而不是“是哪种催化剂”。"},"semanticMap":{"core":{"en":"Of or by catalysis: describing whatever lowers a barrier without being consumed.","cn":"催化的、借催化而成的：描述任何降低障碍而自身不被消耗的事物。"},"chain":["CATALYST","SUFFIX","PROCESS","DEVICE","MATERIAL","ROLE"],"branches":[{"senses":"01 · 09","en":"PROCESS: the general domain of catalysis and reactions that require it.","cn":"过程：催化的一般领域以及需要它的反应。"},{"senses":"03","en":"REFINING: catalytic cracking breaks heavy oil into lighter fuel.","cn":"炼油：催化裂化把重油裂解为轻质燃料。"},{"senses":"05 · 08","en":"MATERIAL AND STEP: catalytic surfaces, sites and enzyme-catalysed steps.","cn":"材料与步骤：催化表面、位点与酶催化的步骤。"},{"senses":"04 · 06 · 07","en":"ROLE: investments, treaties and ideas that enable wider change.","cn":"角色：促成更广泛变化的投资、条约与观念。"},{"senses":"02","en":"EVERYDAY OBJECT: the car part most people know by this adjective.","cn":"日常物件：大多数人通过这个形容词认识的汽车部件。"}]},"affixes":{"intro":{"en":"Catalytic is a textbook case of suffix stacking: a Greek-rooted noun takes Latin -icus and English -ic, then -ly and compound nouns grow on top. The list follows that growth.","cn":"catalytic 是后缀叠加的教科书案例：希腊词根名词接拉丁 -icus 与英语 -ic，再在上面长出 -ly 与复合名词。清单沿着这条生长线展开。"},"latinIntro":{"en":"The Latin entries are learned or Neo-Latin forms: the Greek-rooted nouns as Latinized in European science, plus the Neo-Latin adjective catalyticus. They are included to show how the Greek root entered Latin vocabulary.","cn":"下列拉丁条目是学术拉丁或新拉丁形式：希腊词根名词在欧洲科学中的拉丁化形态，以及新拉丁形容词 catalyticus。列出它们是为了展示希腊词根如何进入拉丁词汇。"},"items":[{"word":"catalytic","structure":"catalyst + -ic (adjective suffix)","meaning":"of a catalyst; acting by catalysis","meaningCN":"催化剂的；借催化作用的","example":"The reaction needs a catalytic surface.","exampleCN":"这个反应需要催化表面。"},{"word":"catalyst","structure":"catalysis + -ist (agent noun)","meaning":"the substance that enables the reaction","meaningCN":"促成反应的物质","example":"The catalyst is not consumed.","exampleCN":"催化剂不被消耗。"},{"word":"catalysis","structure":"kata- + lysis (process noun)","meaning":"the process of catalysis","meaningCN":"催化作用","example":"Catalysis speeds up the industrial process.","exampleCN":"催化加快了工业过程。"},{"word":"catalyze","structure":"catalyst + -yze (verb suffix)","meaning":"to make a reaction proceed by catalysis","meaningCN":"催化；促成","example":"The metal catalyzes the decomposition.","exampleCN":"这种金属催化该分解反应。"},{"word":"catalytically","structure":"catalytic + -ally (adverb suffix)","meaning":"in a catalytic manner","meaningCN":"以催化方式","example":"The exhaust is treated catalytically.","exampleCN":"废气经催化处理。"},{"word":"catalytical","structure":"catalytic + -al (adjectival variant)","meaning":"an older synonym of catalytic","meaningCN":"catalytic 的较旧同义词","example":"Older texts use the catalytical form.","exampleCN":"较早的文献使用 catalytical 这一形式。"},{"word":"catalytic converter","structure":"catalytic + converter (compound noun)","meaning":"an exhaust device that cleans gases by catalysis","meaningCN":"催化转化器","example":"The catalytic converter cuts nitrogen oxides.","exampleCN":"催化转化器减少氮氧化物。"},{"word":"catalytic cracking","structure":"catalytic + cracking (compound noun)","meaning":"refining that breaks heavy oil with a catalyst","meaningCN":"催化裂化","example":"Catalytic cracking produces lighter fuels.","exampleCN":"催化裂化产出更轻的燃料。"},{"word":"catalytic site","structure":"catalytic + site (compound noun)","meaning":"the place on a surface where the reaction occurs","meaningCN":"催化位点","example":"Each catalytic site binds one molecule.","exampleCN":"每个催化位点结合一个分子。"},{"word":"biocatalytic","structure":"bio- (life) + catalytic","meaning":"using enzymes as catalysts","meaningCN":"生物催化的","example":"The biocatalytic route avoids harsh solvents.","exampleCN":"生物催化路线避免了苛刻溶剂。"}],"latinEntries":[{"word":"catalysis","structure":"kata- + lysis (Latinized Greek)","meaning":"a dissolving down; catalytic action","meaningCN":"消解；催化作用"},{"word":"lysis","structure":"Latinized Greek noun","meaning":"a loosening, dissolution","meaningCN":"松开；溶解"},{"word":"catalyticus","structure":"Neo-Latin: catalysis + -icus","meaning":"of catalysis","meaningCN":"催化的"}]}},{"word":"causation","ipa_uk":"/kɔːˈzeɪʃn/","ipa_us":"/kɔːˈzeɪʃn/","definition_zh":"因果关系；因果作用；引起；归因","definition_en":"the relationship between a cause and its effect, or the act of causing something","core_image":"一排多米诺骨牌：第一张倒下，第二张跟着倒下，那条传递下去的连接就是因果","scene":"研讨课上，老师把两张图表并排投影：一张显示相关，一张显示因果。他说：Correlation is not causation. ","sceneCN":"这里 causation 是「因果关系」（第 1、7 个义项：因果关联与统计中的因果判断）；句意：相关不等于因果。图中可辨识物件：两张折线图、投影仪、粉笔、讲台。","pos":[{"tag":"n.","zh":"因果关系；因果作用；引起"}],"collocations":[{"phrase":"the causation of disease","zh":"疾病的成因"},{"phrase":"chain of causation","zh":"因果链"},{"phrase":"correlation is not causation","zh":"相关不等于因果"},{"phrase":"legal causation","zh":"法律上的因果关系"},{"phrase":"multiple causation","zh":"多因性"},{"phrase":"direct causation","zh":"直接因果"}],"forms":[{"label":"单数（不可数为主）","form":"causation"},{"label":"复数（多种因果作用，较少用）","form":"causations"}],"derivatives":[{"word":"cause","pos":"n.","zh":"原因；事业"},{"word":"causal","pos":"adj.","zh":"因果的"},{"word":"causality","pos":"n.","zh":"因果性；因果律"},{"word":"causative","pos":"adj.","zh":"原因的；使役的"}],"senses":[{"no":"01","title":"The relation between cause and effect","titleCN":"因与果之间的关联","definition":"the relation in which one event or state brings about another","definitionCN":"一个事件或状态引起另一个事件或状态的关系","example":"The study examines the causation of migration.","exampleCN":"这项研究考察移民的因果关系。","why":"Causation names the link itself, not the cause and not the effect. The word is the bridge between two events, which is why it is so often paired with chain.","whyCN":"causation 命名的是连接本身，而不是原因或结果。这个词是两个事件之间的桥，因此常与 chain 搭配。"},{"no":"02","title":"The act of causing something","titleCN":"引起、导致的行为","definition":"the action by which something is produced or brought about","definitionCN":"使某事物产生或被造成的行为","example":"The report traces the causation of the accident to a faulty valve.","exampleCN":"报告把事故的起因追溯到一个故障阀门。","why":"Here the noun names an activity rather than a relation. Someone or something did the causing, and the word points to that doing.","whyCN":"这里名词命名的是一个活动，而不是一种关系。某人或某物做了“引起”这件事，这个词指向那个作为。"},{"no":"03","title":"Causation as a philosophical principle","titleCN":"作为哲学原理的因果律","definition":"the principle that every event has a cause, or that like causes produce like effects","definitionCN":"每个事件都有原因、或相同原因产生相同结果的原则","example":"Hume asked whether we can ever observe causation itself.","exampleCN":"休谟追问我们是否真能观察到因果作用本身。","why":"Philosophy turned the relation into a principle. What is at stake is not this or that cause, but whether the link is necessary or merely customary.","whyCN":"哲学把这种关系变成一条原理。争论的不是某一个原因，而是这条连接是必然的，还是仅仅是习惯性的。"},{"no":"04","title":"Legal causation","titleCN":"法律上的因果关系","definition":"in law, the link between a person's act and a result for which they may be held responsible","definitionCN":"法律中某人的行为与其可能须负责的结果之间的连接","example":"The court found no legal causation between the warning and the injury.","exampleCN":"法院认定该警告与伤害之间不存在法律因果关系。","why":"Law narrows causation to what is fair to attribute. Not every physical link creates liability; the chain must be close enough to count.","whyCN":"法律把因果收窄到“公平地归责”的范围。并非每条物理连接都产生责任，链条必须足够近才算数。"},{"no":"05","title":"Attributing an outcome to a source","titleCN":"把结果归因于某个来源","definition":"the assignment of an observed result to a particular cause or set of causes","definitionCN":"把观察到的结果指派给某个原因或一组原因","example":"Attribution of causation requires more than a single case.","exampleCN":"因果归因需要的不只是一个案例。","why":"This is causation as a judgement we make, not a fact we see. The word covers the mental move from 'this happened' to 'that made it happen'.","whyCN":"这是作为判断的因果，而不是被看见的事实。这个词覆盖了从“这件事发生了”到“那件事造成了它”的心智移动。"},{"no":"06","title":"A chain or mechanism of causes","titleCN":"因果链或因果机制","definition":"a series of linked causes through which an effect is produced","definitionCN":"产生某一结果的一连串相互连接的原因","example":"Historians reconstructed the chain of causation behind the famine.","exampleCN":"历史学家重建了那场饥荒背后的因果链。","why":"Complex outcomes rarely have one cause. The word then refers to the whole mechanism, the set of links that together produce the result.","whyCN":"复杂结果很少只有一个原因。此时这个词指整个机制，也就是共同产生结果的那一组连接。"},{"no":"07","title":"The origins of a disease","titleCN":"疾病成因","definition":"in medicine and epidemiology, the factors that bring about a disease","definitionCN":"医学与流行病学中导致疾病的各种因素","example":"Researchers still debate the causation of the syndrome.","exampleCN":"研究者仍在争论这种综合征的成因。","why":"Medicine uses the word when it needs to separate what brings a condition about from what merely accompanies it. Cause and correlation must be told apart.","whyCN":"医学在需要区分“造成某种状况”与“仅仅伴随它”时使用这个词。原因与相关必须被分开。"},{"no":"08","title":"Causal explanation in social science","titleCN":"社会科学中的因果解释","definition":"in social research, the attempt to explain social outcomes by identifying their causes","definitionCN":"社会研究中通过确认原因来解释社会结果的尝试","example":"The paper argues for multiple causation in urban poverty.","exampleCN":"这篇论文主张城市贫困存在多因性。","why":"Social phenomena have many causes at once, so the word shifts from a single link to a field of interacting factors. The plural causations becomes thinkable.","whyCN":"社会现象同时有许多原因，于是这个词从单一连接转向一组相互作用因素。复数形式 causations 也就变得可想了。"},{"no":"09","title":"Causation versus correlation","titleCN":"因果与相关的对照","definition":"the relation that statistical association alone cannot establish","definitionCN":"仅凭统计关联无法确立的那种关系","example":"The slogan 'correlation is not causation' warns against hasty inference.","exampleCN":"“相关不等于因果”这句口号警告人们不要草率推断。","why":"Statistics gave the word its sharpest modern contrast. Two variables can move together without one causing the other, and causation is the name of what is still missing.","whyCN":"统计学给了这个词最尖锐的现代对照。两个变量可以一起变动而互不为因，causation 正是那个仍然缺失的东西的名字。"}],"etymology":{"intro":{"en":"Causation looks like a plain derivative of cause, but it entered English through a Latin noun with a different job. Latin causatio meant 'a pleading, an excuse', and the modern sense 'cause and effect relation' is an English development. This semantic shift is the main thing to notice.","cn":"causation 看起来只是 cause 的平实派生词，实际上它是经一个功能不同的拉丁名词进入英语的。拉丁语 causatio 意为“申辩、借口”，而现代“因果关系”义是英语自身的发展。这个语义偏移是此处最该注意的地方。"},"items":[{"era":"LATIN causa","en":"Causa meant 'cause, reason, motive', and also 'a judicial case'. English cause and the whole causal family descend from it, not from the unrelated casus 'a fall'.","cn":"causa 意为“原因、理由、动机”，也指“司法案件”。英语 cause 与整个因果词族都出自它，而不是出自无关的 casus“落下”。"},{"era":"LATIN causari","en":"Causari meant 'to plead, to bring a case, to give as an excuse'. It came from causa in its legal sense, so the verb was about arguing, not about producing effects.","cn":"causari 意为“申辩、提起诉讼、作为借口提出”。它来自法律义的 causa，因此这个动词讲的是争论，而不是产生结果。"},{"era":"LATIN causatio","en":"Causatio, the noun of causari, meant 'a pleading, an excuse, a pretext'. It did not mean the relation between cause and effect, which is the sense English later gave the word.","cn":"causatio 是 causari 的名词，意为“申辩、借口、托词”。它并不表示因与果的关系，后者是英语后来赋予这个词的意思。"},{"era":"16C. ENGLISH","en":"English adopted causation in the 16th century. Early uses already concerned causing, but the abstract 'cause and effect' sense grew in philosophical writing rather than in law.","cn":"英语在 16 世纪采用 causation。早期用法已涉及“引起”，但抽象的“因与果”义是在哲学写作而非法律中成长起来的。"},{"era":"17C.–18C. PHILOSOPHY","en":"Hume and other philosophers made causation a central problem: is the link between events observed, or only inferred from habit? The word became a technical term of epistemology.","cn":"休谟等哲学家把因果问题推到中心：事件之间的连接是被观察到的，还是仅由习惯推断出来的？这个词成了认识论的术语。"},{"era":"19C.–MODERN","en":"Statistics, medicine and law each gave causation a narrower test. The slogan 'correlation is not causation' and the phrase chain of causation belong to the 20th century's effort to separate association from production.","cn":"统计学、医学与法律各自给了因果一套更窄的检验。“相关不等于因果”与“因果链”这两个说法，属于 20 世纪把“伴随”与“产生”分开的努力。"}]},"similar":{"note":{"en":"The three words cause, causal and causality sit very close to causation and are often confused. The first group sorts them by part of speech; the second group sorts the neighbouring ideas.","cn":"cause、causal、causality 与 causation 距离很近，常被混淆。第一组按词性分开，第二组按相邻概念分开。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"causality","ipa":"/kɔːˈzæləti/","tag":"abstract principle","definition":"the principle or property of being causal. Causation is a relation between events; causality is the general capacity or law behind such relations.","definitionCN":"具有因果性的原理或属性。causation 是事件之间的关系，causality 是这种关系背后的普遍能力或规律。"},{"word":"causal","ipa":"/ˈkɔːzl/","tag":"adjective","definition":"relating to a cause. It is the adjective that modifies links, factors and explanations.","definitionCN":"与原因有关的。它是修饰连接、因素与解释的形容词。"},{"word":"cause","ipa":"/kɔːz/","tag":"base noun and verb","definition":"the thing that produces an effect, or to produce one. Cause names one end of the relation; causation names the relation.","definitionCN":"产生结果的事物，或产生结果。cause 命名关系的一端，causation 命名关系本身。"}]},{"heading":"NEAR MEANING","entries":[{"word":"correlation","ipa":"/ˌkɒrəˈleɪʃn/","tag":"statistics","definition":"a mutual variation of two quantities. It is precisely what causation is often wrongly inferred from.","definitionCN":"两个量之间的相互变化。它正是人们常错误推断出因果的那个东西。"},{"word":"attribution","ipa":"/ˌætrɪˈbjuːʃn/","tag":"assignment","definition":"the act of assigning a result to a source. It is the judgement side of causation.","definitionCN":"把结果指派给某个来源的行为。它是因果的判断面。"},{"word":"determination","ipa":"/dɪˌtɜːmɪˈneɪʃn/","tag":"fixing","definition":"the process by which something is fixed or decided. It can imply a stronger, more necessary link than causation.","definitionCN":"某物被固定或决定的过程。它可以暗示比 causation 更强、更必然的连接。"},{"word":"origination","ipa":"/ˌɒrɪdʒɪˈneɪʃn/","tag":"beginning","definition":"the act of bringing something into existence. It stresses the first moment, not the whole causal link.","definitionCN":"使某物开始存在的行为。它强调最初一刻，而不是整条因果连接。"}]}]},"mnemonics":{"normalIntro":{"en":"These hooks keep the difference between cause, causation and causality visible, and attach the word to its standard phrases.","cn":"这些记忆钩让 cause、causation、causality 的区别保持可见，并把词系到标准搭配上。"},"normal":[{"en":"See the build: cause + -ation, the noun of the process or relation.","cn":"看见构成：cause 加 -ation，表示过程或关系的名词。"},{"en":"Say the slogan: correlation is not causation. It fixes the word in its most useful contrast.","cn":"念那句口号：相关不等于因果。它把这个词钉在最常用的对照里。"},{"en":"Picture dominoes for chain of causation.","cn":"用多米诺骨牌记 chain of causation。"},{"en":"Keep the trio straight: cause is the thing, causal is the adjective, causation is the link.","cn":"把三件套分清：cause 是事物，causal 是形容词，causation 是连接。"},{"en":"In law, ask whether the link is close enough to count.","cn":"在法律中，问这条连接是否近到足以算数。"}],"abstract":[{"en":"Hold one line between two dots: the line is causation, the dots are cause and effect.","cn":"抓住两点之间的一条线：线是 causation，两端是原因与结果。"},{"en":"Sort the senses by discipline: philosophy, law, medicine, social science, statistics, everyday attribution.","cn":"按学科分组义项：哲学、法律、医学、社会科学、统计学、日常归因。"},{"en":"Remember the historical twist: the Latin noun meant 'excuse', not 'cause-effect link'.","cn":"记住历史转折：这个拉丁名词意为“借口”，不是“因果连接”。"}]},"examples":[{"en":"The researchers could not establish causation from the survey alone.","cn":"研究者仅凭这项调查无法确立因果关系。"},{"en":"Legal causation limits who can be held responsible for a harm.","cn":"法律因果关系限定了谁可以为某项损害负责。"},{"en":"Multiple causation is common in complex social problems.","cn":"复杂社会问题中多因性很常见。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音“考贼神”：像“考”察案子的“贼”，要把“神”秘的因果链查清——causation 就是因果关系。","word":"causation"},"root":"拉丁语 causa“原因、理由、诉讼案件”，派生 causari“申辩”与 causatio“申辩、借口”；英语以 cause 加 -ation 构成 causation，并把词义从“申辩”转为“因果关系”。注意它与 casus“落下”无关。","sensesIntro":{"en":"Causation is about a link rather than a thing. Cause names one end, effect names the other, and causation names the connection between them, together with all the questions that connection raises: is it necessary, is it close enough, is it observed or inferred, and is it one link or a whole chain?","cn":"causation 讲的是连接，而不是事物。cause 命名一端，effect 命名另一端，causation 命名它们之间的连接，以及这条连接引出的全部问题：它是否必然、是否足够近、是被观察还是被推断、是一条链还是一整张网。"},"semanticMap":{"core":{"en":"The link that carries one event into another: cause at one end, effect at the other.","cn":"把一件事带成另一件事的连接：一端是原因，另一端是结果。"},"chain":["CAUSE","LINK","EFFECT","PRINCIPLE","ATTRIBUTION","INFERENCE"],"branches":[{"senses":"S1 · S2 · S6","en":"THE LINK: the relation itself, the act of producing, and whole chains.","cn":"连接：关系本身、产生行为，以及整条链。"},{"senses":"S3","en":"THE PRINCIPLE: causation as a law of how events work.","cn":"原理：作为事件运行法则的因果。"},{"senses":"S4","en":"THE LEGAL TEST: a link close enough for responsibility.","cn":"法律检验：近到足以产生责任的连接。"},{"senses":"S5 · S8","en":"THE JUDGEMENT: attributing outcomes, and explaining social ones.","cn":"判断：归因结果，并解释社会结果。"},{"senses":"S7 · S9","en":"THE EVIDENCE: disease origins and the contrast with mere correlation.","cn":"证据：疾病成因，以及与被单纯相关的对照。"}]},"affixes":{"intro":{"en":"Causation is cause plus -ation, and the family keeps the Latin base causa across nouns, adjectives and verbs. The list shows how the same base yields cause, causal, causality and causative.","cn":"causation 是 cause 加 -ation，整个词族在名词、形容词、动词中保留拉丁词基 causa。清单展示同一词基如何生出 cause、causal、causality、causative。"},"latinIntro":{"en":"The Latin entries include the noun of cause, the verb of pleading, and the noun of pleading. The last two are essential because they explain why English causation looks like a legal word.","cn":"拉丁语条目包括“原因”名词、“申辩”动词与“申辩”名词。后两者很关键，因为它们解释了为什么英语 causation 看起来像一个法律词。"},"items":[{"word":"causation","structure":"cause + -ation (action or state noun)","meaning":"the cause-effect relation; the act of causing","meaningCN":"因果关系；引起","example":"Causation is hard to prove from correlation.","exampleCN":"仅凭相关很难证明因果。"},{"word":"cause","structure":"Latin causa, through Old French","meaning":"the source of an effect; a purpose or case","meaningCN":"原因；事业；案件","example":"The cause of the fire was electrical.","exampleCN":"火灾的起因是电路问题。"},{"word":"causal","structure":"cause + -al (adjective suffix)","meaning":"relating to a cause","meaningCN":"因果的","example":"There is a causal link between the two events.","exampleCN":"两个事件之间存在因果联系。"},{"word":"causality","structure":"causal + -ity (abstract noun suffix)","meaning":"the principle or property of being causal","meaningCN":"因果性；因果律","example":"The argument questions causality itself.","exampleCN":"这一论证质疑因果性本身。"},{"word":"causative","structure":"cause + -ative (adjective suffix)","meaning":"producing an effect; in grammar, expressing cause","meaningCN":"使然的；使役的","example":"The verb is used in a causative construction.","exampleCN":"这个动词用于使役结构。"},{"word":"causally","structure":"causal + -ly (adverb suffix)","meaning":"in terms of cause and effect","meaningCN":"在因果方面","example":"The two factors are causally connected.","exampleCN":"这两个因素有因果联系。"},{"word":"causeless","structure":"cause + -less (privative suffix)","meaning":"without a cause","meaningCN":"无原因的","example":"They feared a causeless panic.","exampleCN":"他们担心一场无缘由的恐慌。"},{"word":"because","structure":"by + cause (historical compound)","meaning":"for the reason that","meaningCN":"因为","example":"He left because the room was too hot.","exampleCN":"他离开是因为房间太热。"},{"word":"causal chain","structure":"causal + chain (compound noun)","meaning":"a series of linked causes","meaningCN":"因果链","example":"The causal chain runs from policy to outcome.","exampleCN":"因果链从政策延伸到结果。"},{"word":"causal factor","structure":"causal + factor (compound noun)","meaning":"a condition that contributes to an outcome","meaningCN":"因果因素；致因因素","example":"Smoking is a causal factor in the disease.","exampleCN":"吸烟是这种疾病的一个致因因素。"}],"latinEntries":[{"word":"causa","structure":"root noun (1st declension)","meaning":"cause, reason; judicial case","meaningCN":"原因；理由；诉讼案件"},{"word":"causari","structure":"causa + -ari (verb ending)","meaning":"to plead, to give as an excuse","meaningCN":"申辩；作为借口提出"},{"word":"causatio","structure":"causari + -tio (action noun)","meaning":"a pleading, an excuse, a pretext","meaningCN":"申辩；借口；托词"}]}},{"word":"causal","ipa_uk":"/ˈkɔːzl/","ipa_us":"/ˈkɔːzl/","definition_zh":"因果的；原因的；表示原因的；因果关系的","definition_en":"relating to a cause, or expressing a cause-and-effect relation","core_image":"一根箭头从 A 指向 B：箭头本身不是原因，却标出“谁推了谁”","scene":"研究方法课上，老师在白板上画了一个箭头，从「吸烟」指向「肺癌」。In the methods class, the teacher draws an arrow from smoking to lung cancer and labels it a causal link.","sceneCN":"这里 causal 是「因果的、因果关系的」（第 1、3 个义项：与原因有关与因果联系）；句意：老师从吸烟画箭头指向肺癌，并把它标为因果关系。图中可辨识物件：白板、箭头、两个方框、马克笔。","pos":[{"tag":"adj.","zh":"因果的；原因的；表示原因的"}],"collocations":[{"phrase":"causal link","zh":"因果联系"},{"phrase":"causal relationship","zh":"因果关系"},{"phrase":"causal inference","zh":"因果推断"},{"phrase":"causal mechanism","zh":"因果机制"},{"phrase":"causal explanation","zh":"因果解释"},{"phrase":"causal factor","zh":"致因因素"}],"forms":[{"label":"原级（形容词）","form":"causal"},{"label":"比较级（更具因果性）","form":"more causal"},{"label":"最高级（最具因果性）","form":"most causal"}],"derivatives":[{"word":"causality","pos":"n.","zh":"因果性；因果律"},{"word":"causally","pos":"adv.","zh":"在因果上；以因果方式"},{"word":"causation","pos":"n.","zh":"因果关系；引起"},{"word":"causative","pos":"adj.","zh":"使然的；使役的"}],"senses":[{"no":"01","title":"Relating to a cause","titleCN":"与原因有关的","definition":"connected with the idea of a cause or with causes in general","definitionCN":"与原因这一概念或一般意义上的原因有关","example":"The chapter discusses causal language in ordinary speech.","exampleCN":"这一章讨论日常言语中的因果语言。","why":"Late Latin causalis was simply 'of a cause', formed from causa with -alis. The adjective begins as a label for anything belonging to the category of cause.","whyCN":"晚期拉丁语 causalis 就是“原因的”，由 causa 加 -alis 构成。这个形容词起初只是给任何属于“原因”范畴的东西贴标签。"},{"no":"02","title":"Expressing cause in grammar","titleCN":"语法中表示原因的","definition":"in grammar, describing a clause or conjunction that introduces a reason","definitionCN":"语法中描述引出原因的从句或连词","example":"Because and since are causal conjunctions.","exampleCN":"because 与 since 是表示原因的连词。","why":"Grammar borrowed the adjective for forms whose whole job is to state a reason. A causal clause does not describe a relation; it performs one in language.","whyCN":"语法借这个形容词来指那些专职陈述理由的形式。原因状语从句不描述一种关系，它在语言中执行一种关系。"},{"no":"03","title":"Marking a cause-effect link","titleCN":"标示因果联系的","definition":"describing a connection in which one thing is held to produce another","definitionCN":"描述一物被认为产生另一物的连接","example":"Researchers found a causal link between sleep loss and errors.","exampleCN":"研究者发现睡眠不足与差错之间存在因果联系。","why":"This is the most common modern use: the adjective modifies link, relation or connection. It marks the arrow between two boxes.","whyCN":"这是最常见的现代用法：形容词修饰 link、relation、connection。它标出两个方框之间的箭头。"},{"no":"04","title":"Causal inference in statistics","titleCN":"统计中的因果推断","definition":"in statistics and epidemiology, describing methods that try to move from association to cause","definitionCN":"统计与流行病学中描述从关联走向原因的方法","example":"The trial was designed for causal inference, not mere description.","exampleCN":"这项试验是为因果推断而设计，而不只是描述。","why":"The adjective now qualifies a method rather than a link. Causal inference is the disciplined attempt to earn the arrow that correlation alone cannot give.","whyCN":"这个形容词现在修饰方法，而不是连接。因果推断是有纪律的尝试，去赢得单靠相关无法给出的那支箭头。"},{"no":"05","title":"A causal explanation","titleCN":"因果解释","definition":"an account that explains an event by identifying what brought it about","definitionCN":"通过确认是什么造成了某事件来解释它的说法","example":"A causal explanation must rule out reverse causation.","exampleCN":"因果解释必须排除反向因果。","why":"Explanation is the human activity, and causal marks its type. The word tells the reader that reasons of the 'because it produced' kind are coming, not reasons of purpose or meaning.","whyCN":"解释是人的活动，causal 标示它的类型。这个词告诉读者，接下来的是“因为它造成了”这一类理由，而不是目的或意义类的理由。"},{"no":"06","title":"A causal chain","titleCN":"因果链","definition":"a sequence of events in which each link produces the next","definitionCN":"每个环节都产生下一环节的一连串事件","example":"The causal chain from drought to conflict is long and indirect.","exampleCN":"从干旱到冲突的因果链漫长而间接。","why":"The adjective makes chain a technical object. Once causes are linked in series, the question becomes where to cut the chain for responsibility or analysis.","whyCN":"这个形容词把 chain 变成技术对象。一旦原因被串成系列，问题就变成：为了责任或分析，应该在哪一环切断。"},{"no":"07","title":"A causal model","titleCN":"因果模型","definition":"a formal representation of assumed causal relations among variables","definitionCN":"对变量之间假定因果关系的形式化表示","example":"The diagram is a causal model with arrows for assumed effects.","exampleCN":"这张图是一个因果模型，用箭头表示假定的效应。","why":"Computing and statistics turned the adjective into a modelling term. A causal model does not prove causation; it states a hypothesis about which arrows exist.","whyCN":"计算机与统计学把这个形容词变成建模术语。因果模型并不证明因果，它陈述一个关于哪些箭头存在的假设。"},{"no":"08","title":"A causal agent","titleCN":"致因主体","definition":"the thing that actively produces an effect, especially in medicine or biology","definitionCN":"主动产生效果的事物，尤用于医学或生物学","example":"The causal agent of the disease was a previously unknown virus.","exampleCN":"这种疾病的致因体是一种此前未知的病毒。","why":"Here the adjective points to a concrete producer, not to a relation. A causal agent is the thing at the tail of the arrow, the one doing the producing.","whyCN":"这里形容词指向具体的产生者，而不是关系。致因主体是箭头尾端那个真正在起作用的东西。"},{"no":"09","title":"A causal factor in medicine","titleCN":"医学中的致因因素","definition":"a condition that contributes to the development of a disease or outcome","definitionCN":"促成某种疾病或结果发展的条件","example":"Air pollution is a causal factor in childhood asthma.","exampleCN":"空气污染是儿童哮喘的一个致因因素。","why":"Medicine prefers this phrase because it allows several contributors at once. The adjective marks contribution to an outcome without claiming that one factor is solely responsible.","whyCN":"医学偏爱这个说法，因为它允许同时有多个贡献者。这个形容词标示对结果的贡献，而不宣称某个因素是唯一责任者。"}],"etymology":{"intro":{"en":"Causal is the direct Latin adjective of causa, unlike causation, which came through the legal noun causatio. Its history is mostly the history of how philosophers and statisticians learned to qualify the word 'link'.","cn":"causal 是 causa 的直接拉丁形容词，与经法律名词 causatio 而来的 causation 不同。它的历史，主要是哲学家与统计学家学会如何修饰“连接”这个词的历史。"},"items":[{"era":"LATIN causa","en":"Causa meant 'cause, reason, motive' and also 'a legal case'. Every member of the English causal family goes back to this noun, including cause itself.","cn":"causa 意为“原因、理由、动机”，也指“法律案件”。英语因果词族的每个成员，包括 cause 本身，都上溯到这个名词。"},{"era":"LATE LATIN causalis","en":"Causalis was formed with -alis, 'belonging to', and meant 'of a cause'. It was a learned adjective used in philosophy and grammar, not a word of ordinary Roman speech.","cn":"causalis 由 -alis“属于……的”构成，意为“原因的”。它是哲学与语法中的学术形容词，不是罗马日常口语词。"},{"era":"16C. ENGLISH","en":"English causal enters in the 16th century as the adjective corresponding to cause. Early uses are philosophical and grammatical, matching its Latin career.","cn":"英语 causal 在 16 世纪作为 cause 的对应形容词进入。早期用法属哲学与语法，与它的拉丁经历一致。"},{"era":"17C.–18C. PHILOSOPHY","en":"The phrase causal relation becomes central in debates over whether causes are observed or inferred. The adjective now modifies relation, connection and necessity, not only cause itself.","cn":"causal relation 这一说法在“原因是被观察还是被推断”的争论中变得核心。这个形容词现在修饰 relation、connection、necessity，而不只是 cause 本身。"},{"era":"19C.–20C. SCIENCE","en":"Medicine speaks of causal agents, and statistics of causal inference. Each field attaches the adjective to its own object: a pathogen, a variable, a mechanism.","cn":"医学谈致因主体，统计学谈因果推断。每个领域都把这个形容词接到自己的对象上：病原体、变量、机制。"},{"era":"MODERN ENGLISH","en":"Causal model, causal chain and causal factor are now standard across disciplines. The word has become the general adjective for any claim that one thing produces another.","cn":"因果模型、因果链、致因因素如今在各学科中都是标准说法。这个词已成为任何“一物产生另一物”之主张的通用形容词。"}]},"similar":{"note":{"en":"Causal is most often confused with casual, which looks and sounds close but has a completely different root. The first group makes that separation, then distinguishes the family members by part of speech.","cn":"causal 最常与 casual 混淆，后者形音都近，却词根完全不同。第一组先做这个区分，再按词性区分同族词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"casual","ipa":"/ˈkæʒuəl/","tag":"different root","definition":"relaxed, informal, or happening by chance. It comes from Latin casus 'a fall, an occurrence', not from causa.","definitionCN":"随意的、非正式的，或偶然发生的。它来自拉丁语 casus“落下、发生”，不是 causa。"},{"word":"causative","ipa":"/ˈkɔːzətɪv/","tag":"family adjective","definition":"actively producing an effect, or marking a cause in grammar. It is stronger than causal: it says something does cause, not merely relates to cause.","definitionCN":"主动产生效果的，或在语法中标记使役的。它比 causal 更强：它说某物确实造成，而不只是与原因有关。"},{"word":"causation","ipa":"/kɔːˈzeɪʃn/","tag":"family noun","definition":"the cause-effect relation itself. Causal is the adjective; causation is the relation it describes.","definitionCN":"因果关系本身。causal 是形容词，causation 是它所描述的关系。"}]},{"heading":"NEAR MEANING","entries":[{"word":"etiological","ipa":"/ˌiːtiəˈlɒdʒɪkl/","tag":"medicine","definition":"relating to the causes of a disease. It is the medical specialist's word for what causal covers more broadly.","definitionCN":"与疾病原因有关的。它是医学专家用来表达 causal 更宽含义的词。"},{"word":"correlational","ipa":"/ˌkɒrəˈleɪʃənl/","tag":"statistics","definition":"describing a study of association without claimed causation. It is the deliberate opposite of causal in research design.","definitionCN":"描述只研究关联而不主张因果的研究。在研究设计中，它是 causal 的刻意对立面。"},{"word":"explanatory","ipa":"/ɪkˈsplænətri/","tag":"function","definition":"serving to explain. It is broader than causal: an explanation can be functional or historical, not only causal.","definitionCN":"用于解释的。它比 causal 更宽：解释可以是功能性的或历史性的，不只限于因果。"},{"word":"deterministic","ipa":"/dɪˌtɜːmɪˈnɪstɪk/","tag":"stronger link","definition":"holding that events follow necessarily from prior conditions. It is a much stronger claim than causal.","definitionCN":"主张事件必然由先前条件决定的。它比 causal 的主张强得多。"}]}]},"mnemonics":{"normalIntro":{"en":"These hooks separate causal from casual at the level of the root, then attach the adjective to six standard nouns it modifies.","cn":"这些记忆钩在词根层面把 causal 与 casual 分开，再把形容词接到它常修饰的六个标准名词上。"},"normal":[{"en":"Spell it with cause inside: c-a-u-s-a-l. The u comes from causa; casual has no u.","cn":"记住里面藏着 cause：c-a-u-s-a-l。u 来自 causa；casual 没有 u。"},{"en":"Pair the arrow: causal link is the arrow between two boxes.","cn":"配箭头：causal link 是两个方框之间的箭头。"},{"en":"Keep causal for relation, causative for producing.","cn":"causal 用于关系，causative 用于产生。"},{"en":"In grammar, causal conjunctions give reasons: because, since, as.","cn":"语法中表示原因的连词给理由：because、since、as。"},{"en":"In statistics, causal inference tries to earn the arrow.","cn":"统计中，因果推断试图赢得那支箭头。"}],"abstract":[{"en":"Hold one arrow and one label: the arrow is causation, the label on it is causal.","cn":"抓住一支箭头和一个标签：箭头是 causation，贴在上面的标签是 causal。"},{"en":"Sort by the noun it modifies: link, relation, inference, mechanism, model, agent, factor, clause.","cn":"按所修饰的名词分组：联系、关系、推断、机制、模型、主体、因素、从句。"},{"en":"Remember the false friend: casual means relaxed or accidental, never causal.","cn":"记住假朋友：casual 意为随意或偶然，绝不是 causal。"}]},"examples":[{"en":"The evidence does not prove a causal relationship.","cn":"这些证据不能证明因果关系。"},{"en":"Because introduces a causal clause.","cn":"because 引出原因状语从句。"},{"en":"Researchers use causal models to test competing explanations.","cn":"研究者用因果模型来检验相互竞争的解释。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音“考走”：把原因“考”察清楚才“走”下一步——causal 就是因果的。注意别和 casual“随意”混。","word":"causal"},"root":"拉丁语 causa“原因、理由、诉讼案件”加形容词后缀 -alis，构成晚期拉丁语 causalis“原因的”；英语 16 世纪直接借入作 causal。注意与 casus“落下、偶然”派生的 casual 无关。","sensesIntro":{"en":"Causal is the adjective that marks an arrow. It can sit on the relation itself (causal link), on the method that tries to establish it (causal inference), on the thing that produces it (causal agent), or on the clause that states a reason (causal conjunction). The word never says the arrow is proven; it only says the claim is about cause.","cn":"causal 是给箭头贴标签的形容词。它可以贴在关系本身（causal link）、贴在试图确立关系的方法（causal inference）、贴在产生结果的事物（causal agent），或贴在陈述理由的从句（causal conjunction）。这个词从不宣称箭头已被证明，它只说这个主张是关于原因的。"},"semanticMap":{"core":{"en":"The label on a cause-effect arrow: relating to who or what produces what.","cn":"贴在因果箭头上的标签：关于谁或什么产生了什么。"},"chain":["CAUSE","ARROW","RELATION","METHOD","MODEL","AGENT"],"branches":[{"senses":"S1 · S3 · S6","en":"THE LINK: general causal language, causal links, and whole chains.","cn":"连接：一般因果语言、因果联系与整条链。"},{"senses":"S2","en":"GRAMMAR: clauses and conjunctions that state a reason.","cn":"语法：陈述理由的从句与连词。"},{"senses":"S4 · S7","en":"METHOD: causal inference and formal causal models.","cn":"方法：因果推断与形式化因果模型。"},{"senses":"S5","en":"EXPLANATION: an account organised around production.","cn":"解释：围绕“产生”组织起来的说明。"},{"senses":"S8 · S9","en":"THE PRODUCER: agents and factors that contribute to an outcome.","cn":"产生者：促成结果的主体与因素。"}]},"affixes":{"intro":{"en":"Causal takes the Latin adjective suffix -alis, and its family spreads across -ity, -ly, -tion and -ative. The list shows the same base producing a noun of principle, a noun of relation, and an adverb.","cn":"causal 接拉丁形容词后缀 -alis，其词族分布在 -ity、-ly、-tion、-ative 上。清单展示同一词基如何生出原理名词、关系名词与副词。"},"latinIntro":{"en":"The Latin entries give the noun of cause, its learned adjective, and the abstract noun of causality formed in later Latin.","cn":"拉丁语条目给出“原因”名词、其学术形容词，以及晚期拉丁语中构成的“因果性”抽象名词。"},"items":[{"word":"causal","structure":"causa + -alis (adjective suffix)","meaning":"relating to a cause","meaningCN":"与原因有关的","example":"They found no causal connection.","exampleCN":"他们没有发现因果联系。"},{"word":"cause","structure":"Latin causa, through Old French","meaning":"the source of an effect","meaningCN":"原因；起因","example":"The cause remains unknown.","exampleCN":"原因仍不清楚。"},{"word":"causality","structure":"causal + -ity (abstract noun)","meaning":"the principle of cause and effect","meaningCN":"因果性；因果律","example":"The novel plays with ideas of causality.","exampleCN":"这部小说玩弄因果观念。"},{"word":"causally","structure":"causal + -ly (adverb suffix)","meaning":"in a causal way","meaningCN":"在因果上","example":"The variables are causally related.","exampleCN":"这些变量有因果关系。"},{"word":"causation","structure":"cause + -ation (relation noun)","meaning":"the cause-effect relation","meaningCN":"因果关系","example":"Causation is not established by correlation.","exampleCN":"相关不能确立因果。"},{"word":"causative","structure":"causa + -ative (productive adjective)","meaning":"producing an effect; expressing cause","meaningCN":"使然的；使役的","example":"The suffix forms a causative verb.","exampleCN":"这个后缀构成使役动词。"},{"word":"causal link","structure":"causal + link (compound noun)","meaning":"a connection held to produce an effect","meaningCN":"因果联系","example":"The study reports a causal link.","exampleCN":"这项研究报告了一项因果联系。"},{"word":"causal inference","structure":"causal + inference (compound noun)","meaning":"reasoning from data to a causal claim","meaningCN":"因果推断","example":"Causal inference needs strong assumptions.","exampleCN":"因果推断需要强假设。"},{"word":"causal clause","structure":"causal + clause (compound noun)","meaning":"a clause that states a reason","meaningCN":"原因状语从句","example":"The sentence begins with a causal clause.","exampleCN":"这个句子以原因状语从句开头。"},{"word":"causal factor","structure":"causal + factor (compound noun)","meaning":"a condition that contributes to an outcome","meaningCN":"致因因素","example":"Stress is one causal factor in the illness.","exampleCN":"压力是这种疾病的一个致因因素。"}],"latinEntries":[{"word":"causa","structure":"root noun (1st declension)","meaning":"cause, reason","meaningCN":"原因；理由"},{"word":"causalis","structure":"causa + -alis","meaning":"of a cause","meaningCN":"原因的"},{"word":"causalitas","structure":"causalis + -itas (abstract noun)","meaning":"causality, causal quality","meaningCN":"因果性；因果性质"}]}},{"word":"causality","ipa_uk":"/kɔːˈzæləti/","ipa_us":"/kɔːˈzæləti/","definition_zh":"因果性；因果律；因果关系；因果作用","definition_en":"the principle or property by which causes produce effects, or the quality of being causal","core_image":"一张看不见的网：每个节点都连着前一个节点，整张网就是因果性","scene":"哲学导论课上，老师在黑板上写下原因、因果作用、因果性三个词，然后提问。In the philosophy class, the teacher writes cause, causation and causality on the board and asks which one names the principle itself.","sceneCN":"这里 causality 是「因果性、因果律」（第 1、2 个义项：作为属性的因果性与作为原则的因果律）；句意：老师在黑板上写下 cause、causation、causality 三个词，问哪一个命名了原则本身。图中可辨识物件：黑板、三个粉笔词、板擦、讲台。","pos":[{"tag":"n.","zh":"因果性；因果律；因果关系"}],"collocations":[{"phrase":"the principle of causality","zh":"因果律原则"},{"phrase":"reverse causality","zh":"反向因果"},{"phrase":"linear causality","zh":"线性因果"},{"phrase":"causality assessment","zh":"因果性评估"},{"phrase":"causality and correlation","zh":"因果与相关"},{"phrase":"the law of causality","zh":"因果律"}],"forms":[{"label":"单数（不可数为主）","form":"causality"},{"label":"复数（多种因果体系，较少用）","form":"causalities"}],"derivatives":[{"word":"causal","pos":"adj.","zh":"因果的"},{"word":"causation","pos":"n.","zh":"因果关系；引起"},{"word":"causally","pos":"adv.","zh":"在因果上"},{"word":"causative","pos":"adj.","zh":"使然的；使役的"}],"senses":[{"no":"01","title":"The property of being causal","titleCN":"具有因果性的属性","definition":"the quality that makes one thing able to produce another","definitionCN":"使一物能够产生另一物的性质","example":"Philosophers debate whether causality belongs to things or to our descriptions of them.","exampleCN":"哲学家争论因果性属于事物本身，还是属于我们对事物的描述。","why":"The suffix -ity turns an adjective into a property. Causality is not a particular cause or a particular link, but the quality of being causal at all.","whyCN":"后缀 -ity 把形容词变成属性。causality 不是某个原因或某条连接，而是“具有因果性”这一性质本身。"},{"no":"02","title":"The principle that every event has a cause","titleCN":"每个事件都有原因的原则","definition":"the principle that nothing happens without a cause, often treated as a law of thought or of nature","definitionCN":"没有事物无缘无故发生的原则，常被视为思维或自然的法则","example":"Kant treated causality as a category of the understanding.","exampleCN":"康德把因果性视为知性的一个范畴。","why":"Philosophy made the property into a principle. Once stated as a law, causality governs all events rather than describing one link.","whyCN":"哲学把属性变成原则。一旦被陈述为法则，因果性就支配一切事件，而不是描述某一条连接。"},{"no":"03","title":"Cause and effect taken together","titleCN":"原因与结果的总体关系","definition":"the whole system of cause-effect relations, considered as one subject","definitionCN":"作为一个整体主题来考察的全部因果关系系统","example":"The book studies causality in complex systems.","exampleCN":"这本书研究复杂系统中的因果关系。","why":"This is the collective use: not one arrow but the whole network. It is close to causation, but wider and more abstract.","whyCN":"这是集合用法：不是一支箭头，而是整张网。它接近 causation，但更宽、更抽象。"},{"no":"04","title":"A philosophical category","titleCN":"哲学范畴","definition":"in philosophy, one of the basic categories through which the mind organises experience","definitionCN":"哲学中心智借以组织经验的基本范畴之一","example":"The critique asks whether causality is a feature of the world or of thought.","exampleCN":"这项批判追问因果性是世界的特征，还是思维的特征。","why":"Kant's move made causality a form imposed by the mind. The word then names a condition of possible experience, not an observable relation.","whyCN":"康德的做法把因果性变成心智施加的形式。这个词于是命名可能经验的条件，而不是可观察的关系。"},{"no":"05","title":"Deterministic chains of causes","titleCN":"决定论式的因果链","definition":"the view or situation in which every later state follows necessarily from earlier ones","definitionCN":"每个后续状态都必然由先前状态得出的观点或情形","example":"Laplace imagined a mind that could predict everything through causality.","exampleCN":"拉普拉斯想象了一种能通过因果性预测一切的心智。","why":"If causality is a universal law, the whole future is a chain. The word then carries a determinist weight that everyday 'cause' does not.","whyCN":"如果因果性是普遍法则，整个未来就是一条链。这个词于是带上决定论的分量，而日常的 cause 没有这层分量。"},{"no":"06","title":"Causality in scientific research","titleCN":"科研中的因果性","definition":"the property that a study tries to establish when it moves beyond association","definitionCN":"研究在超越关联时试图确立的那种性质","example":"The review graded the causality of each reported side effect.","exampleCN":"这项综述对报告的每种副作用进行了因果性分级。","why":"Science uses the word when it must decide whether a observed association deserves the name of causation. Causality is the target, not the starting point.","whyCN":"科学在必须判断某种观察到的关联是否配得上“因果”之名时使用这个词。因果性是目标，而不是起点。"},{"no":"07","title":"Legal causality","titleCN":"法律上的因果性","definition":"the degree to which an act can be treated as the cause of a legally relevant result","definitionCN":"某一行为可被视为法律相关结果之原因的程度","example":"The judgment separates factual from legal causality.","exampleCN":"该判决把事实因果性与法律因果性分开。","why":"Law adds a normative layer: not every link in the chain counts for liability. Causality here is a property the court is willing to recognise, not merely a physical fact.","whyCN":"法律加上了一层规范：并非链上的每条连接都算作责任。这里的因果性是法院愿意承认的属性，而不只是物理事实。"},{"no":"08","title":"Narrative causality","titleCN":"叙事因果性","definition":"in literary criticism, the way a story connects events so that one seems to lead to the next","definitionCN":"文学批评中故事连接事件、使前事看似引出后事的方式","example":"The novel's causality is emotional rather than logical.","exampleCN":"这部小说的因果性是情感的，而不是逻辑的。","why":"Stories need events to feel caused even when no physical cause exists. Criticism borrowed the word to describe that invented connective tissue.","whyCN":"故事需要事件显得有原因，即使并不存在物理原因。批评界借用这个词来描述这种被发明出来的连接组织。"},{"no":"09","title":"The intuition of causality","titleCN":"因果直觉","definition":"in psychology, the human tendency to perceive certain events as causing others","definitionCN":"心理学中人类把某些事件感知为造成另一些事件的倾向","example":"Infants appear to develop an intuition of causality early.","exampleCN":"婴儿似乎很早就发展出因果直觉。","why":"Psychology locates causality in the perceiver. The word now names a habit of the mind, which is exactly the point Hume made about the relation itself.","whyCN":"心理学把因果性定位在感知者身上。这个词现在命名心智的一种习惯，而这正是休谟对因果关系本身所做的论断。"}],"etymology":{"intro":{"en":"Causality is a scholastic abstraction: Latin causalitas, built on causalis with the abstract suffix -itas. It entered English philosophy as the name of a property or principle, which is why it sounds more theoretical than causation.","cn":"causality 是一个经院哲学式的抽象词：拉丁语 causalitas，由 causalis 加抽象后缀 -itas 构成。它作为属性或原则的名称进入英语哲学，因此听起来比 causation 更理论化。"},"items":[{"era":"LATIN causa","en":"Causa supplied the whole family: cause, causal, causation and causality. Its range included 'reason', 'motive' and 'legal case', so the descendants split along those lines.","cn":"causa 提供了整个词族：cause、causal、causation、causality。它的范围包括“理由”“动机”“法律案件”，后代词便沿着这些线分化。"},{"era":"LATIN causalis","en":"Causalis, 'of a cause', was the adjective used by Latin writers on philosophy and grammar. English borrowed it almost unchanged as causal.","cn":"causalis“原因的”是拉丁哲学与语法作家使用的形容词。英语几乎原样借入作 causal。"},{"era":"LATE LATIN causalitas","en":"Causalitas was formed with -itas, the abstract suffix that gives English -ity. Scholastic writers used it for the property of being a cause, a term of analysis rather than of everyday speech.","cn":"causalitas 由 -itas 构成，这个抽象后缀对应英语 -ity。经院作家用它指“作为原因的性质”，这是分析术语，不是日常言语。"},{"era":"17C. ENGLISH","en":"English causality appears in philosophical writing in the 17th century, alongside causal and causation. The three words were differentiated by part of speech and by level of abstraction.","cn":"英语 causality 在 17 世纪与 causal、causation 一同出现在哲学写作中。这三个词按词性与抽象层级被区分开来。"},{"era":"18C. PHILOSOPHY","en":"Hume analysed causality as a habit of expectation, and Kant rebuilt it as a category of the understanding. The word became a battlefield term in epistemology.","cn":"休谟把因果性分析为一种期待的习惯，康德则把它重建为知性的范畴。这个词成了认识论的战场术语。"},{"era":"20C.–MODERN","en":"Science added causality assessment, reverse causality and multicausality. Literary criticism added narrative causality. The word now names a property to be tested, denied or narrated.","cn":"科学增加了因果性评估、反向因果与多因性。文学批评增加了叙事因果性。这个词现在命名一种可被检验、否认或叙述的属性。"}]},"similar":{"note":{"en":"Causality, causation and causal are a closely related trio, and casualty is a dangerous look-alike from a different root. The groups sort both problems.","cn":"causality、causation、causal 是关系很近的三件套，而 casualty 是来自另一词根的危险形近词。两组分别处理这两个问题。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"casualty","ipa":"/ˈkæʒuəlti/","tag":"different root","definition":"a person killed or injured in an accident or war. It comes from Latin casus 'a fall', not from causa, and has nothing to do with causes.","definitionCN":"事故或战争中伤亡的人。它来自拉丁语 casus“落下”，不是 causa，与原因无关。"},{"word":"causation","ipa":"/kɔːˈzeɪʃn/","tag":"relation","definition":"the relation between a cause and its effect. Causality is the general property or principle; causation is the particular relation.","definitionCN":"因与果之间的关系。causality 是普遍属性或原则，causation 是具体关系。"},{"word":"causal","ipa":"/ˈkɔːzl/","tag":"adjective","definition":"relating to a cause. It is the adjective of the family, while causality is the abstract noun.","definitionCN":"与原因有关的。它是词族中的形容词，而 causality 是抽象名词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"determinism","ipa":"/dɪˈtɜːmɪnɪzəm/","tag":"stronger doctrine","definition":"the doctrine that every event is fixed by prior conditions. Causality alone does not require this strong claim.","definitionCN":"主张每个事件都由先前条件固定的学说。单凭因果性并不需要这么强的主张。"},{"word":"correlation","ipa":"/ˌkɒrəˈleɪʃn/","tag":"statistics","definition":"a mutual variation of quantities. It is what causality is often wrongly reduced to.","definitionCN":"数量之间的相互变化。它常被错误地还原为因果性。"},{"word":"necessity","ipa":"/nəˈsesəti/","tag":"modality","definition":"the quality of being impossible to be otherwise. Some theories of causality include necessity, others do not.","definitionCN":"不可能不是如此的性质。有些因果理论包含必然性，有些则不含。"},{"word":"agency","ipa":"/ˈeɪdʒənsi/","tag":"source","definition":"the capacity to act and produce effects. It locates causality in an actor rather than in a law.","definitionCN":"行动并产生效果的能力。它把因果性定位在行动者，而不是法则中。"}]}]},"mnemonics":{"normalIntro":{"en":"These hooks separate the -ity abstraction from the -tion relation, and mark the casualty trap.","cn":"这些记忆钩把 -ity 的抽象与 -tion 的关系分开，并标出 casualty 这个陷阱。"},"normal":[{"en":"See the suffix: causal + -ity makes a property, not a single link.","cn":"看见后缀：causal 加 -ity 造出属性，而不是单条连接。"},{"en":"Keep the trio: cause is the thing, causation is the link, causality is the principle.","cn":"记住三件套：cause 是事物，causation 是连接，causality 是原则。"},{"en":"Watch the trap: casualty is a victim, not a principle. One letter changes the whole family.","cn":"当心陷阱：casualty 是伤亡者，不是原则。一个字母换掉整个词族。"},{"en":"Use the phrase principle of causality for the philosophical sense.","cn":"哲学义用 principle of causality 这一说法。"},{"en":"In research, pair causality with assessment and reverse causality.","cn":"在研究语境中，把 causality 与 assessment、reverse causality 配对。"}],"abstract":[{"en":"Hold one network, not one arrow: causality is the whole web of arrows.","cn":"抓住一张网，而不是一支箭头：causality 是全部箭头的网。"},{"en":"Sort the senses by discipline: philosophy, science, law, literature, psychology.","cn":"按学科分组义项：哲学、科学、法律、文学、心理学。"},{"en":"Remember the abstraction ladder: cause, causal, causation, causality.","cn":"记住抽象阶梯：cause、causal、causation、causality。"}]},"examples":[{"en":"The principle of causality states that every event has a cause.","cn":"因果律原则指出每个事件都有原因。"},{"en":"The study could not rule out reverse causality.","cn":"这项研究无法排除反向因果。"},{"en":"Literary critics speak of narrative causality when plot events feel inevitable.","cn":"当情节事件显得必然时，文学批评家会谈及叙事因果性。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音“烤杂了题”：把各种原因“烤”在一起，成一整套“题”——causality 就是因果性。注意别读成 casualty 伤亡者。","word":"causality"},"root":"拉丁语 causa“原因”加后缀构成 causalis“原因的”，再加抽象后缀 -itas 成晚期拉丁语 causalitas“因果性”；英语经哲学写作借入作 causality。与 casus“落下”派生的 casualty 无关。","sensesIntro":{"en":"Causality is the abstract member of the family: not a cause, not one link, but the property or principle that makes links possible. Philosophy treats it as a law or a category, science as a property to be established, law as a limit on responsibility, and literature as an effect the story must create.","cn":"causality 是词族中最抽象的成员：不是原因，不是某条连接，而是使连接成为可能的属性或原则。哲学把它当作法则或范畴，科学把它当作待确立的属性，法律把它当作责任的界限，文学把它当作故事必须制造出的效果。"},"semanticMap":{"core":{"en":"The quality behind all arrows: whatever makes one thing able to produce another.","cn":"一切箭头背后的性质：使一物能够产生另一物的东西。"},"chain":["CAUSE","PROPERTY","PRINCIPLE","CATEGORY","SYSTEM","INTUITION"],"branches":[{"senses":"S1 · S3","en":"THE PROPERTY: being causal, and the whole network of relations.","cn":"属性：具有因果性，以及全部关系网。"},{"senses":"S2 · S4 · S5","en":"THE PRINCIPLE: a law of nature, a category of mind, and a determinist chain.","cn":"原则：自然法则、心智范畴，以及决定论链条。"},{"senses":"S6 · S7","en":"THE TEST: scientific assessment and legal attribution.","cn":"检验：科学评估与法律归责。"},{"senses":"S8","en":"THE STORY: causality manufactured by narrative.","cn":"故事：由叙事制造出来的因果性。"},{"senses":"S9","en":"THE MIND: the intuition that some events cause others.","cn":"心智：某些事件造成另一些事件的直觉。"}]},"affixes":{"intro":{"en":"Causality is the abstract noun in -ity built on causal. The items show the same base across adjectives, nouns and compounds, including the modern research phrases.","cn":"causality 是建立在 causal 上的 -ity 抽象名词。下列条目展示同一词基在形容词、名词与复合词中的形态，包括现代研究短语。"},"latinIntro":{"en":"The Latin entries give cause, its adjective, and the scholastic abstract noun that English borrowed as causality.","cn":"拉丁语条目给出原因、其形容词，以及英语借作 causality 的经院抽象名词。"},"items":[{"word":"causality","structure":"causal + -ity (abstract noun suffix)","meaning":"the property or principle of cause and effect","meaningCN":"因果性；因果律","example":"The argument questions the very idea of causality.","exampleCN":"这一论证质疑因果性观念本身。"},{"word":"causal","structure":"causa + -alis (adjective suffix)","meaning":"relating to a cause","meaningCN":"因果的","example":"They looked for a causal explanation.","exampleCN":"他们寻找一种因果解释。"},{"word":"causa","structure":"Latin root noun","meaning":"cause, reason","meaningCN":"原因；理由","example":"Causa is the base of the whole family.","exampleCN":"causa 是整个词族的词基。"},{"word":"causalitas","structure":"causalis + -itas (abstract suffix)","meaning":"causality, causal quality","meaningCN":"因果性；因果性质","example":"Scholastic writers used causalitas.","exampleCN":"经院作家使用 causalitas 一词。"},{"word":"causation","structure":"cause + -ation (relation noun)","meaning":"the cause-effect relation","meaningCN":"因果关系","example":"Causation requires more than sequence.","exampleCN":"因果不只是先后相继。"},{"word":"causally","structure":"causal + -ly (adverb suffix)","meaning":"in causal terms","meaningCN":"在因果上","example":"The two events are causally linked.","exampleCN":"这两个事件有因果联系。"},{"word":"causative","structure":"causa + -ative (productive adjective)","meaning":"producing an effect","meaningCN":"使然的","example":"A causative agent produces the change.","exampleCN":"致因主体产生这种变化。"},{"word":"reverse causality","structure":"reverse + causality (compound noun)","meaning":"a causal direction opposite to the one assumed","meaningCN":"反向因果","example":"Reverse causality can ruin a naive analysis.","exampleCN":"反向因果会毁掉一个天真的分析。"},{"word":"linear causality","structure":"linear + causality (compound noun)","meaning":"a simple one-way chain of causes","meaningCN":"线性因果","example":"Complex systems rarely show linear causality.","exampleCN":"复杂系统很少呈现线性因果。"},{"word":"multicausality","structure":"multi- (many) + causality","meaning":"the presence of several interacting causes","meaningCN":"多因性；多重因果","example":"Multicausality is the norm in public health.","exampleCN":"多因性是公共卫生中的常态。"}],"latinEntries":[{"word":"causa","structure":"root noun (1st declension)","meaning":"cause, reason","meaningCN":"原因；理由"},{"word":"causalis","structure":"causa + -alis","meaning":"of a cause","meaningCN":"原因的"},{"word":"causalitas","structure":"causalis + -itas","meaning":"causality, causal quality","meaningCN":"因果性；因果性质"}]}},{"word":"cautiously","ipa_uk":"/ˈkɔːʃəsli/","ipa_us":"/ˈkɔːʃəsli/","definition_zh":"谨慎地；小心地；审慎地；有保留地","definition_en":"in a careful way that avoids unnecessary risk, or with deliberate restraint","core_image":"一只手先伸出一寸试探地面，确认结实后才把整个重心移过去","scene":"雨夜的盘山公路上，司机把车速降到很低。On the mountain road at night, the driver slows down and takes the blind bend cautiously.","sceneCN":"这里 cautiously 是「小心地、谨慎地」（第 1、2 个义项：避免危险与缓慢移动）；句意：雨夜的盘山公路上，司机放慢车速，小心地转过看不清边界的弯。图中可辨识物件：雨刷、车灯、弯道标线、湿滑路面。","pos":[{"tag":"adv.","zh":"谨慎地；小心地；审慎地"}],"collocations":[{"phrase":"cautiously optimistic","zh":"谨慎乐观的"},{"phrase":"proceed cautiously","zh":"谨慎推进"},{"phrase":"cautiously worded","zh":"措辞谨慎的"},{"phrase":"drive cautiously","zh":"小心驾驶"},{"phrase":"cautiously welcome","zh":"谨慎地欢迎"},{"phrase":"move cautiously","zh":"小心移动"}],"forms":[{"label":"原级（副词）","form":"cautiously"},{"label":"比较级（更谨慎地）","form":"more cautiously"},{"label":"最高级（最谨慎地）","form":"most cautiously"}],"derivatives":[{"word":"cautious","pos":"adj.","zh":"谨慎的；小心的"},{"word":"caution","pos":"n.","zh":"谨慎；警告；保证金"},{"word":"cautiousness","pos":"n.","zh":"谨慎；小心"},{"word":"incautious","pos":"adj.","zh":"不谨慎的；轻率的"}],"senses":[{"no":"01","title":"Acting so as to avoid danger","titleCN":"为避免危险而行动","definition":"in a way that carefully avoids risk or harm","definitionCN":"以小心避开风险或伤害的方式","example":"She cautiously opened the door and looked inside.","exampleCN":"她小心地打开门，往里看。","why":"Latin cavere meant 'to beware, to guard against'. The adverb keeps that original posture: the actor is watching for harm before moving.","whyCN":"拉丁语 cavere 意为“当心、防备”。这个副词保留了最初的姿态：行动者在移动之前先留意伤害。"},{"no":"02","title":"Slowly and carefully, in movement","titleCN":"缓慢而小心地移动","definition":"of physical movement, slowly and with close attention to footing or surroundings","definitionCN":"指身体移动缓慢，并密切注意脚下或周围","example":"He cautiously stepped onto the icy bridge.","exampleCN":"他小心翼翼地踏上结冰的桥。","why":"Caution shows in the body before it shows in speech. The adverb describes a gait: short steps, weight tested, eyes down.","whyCN":"谨慎先显现在身体上，再显现在言语上。这个副词描述的是一种步态：步子短，重心先试探，眼睛向下看。"},{"no":"03","title":"Judging without rushing","titleCN":"不轻率地下判断","definition":"in a way that withholds judgement until enough evidence is available","definitionCN":"在获得足够证据之前不作判断的方式","example":"The committee cautiously endorsed the proposal.","exampleCN":"委员会审慎地认可了这项提案。","why":"The danger is no longer physical. Caution becomes a mental habit: do not commit until the ground has been tested.","whyCN":"危险不再是身体上的。谨慎变成一种心智习惯：在地面被试探过之前，不要承诺。"},{"no":"04","title":"Testing the ground first","titleCN":"先试探再前进","definition":"in a tentative way, making a small move before a larger one","definitionCN":"以试探的方式，先小步行动再大步前进","example":"They cautiously raised the idea before asking for funding.","exampleCN":"在申请经费之前，他们先谨慎地提出了这个想法。","why":"This sense is about sequence rather than speed: the first move is deliberately small so that a retreat is still possible.","whyCN":"这一义讲的是次序而非速度：第一步故意迈得很小，以便仍然可以后退。"},{"no":"05","title":"With a reservation: cautiously optimistic","titleCN":"有保留地乐观","definition":"in the phrase cautiously optimistic, hopeful but aware that things may still go wrong","definitionCN":"用于 cautiously optimistic，表示抱有希望但也知道事情仍可能出错","example":"Doctors are cautiously optimistic about her recovery.","exampleCN":"医生对她的康复持谨慎乐观态度。","why":"The adverb limits the adjective. It allows hope while refusing to promise, which is exactly what caution does to a judgement.","whyCN":"这个副词限制了形容词。它允许希望，却拒绝承诺，这正是谨慎对判断所做的事。"},{"no":"06","title":"With carefully chosen words","titleCN":"措辞谨慎地","definition":"in language that avoids overstatement, commitment or giving offence","definitionCN":"以避免夸大、承诺或冒犯的语言","example":"The statement was cautiously worded to leave room for negotiation.","exampleCN":"这份声明措辞谨慎，为谈判留出余地。","why":"Words can also be dangerous. Caution moves from the body to the sentence, and the adverb marks language that has been checked before it was released.","whyCN":"言语也可能是危险的。谨慎从身体移到句子上，这个副词标示那些在说出口之前已被检查过的语言。"},{"no":"07","title":"Spending or using with restraint","titleCN":"节制地使用","definition":"in a way that avoids waste or excessive use of money, energy or resources","definitionCN":"以避免浪费或过度使用金钱、精力或资源的方式","example":"The company cautiously invested in the new market.","exampleCN":"公司谨慎地投资这个新市场。","why":"The risk here is loss rather than injury. Caution becomes economy: put in only what can be afforded to lose.","whyCN":"这里的风险是损失而非受伤。谨慎变成节制：只投入输得起的部分。"},{"no":"08","title":"Handling something delicate","titleCN":"小心处理敏感事物","definition":"in a way that treats a sensitive matter or fragile object with special care","definitionCN":"以特别小心的方式对待敏感事务或易碎物品","example":"The archive cautiously released the personal letters.","exampleCN":"档案馆谨慎地公开了这些私人信件。","why":"What is handled may be fragile in a physical or social sense. The adverb warns that a wrong touch would do damage that cannot be undone.","whyCN":"被处理的对象可能在物理或社会意义上易碎。这个副词警告：一次错误的触碰会造成无法挽回的损害。"},{"no":"09","title":"Welcoming without full endorsement","titleCN":"谨慎地欢迎","definition":"in the phrase cautiously welcome, to accept something positively while keeping doubts","definitionCN":"用于 cautiously welcome，表示正面接受某事但仍保留疑虑","example":"Rights groups cautiously welcomed the new law.","exampleCN":"人权组织谨慎地欢迎这项新法律。","why":"Welcome is warm; cautiously cools it. The pair is a formula for public statements that must not appear either hostile or naive.","whyCN":"welcome 是热烈的，cautiously 让它降温。这个搭配是公共声明的公式，既不能显得敌意，也不能显得天真。"}],"etymology":{"intro":{"en":"Cautiously is a three-step derivative: Latin cautio became English caution, caution plus -ous became cautious, and cautious plus -ly became the adverb. The Latin noun first meant a legal security, not a mental habit, and that shift is visible in the history of caution.","cn":"cautiously 是三步派生：拉丁语 cautio 变成英语 caution，caution 加 -ous 成 cautious，cautious 加 -ly 成副词。这个拉丁名词最初指法律上的担保，而不是心智习惯；这一偏移在 caution 的历史中看得见。"},"items":[{"era":"LATIN cavere","en":"Cavere meant 'to beware, take heed, guard against'. It was a verb of watching and avoiding, used for both physical danger and legal risk.","cn":"cavere 意为“当心、留意、防备”。它是一个看顾与回避的动词，既用于身体危险，也用于法律风险。"},{"era":"LATIN cautio","en":"Cautio, from the participle cautus, meant 'caution, precaution' but also 'a bond, a security, a guarantee'. Roman law used it for the formal assurance one party gave another.","cn":"cautio 出自分词 cautus，意为“谨慎、预防”，但也指“保证、担保、契约”。罗马法用它指一方给另一方的正式保证。"},{"era":"OLD FRENCH caution","en":"Old French caution carried both the 'precaution' and the 'security' senses. English borrowed the noun with the legal sense still prominent.","cn":"古法语 caution 同时携带“预防”与“担保”两义。英语借入这个名词时，法律义仍然突出。"},{"era":"16C. ENGLISH caution","en":"In 16th-century English, caution often meant a pledge or security, and 'give caution' meant to provide a guarantee. The sense 'care to avoid danger' grew beside it.","cn":"在 16 世纪英语中，caution 常指保证或担保，give caution 意为提供担保。“避免危险的谨慎”这一义在旁边成长起来。"},{"era":"17C. cautious + -ly","en":"Cautious was formed with -ous, 'full of', and the adverb cautiously with -ly, from Old English -lice. By the 17th century the mental sense had won.","cn":"cautious 由 -ous“充满……的”构成，副词 cautiously 再由 -ly（来自古英语 -lice）构成。到 17 世纪，心智义已经胜出。"},{"era":"MODERN ENGLISH","en":"Cautiously now modifies verbs of movement, speech, investment and judgement. Fixed pairs such as cautiously optimistic and cautiously welcome turn the adverb into a diplomatic formula.","cn":"cautiously 如今修饰移动、言语、投资与判断的动词。cautiously optimistic 与 cautiously welcome 这类固定搭配，把这个副词变成了外交辞令。"}]},"similar":{"note":{"en":"The first group separates the adverb from its adjective, noun and one look-alike relative. The second group compares kinds of careful behaviour.","cn":"第一组把副词与它的形容词、名词以及一个形近亲属分开。第二组比较几种小心行事的方式。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"cautious","ipa":"/ˈkɔːʃəs/","tag":"base adjective","definition":"careful to avoid danger. Cautiously is simply its adverb form.","definitionCN":"小心避免危险的。cautiously 就是它的副词形式。"},{"word":"caution","ipa":"/ˈkɔːʃn/","tag":"base noun","definition":"care to avoid danger, a warning, or a legal security. It is the noun from which cautious was built.","definitionCN":"避免危险的谨慎、警告，或法律担保。它是构成 cautious 的名词。"},{"word":"precaution","ipa":"/prɪˈkɔːʃn/","tag":"prefixed relative","definition":"a measure taken in advance to prevent harm. It is pre- plus caution, so it looks close but adds the idea of doing something beforehand.","definitionCN":"为防害而事先采取的措施。它是 pre- 加 caution，形近但多出“事先行动”的意思。"}]},{"heading":"NEAR MEANING","entries":[{"word":"carefully","ipa":"/ˈkeəfəli/","tag":"attention","definition":"with attention to detail and to avoiding mistakes. It is broader than cautiously and does not always imply danger.","definitionCN":"注意细节、避免出错。它比 cautiously 更宽，并不总含危险意味。"},{"word":"warily","ipa":"/ˈweərəli/","tag":"suspicion","definition":"with suspicion of possible danger or deceit. It adds distrust that cautiously does not necessarily carry.","definitionCN":"带着对危险或欺骗的怀疑。它加上一层 cautiously 未必有的不信任。"},{"word":"prudently","ipa":"/ˈpruːdəntli/","tag":"long-term","definition":"with wise attention to future consequences. It is about good management over time, not immediate danger.","definitionCN":"明智地顾及未来后果。它讲的是长期的良好管理，而不是眼前的危险。"},{"word":"gingerly","ipa":"/ˈdʒɪndʒəli/","tag":"touch","definition":"with extreme care in touching or moving something fragile. It is narrower and more physical than cautiously.","definitionCN":"触碰或移动易碎物时极其小心。它比 cautiously 更窄、更身体化。"}]}]},"mnemonics":{"normalIntro":{"en":"These hooks build the adverb through its two suffixes and attach it to the fixed phrases that carry its modern tone.","cn":"这些记忆钩通过两个后缀搭起这个副词，并把它系到承载现代语气的固定搭配上。"},"normal":[{"en":"See the chain: caution, cautious, cautiously. Each step adds one suffix.","cn":"看见链条：caution、cautious、cautiously。每一步加一个后缀。"},{"en":"Link caution to cavere, to beware: the adverb is a watching posture.","cn":"把 caution 连到 cavere“当心”：这个副词是一种守望姿态。"},{"en":"Pair it with optimistic to remember the reservation.","cn":"与 optimistic 配对，记住“有保留”这一层。"},{"en":"Pair it with worded to remember careful language.","cn":"与 worded 配对，记住谨慎措辞。"},{"en":"Remember the body image: short steps on ice.","cn":"记住身体意象：在冰上迈小步。"}],"abstract":[{"en":"Hold one posture: test the ground before shifting weight. Every sense is that posture applied to something new.","cn":"抓住一个姿态：移重心之前先试探地面。每个义项都是这个姿态用在新对象上。"},{"en":"Sort the senses by object: danger, movement, judgement, trial, hope, language, money, delicate matter, welcome.","cn":"按对象分组：危险、移动、判断、试探、希望、语言、金钱、敏感事务、欢迎。"},{"en":"Remember the register: cautiously often cools a warm word rather than adding fear.","cn":"记住语体：cautiously 常常是给热烈的词降温，而不是添加恐惧。"}]},"examples":[{"en":"The hikers moved cautiously along the wet ridge.","cn":"徒步者沿着湿滑的山脊小心前进。"},{"en":"Analysts remain cautiously optimistic about the recovery.","cn":"分析师对复苏仍持谨慎乐观态度。"},{"en":"The agreement was cautiously worded to avoid a binding promise.","cn":"这份协议措辞谨慎，以免形成有约束力的承诺。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音“考神利”：考试前先“考”虑风“险”，再“利”用机会——cautiously 就是谨慎地。","word":"cautiously"},"root":"拉丁语 cavere“当心、防备”的过去分词 cautus，派生名词 cautio“谨慎、担保”；经古法语 caution 进入英语，加 -ous 成 cautious，再加 -ly 成 cautiously。","sensesIntro":{"en":"Cautiously is a posture turned into an adverb. It can describe the body (short steps), the mind (withheld judgement), the wallet (restrained spending), the sentence (careful wording) or the official statement (cautiously optimistic). In all of them the same move occurs: reduce the exposure before you commit.","cn":"cautiously 是把一种姿态变成副词。它可以描述身体（小步）、心智（暂缓判断）、钱包（节制支出）、句子（谨慎措辞）或官方声明（谨慎乐观）。在所有这些用法中，发生的都是同一个动作：在承诺之前先减少暴露。"},"semanticMap":{"core":{"en":"Test the ground before shifting weight: act with reduced exposure to harm.","cn":"移重心之前先试探地面：减少暴露于伤害地行动。"},"chain":["BEWARE","WATCH","SLOW","TEST","LIMIT","RESERVE"],"branches":[{"senses":"S1 · S2","en":"BODY: avoiding danger and moving with short, tested steps.","cn":"身体：避开危险，以试探性的小步移动。"},{"senses":"S3 · S4","en":"MIND: withholding judgement, then making a small first move.","cn":"心智：暂缓判断，然后先迈出小步。"},{"senses":"S5 · S9","en":"RESERVATION: hope and welcome that stop short of a promise.","cn":"保留：希望与欢迎都停在承诺之前。"},{"senses":"S6 · S8","en":"LANGUAGE AND HANDLING: checked words, delicate matters.","cn":"语言与处理：检查过的措辞、敏感的事务。"},{"senses":"S7","en":"MONEY: investing only what can be risked.","cn":"金钱：只投入输得起的部分。"}]},"affixes":{"intro":{"en":"Cautiously stacks three layers: the Latin noun cautio, the adjective suffix -ous, and the adverb suffix -ly. The list follows that chain and adds the prefixed relatives in- and pre-.","cn":"cautiously 叠了三层：拉丁名词 cautio、形容词后缀 -ous、副词后缀 -ly。清单沿着这条链展开，并加上前缀亲属 in- 与 pre-。"},"latinIntro":{"en":"The Latin entries give the verb of bewaring, its participle, and the noun that first meant a legal guarantee. They explain why caution still sounds slightly formal.","cn":"拉丁语条目给出“当心”的动词、其分词，以及最初指法律担保的名词。它们解释了为什么 caution 至今仍略带正式感。"},"items":[{"word":"cautiously","structure":"cautious + -ly (adverb suffix)","meaning":"in a careful, risk-avoiding way","meaningCN":"谨慎地；小心地","example":"Drive cautiously in the rain.","exampleCN":"雨天要小心驾驶。"},{"word":"cautious","structure":"caution + -ous (adjective suffix)","meaning":"careful to avoid danger","meaningCN":"谨慎的；小心的","example":"She gave a cautious answer.","exampleCN":"她给了一个谨慎的回答。"},{"word":"caution","structure":"Latin cautio, through Old French","meaning":"care to avoid danger; a warning; a security","meaningCN":"谨慎；警告；担保","example":"Proceed with caution.","exampleCN":"谨慎前行。"},{"word":"cautionary","structure":"caution + -ary (adjective suffix)","meaning":"serving as a warning","meaningCN":"警告性的；警戒的","example":"The story is a cautionary tale.","exampleCN":"这个故事是一个警示。"},{"word":"incautious","structure":"in- (not) + cautious","meaning":"not careful; rash","meaningCN":"不谨慎的；轻率的","example":"An incautious remark caused the quarrel.","exampleCN":"一句轻率的话引发了争吵。"},{"word":"cautiousness","structure":"cautious + -ness (noun suffix)","meaning":"the quality of being cautious","meaningCN":"谨慎；小心","example":"His cautiousness slowed the deal.","exampleCN":"他的谨慎拖慢了交易。"},{"word":"precaution","structure":"pre- (before) + caution","meaning":"a measure taken in advance against harm","meaningCN":"预防措施","example":"Take precautions against fire.","exampleCN":"采取防火措施。"},{"word":"caveat","structure":"Latin cavere + -at (let him beware)","meaning":"a warning or condition attached to an offer","meaningCN":"警告；附加条件","example":"The offer comes with one caveat.","exampleCN":"这项提议附带一个条件。"},{"word":"caution sign","structure":"caution + sign (compound noun)","meaning":"a sign warning of a hazard","meaningCN":"警告标志","example":"A caution sign stood by the wet floor.","exampleCN":"湿地旁立着一个警告标志。"},{"word":"caution tape","structure":"caution + tape (compound noun)","meaning":"bright tape used to mark a hazard","meaningCN":"警戒带","example":"Police cordoned the area with caution tape.","exampleCN":"警察用警戒带封锁了该区域。"}],"latinEntries":[{"word":"cavere","structure":"root verb (2nd conjugation)","meaning":"to beware, take heed, guard against","meaningCN":"当心；留意；防备"},{"word":"cautus","structure":"past participle of cavere","meaning":"wary, careful","meaningCN":"警惕的；小心的"},{"word":"cautio","structure":"cautus + -tio (action noun)","meaning":"caution; a security or guarantee","meaningCN":"谨慎；担保；保证"}]}},{"word":"certainty","ipa_uk":"/ˈsɜːtnti/","ipa_us":"/ˈsɜːrtnti/","definition_zh":"确定性；必然性；确信；必然之事","definition_en":"the state of being definitely true or of being firmly convinced, or something that cannot fail to happen","core_image":"一块石头被放上秤，指针不再晃动，停在刻度上不动了","scene":"实验室里，研究员把样品重复测了三次，数值完全一致。In the lab, the researcher runs the sample three times, gets the same figure, and finally writes it down with certainty.","sceneCN":"这里 certainty 是「确定性」（第 1、4 个义项：客观为真与认知上的确定）；句意：研究员把样品测了三次，数值完全一致，终于带着确定性把它记下。图中可辨识物件：天平、刻度指针、记录本、三支试管。","pos":[{"tag":"n.","zh":"确定性；必然性；确信；必然之事"}],"collocations":[{"phrase":"with certainty","zh":"确凿地；有把握地"},{"phrase":"absolute certainty","zh":"绝对的确定性"},{"phrase":"a near certainty","zh":"几乎必然的事"},{"phrase":"legal certainty","zh":"法律确定性"},{"phrase":"moral certainty","zh":"道德上的确信"},{"phrase":"certainty equivalent","zh":"确定性等值"}],"forms":[{"label":"单数（不可数，抽象义）","form":"certainty"},{"label":"复数（可数，指具体必然之事）","form":"certainties"},{"label":"常见搭配形式","form":"with certainty"}],"derivatives":[{"word":"certain","pos":"adj.","zh":"确定的；某一的；一定的"},{"word":"certainly","pos":"adv.","zh":"无疑；当然"},{"word":"uncertain","pos":"adj.","zh":"不确定的；没有把握的"},{"word":"ascertain","pos":"v.","zh":"查明；确定"}],"senses":[{"no":"01","title":"The state of being definitely true","titleCN":"确实为真的状态","definition":"the quality of being established as true beyond doubt","definitionCN":"被确立为毫无疑问为真的性质","example":"The certainty of the result surprised even the researchers.","exampleCN":"结果的确定性连研究人员自己都感到意外。","why":"Certainty is built on certus, 'settled, decided'. Something is certain when the question has been closed, not merely when most people believe it.","whyCN":"certainty 建立在 certus“已定、已决”之上。一件事是确定的，是因为问题已经闭合，而不只是因为多数人相信。"},{"no":"02","title":"Firm personal conviction","titleCN":"坚定的个人确信","definition":"a strong inner state of being sure, even without external proof","definitionCN":"内心强烈地相信，即使没有外部证据","example":"She spoke with the certainty of someone who had seen it herself.","exampleCN":"她说话时的确信，像是一个亲眼见过的人。","why":"The noun can point inward: not the fact but the person's grip on the fact. This sense is about how firmly a mind holds, not about how well the world supports it.","whyCN":"这个名词可以指向内部：不是事实本身，而是人对事实的把握。这一义讲的是心智握得多紧，而不是世界提供多少支持。"},{"no":"03","title":"Something that is sure to happen","titleCN":"必然会发生的事","definition":"a countable event or outcome that cannot fail to occur","definitionCN":"可数的、不可能不发生的事件或结果","example":"Death and taxes are called the two certainties of life.","exampleCN":"死亡与税收被称作人生两大必然之事。","why":"Here the abstract quality becomes a countable thing. English allows the shift: what is certain in general can be listed as one certainty among others.","whyCN":"在这里，抽象性质变成了可数之物。英语允许这种转换：总体上确定的东西，可以被列为众多必然之事中的一个。"},{"no":"04","title":"Certainty as a philosophical category","titleCN":"作为哲学范畴的确定性","definition":"in epistemology, the highest degree of justified confidence a belief can have","definitionCN":"在认识论中，一个信念所能拥有的最高程度的正当确信","example":"Descartes searched for one certainty on which to rebuild knowledge.","exampleCN":"笛卡尔寻找一个确定性，以重建全部知识。","why":"Philosophy turned certainty into a grade of knowledge. The word no longer describes a feeling or an event but a position on a scale from doubt to proof.","whyCN":"哲学把 certainty 变成一个知识等级。这个词不再描述感觉或事件，而是描述从怀疑到证明这一刻度上的位置。"},{"no":"05","title":"Legal certainty","titleCN":"法律确定性","definition":"the principle that law should be clear, stable and predictable","definitionCN":"法律应当清晰、稳定、可预期的原则","example":"Investors rely on legal certainty before committing capital.","exampleCN":"投资者在投入资本之前依赖法律确定性。","why":"In law the word is not about truth but about predictability: a rule that cannot be read two ways gives people a stable ground for planning.","whyCN":"在法律中，这个词讲的不是真，而是可预期：一条不会被读成两种意思的规则，给人稳定的规划基础。"},{"no":"06","title":"Mathematical or logical certainty","titleCN":"数学或逻辑上的必然","definition":"the property of a statement that is true in every possible case","definitionCN":"一个陈述在所有可能情形下都为真的性质","example":"A proof aims at certainty, not at high probability.","exampleCN":"证明追求的是必然性，而不是高概率。","why":"Mathematics uses the word for conclusions that cannot be otherwise. The contrast is with empirical fields, where the best result is still probability.","whyCN":"数学用这个词指不可能有别的样子的结论。对比对象是经验领域，那里最好的结果仍然只是概率。"},{"no":"07","title":"Religious certainty","titleCN":"宗教上的确信","definition":"a faith held without doubt, often described as inner assurance","definitionCN":"不带怀疑的信仰，常被描述为内心的确证","example":"He preached with a certainty that drew large crowds.","exampleCN":"他讲道时带着一种确信，吸引了大量听众。","why":"Religious language borrows the noun for a conviction that does not depend on evidence. Here certainty is a gift of faith rather than a result of proof.","whyCN":"宗教语言借用这个名词，指一种不依赖证据的确信。在这里，确定性是信仰的赐予，而不是证明的结果。"},{"no":"08","title":"Statistical confidence","titleCN":"统计上的置信度","definition":"in statistics, the degree to which a result is not attributed to chance","definitionCN":"在统计中，结果不被归因于偶然的程度","example":"The study reports its findings at ninety-five percent certainty.","exampleCN":"这项研究以百分之九十五的置信度报告其结论。","why":"Science had to soften the word: it speaks of confidence levels because absolute certainty is rarely available. The noun survives with a measured number attached.","whyCN":"科学不得不软化这个词：它说的是置信水平，因为绝对的确定性很少可得。这个名词带着一个量化的数字存活下来。"},{"no":"09","title":"In the phrase with certainty","titleCN":"用于 with certainty","definition":"in the fixed phrase with certainty, meaning in a way that leaves no doubt","definitionCN":"用于固定搭配 with certainty，表示不留疑问地","example":"No one can say with certainty what caused the collapse.","exampleCN":"没有人能确凿地说出坍塌的原因。","why":"The preposition turns the abstract noun into an adverbial phrase. With certainty is what a cautious expert says when asked for a conclusion.","whyCN":"介词把这个抽象名词变成副词性短语。with certainty 是谨慎的专家在被要求下结论时说的话。"}],"etymology":{"intro":{"en":"Certainty is a nominal derivative of certain, which descends from Latin certus, itself tied to the verb cernere, 'to sift, to decide'. The suffix -ty (Latin -tas, through French -té) turns the adjective into the name of a state. The word's history moves from 'decided' to 'true beyond doubt'.","cn":"certainty 是 certain 的名词派生，certain 来自拉丁语 certus，而 certus 又与动词 cernere“筛分、判定”相连。后缀 -ty（拉丁 -tas，经法语 -té）把形容词变成状态名称。这个词的历史从“已判定”走向“无可怀疑地为真”。"},"items":[{"era":"LATIN cernere","en":"Cernere meant 'to sift, to separate, to distinguish', and from that 'to discern, to decide'. A legal judgement and a physical sieve share one image: separating what belongs from what does not.","cn":"cernere 意为“筛、分离、辨别”，由此引申为“看清、判定”。法律裁决与物理筛子共享一个意象：把属于的与不属于的分开。"},{"era":"LATIN certus","en":"Certus, originally the participle of cernere, meant 'sifted, settled, decided'. It described a matter no longer open, and only later acquired the colour of 'sure, undoubted'.","cn":"certus 原为 cernere 的分词，意为“已筛过、已定、已决”。它描述一件不再开放的事，后来才染上“可靠、无可怀疑”的色彩。"},{"era":"LATIN certitudo","en":"Certitudo was the classical abstract noun: certus plus -tudo. It named the quality of being settled, and it is the direct model for the English suffix pattern.","cn":"certitudo 是古典拉丁的抽象名词：certus 加 -tudo。它命名“已定”的性质，也是英语后缀模式的直接样板。"},{"era":"OLD FRENCH certaineté","en":"Old French formed certaineté in the 12th century, replacing Latin -tudo with the inherited -té. The word reached Middle English as certeinte in the 14th century.","cn":"古法语在 12 世纪造出 certaineté，用本土的 -té 替换拉丁 -tudo。这个词在 14 世纪以 certeinte 进入中古英语。"},{"era":"16C.-17C. ENGLISH certainty","en":"English settled on certainty and used it in two directions: an objective fact that cannot be otherwise, and a subjective state of no doubt. Philosophy in the 17th century sharpened both.","cn":"英语定型为 certainty，并把它用在两个方向：不可能有别的样子的客观事实，以及主观上无疑的状态。17 世纪的哲学把两者都磨得更锋利。"},{"era":"MODERN ENGLISH","en":"Modern English keeps the countable plural (the certainties of life) and adds technical uses such as legal certainty and statistical confidence. The suffix -ty still marks a measured state rather than a passing feeling.","cn":"现代英语保留可数复数（人生的必然之事），并增加法律确定性、统计置信等技术用法。后缀 -ty 仍标示一种可量度的状态，而非一时的感觉。"}]},"similar":{"note":{"en":"The first group separates certainty from three words built on the same stem or sound. The second group compares degrees and kinds of being sure.","cn":"第一组把 certainty 与三个同根或同音的邻近词分开。第二组比较“有把握”的不同程度与类型。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"certain","ipa":"/ˈsɜːtn/","tag":"base adjective","definition":"sure, or referring to an unspecified one. Certainty is the noun built from it.","definitionCN":"确定的，或指某一个不特指的。certainty 是由它构成的名词。"},{"word":"certainly","ipa":"/ˈsɜːtnli/","tag":"adverb","definition":"without doubt, or used as a strong yes. It modifies a verb; certainty names a state.","definitionCN":"无疑地，或用作强烈的肯定。它修饰动词；certainty 命名一种状态。"},{"word":"certification","ipa":"/ˌsɜːtɪfɪˈkeɪʃn/","tag":"look-alike noun","definition":"official confirmation of a fact or standard. It looks close but is built on certify, not on certain.","definitionCN":"对事实或标准的官方确认。它形近，但由 certify 构成，而非 certain。"}]},{"heading":"NEAR MEANING","entries":[{"word":"assurance","ipa":"/əˈʃʊərəns/","tag":"given confidence","definition":"confidence that comes from another person's promise or from evidence. It often implies someone else has made you sure.","definitionCN":"因他人的承诺或证据而来的把握。它常含“别人让你确信”的意思。"},{"word":"conviction","ipa":"/kənˈvɪkʃn/","tag":"held belief","definition":"a firmly held belief, especially one that guides action. It is personal and moral where certainty can be neutral and factual.","definitionCN":"坚定持有的信念，尤指指导行动的信念。它偏个人与道德，而 certainty 可以是中性的、事实性的。"},{"word":"confidence","ipa":"/ˈkɒnfɪdəns/","tag":"self-trust","definition":"trust in oneself or in an outcome, often graded rather than absolute. Certainty is stronger and less negotiable.","definitionCN":"对自己或对结果的信任，常有程度而非绝对。certainty 更强，也更不可协商。"},{"word":"sureness","ipa":"/ˈʃʊənəs/","tag":"manner","definition":"the quality of being sure, especially in movement or manner. It describes steadiness more than truth.","definitionCN":"有把握的性质，尤指动作或姿态上的。它更多描述稳定，而不是真。"}]}]},"mnemonics":{"normalIntro":{"en":"These hooks work through the stem certain and the two suffixes, then attach the word to the situations where English speakers actually use it.","cn":"这些记忆钩通过词干 certain 与两个后缀展开，再把词系到英语使用者实际使用它的场景上。"},"normal":[{"en":"See the chain: cernere, certus, certain, certainty. A sieve becomes a settled fact.","cn":"看链条：cernere、certus、certain、certainty。筛子变成已定的事实。"},{"en":"Remember -ty as the noun suffix: certain plus -ty makes the name of the state.","cn":"记住 -ty 是名词后缀：certain 加 -ty 得到状态的名称。"},{"en":"Keep the pair legal certainty for predictability, not truth.","cn":"记住 legal certainty 这一搭配：它指可预期，而非真。"},{"en":"Keep the pair with certainty for the cautious conclusion.","cn":"记住 with certainty 这一搭配：它用于谨慎的结论。"},{"en":"Note the plural certainties: abstract quality turned into listed facts.","cn":"注意复数 certainties：抽象性质变成被列举的事实。"}],"abstract":[{"en":"Hold one image: the needle stops moving. Certainty is the moment a scale stops wobbling.","cn":"抓住一个意象：指针停止晃动。确定性就是刻度不再摇摆的那一刻。"},{"en":"Sort the senses by question: is it true (S1), do I believe it (S2), will it happen (S3), can we prove it (S4, S6), can we plan on it (S5), what do we trust (S7, S8).","cn":"按问题分组：它真吗（S1）、我信吗（S2）、会发生吗（S3）、能证明吗（S4、S6）、能据此规划吗（S5）、我们信什么（S7、S8）。"},{"en":"Notice the temperature: certainty is cold and factual, assurance is warm because someone gave it to you.","cn":"留意温度：certainty 冷而事实化，assurance 暖，因为它是别人给你的。"}]},"examples":[{"en":"There is no certainty that the treaty will be ratified.","cn":"条约能否获批并无确定把握。"},{"en":"She answered with the calm certainty of long practice.","cn":"她以长期训练带来的平静确信作答。"},{"en":"Rising costs are one of the certainties of the coming decade.","cn":"成本上升是未来十年必然会发生的事情之一。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音“舍疼提”：该舍的、该疼的、该提的，早在心里定好了数，不必再犹豫——这就是 certainty，确定性。","word":"certainty"},"root":"拉丁语 cernere“筛分、判定”的分词 certus“已定的”，抽象名词 certitudo；经古法语 certaineté 进入中古英语，最终定型为 certainty（certain + -ty）。","sensesIntro":{"en":"Certainty covers a scale rather than a single point. At one end it is a fact that cannot be otherwise; at the other it is a person's firm grip on that fact. Between them sit the countable certainties of daily life, the legal demand for predictability, the mathematician's proof and the statistician's confidence level. Every sense answers the same question in a different register: how far has doubt been closed?","cn":"certainty 覆盖的是一段刻度，而不是一个点。一端是不可能另有样子的客观事实，另一端是人对该事实的牢固把握。两者之间是日常生活中可数的必然之事、法律对可预期的要求、数学家的证明与统计学家的置信水平。每个义项都在不同语域回答同一个问题：怀疑被闭合到什么程度？"},"semanticMap":{"core":{"en":"The needle stops: doubt has been closed, whether by fact, proof, law or faith.","cn":"指针停住：无论靠事实、证明、法律还是信仰，怀疑已经闭合。"},"chain":["SIFT","DECIDE","SETTLE","STATE","OBJECT","MEASURE"],"branches":[{"senses":"S1 · S3","en":"FACT: the objective quality, and the countable things it produces.","cn":"事实：客观性质，以及由它产生的可数之事。"},{"senses":"S2 · S7","en":"MIND: personal conviction, including its religious form.","cn":"心智：个人确信，包括其宗教形式。"},{"senses":"S4 · S6","en":"PROOF: the philosophical category and the mathematical standard.","cn":"证明：哲学范畴与数学标准。"},{"senses":"S5","en":"LAW: certainty as predictability rather than truth.","cn":"法律：确定性即可预期，而非真。"},{"senses":"S8 · S9","en":"MEASURE: confidence levels, and the phrase for a cautious conclusion.","cn":"量度：置信水平，以及谨慎下结论的短语。"}]},"affixes":{"intro":{"en":"Certainty is a single suffix away from certain. The items below walk that suffix chain, then add the prefixed forms un- and a-, plus three fixed compounds that carry the word into law, finance and expert systems.","cn":"certainty 距 certain 只差一个后缀。下面的条目沿着这条后缀链展开，再加上前缀形式 un- 与 a-，以及三个把这个词带入法律、金融与专家系统的固定复合词。"},"latinIntro":{"en":"The Latin entries supply the verb of sifting, its participle, and the classical abstract noun. They show that certus already meant 'decided' before it meant 'true'.","cn":"拉丁语条目给出“筛分”的动词、其分词，以及古典抽象名词。它们说明 certus 在表示“真”之前，先表示“已决”。"},"items":[{"word":"certainty","structure":"certain + -ty (Latin -tas, through French -té)","meaning":"the state of being sure or definitely true","meaningCN":"确定性；必然","example":"We cannot predict the outcome with certainty.","exampleCN":"我们无法确凿地预测结果。"},{"word":"certain","structure":"Latin certus, 'settled, decided'","meaning":"sure; also, a particular but unnamed one","meaningCN":"确定的；某一","example":"I am certain that the door was locked.","exampleCN":"我确定门是锁上的。"},{"word":"certainly","structure":"certain + -ly (adverb suffix)","meaning":"without doubt; used as a firm yes","meaningCN":"无疑；当然","example":"Certainly, we can try again tomorrow.","exampleCN":"当然，我们明天可以再试。"},{"word":"uncertain","structure":"un- (not) + certain","meaning":"not sure; not decided","meaningCN":"不确定的；未定的","example":"The date of the vote remains uncertain.","exampleCN":"投票日期仍不确定。"},{"word":"uncertainty","structure":"un- (not) + certainty","meaning":"the state of not knowing or not being settled","meaningCN":"不确定性","example":"Uncertainty about funding delayed the project.","exampleCN":"资金上的不确定性拖慢了项目。"},{"word":"ascertain","structure":"a- (to) + certain (from Old French acertainer)","meaning":"to find out for certain","meaningCN":"查明；确定","example":"Police are trying to ascertain the cause of the fire.","exampleCN":"警方正努力查明火灾原因。"},{"word":"certitude","structure":"Latin certitudo, the classical abstract noun","meaning":"a formal word for complete certainty, often of faith","meaningCN":"确信（正式，常用于信仰）","example":"She spoke with an unshakable certitude.","exampleCN":"她以不可动摇的确信说话。"},{"word":"cert","structure":"clipped form of certainty, British informal","meaning":"something regarded as an absolute certainty","meaningCN":"十拿九稳的事（英式口语）","example":"He is a dead cert to win the seat.","exampleCN":"他稳赢这个席位。"},{"word":"certainty equivalent","structure":"certainty + equivalent (compound, finance)","meaning":"the guaranteed amount a risk-averse person would accept instead of a gamble","meaningCN":"确定性等值","example":"The certainty equivalent of the lottery was below its expected value.","exampleCN":"这笔抽奖的确定性等值低于其期望值。"},{"word":"certainty factor","structure":"certainty + factor (compound, expert systems)","meaning":"a number expressing confidence in a rule or conclusion in an expert system","meaningCN":"确定性因子（专家系统）","example":"Each rule carries a certainty factor between minus one and one.","exampleCN":"每条规则都带有一个负一到一之间的确定性因子。"}],"latinEntries":[{"word":"cernere","structure":"root verb (3rd conjugation)","meaning":"to sift, separate, discern, decide","meaningCN":"筛分；分离；辨别；判定"},{"word":"certus","structure":"participle of cernere, used as adjective","meaning":"settled, decided; sure","meaningCN":"已定的；确信的"},{"word":"certitudo","structure":"certus + -tudo (abstract noun)","meaning":"certainty, the quality of being settled","meaningCN":"确定性；已定的状态"}]}},{"word":"certification","ipa_uk":"/ˌsɜːtɪfɪˈkeɪʃn/","ipa_us":"/ˌsɜːrtəfəˈkeɪʃn/","definition_zh":"认证；证明；资格证书；资格认定","definition_en":"the official process of confirming that a person, product or fact meets a standard, or the document that records it","core_image":"一枚印章落在纸面上，同一张纸从“自称合格”变成“被机构确认合格”","scene":"建筑事务所的墙上挂着一张框好的证书，客户进门第一眼就看见它。A framed certificate hangs on the wall of the firm, and every client who walks in can see its certification.","sceneCN":"这里 certification 是「认证、资格认定」（第 1、3 个义项：认证过程与执业资格）；句意：事务所墙上挂着框好的证书，客户一进门就看得见它的认证。图中可辨识物件：证书边框、印章、公司铭牌、会客沙发。","pos":[{"tag":"n.","zh":"认证；证明；资格证书"}],"collocations":[{"phrase":"professional certification","zh":"专业资格认证"},{"phrase":"certification body","zh":"认证机构"},{"phrase":"certification exam","zh":"认证考试"},{"phrase":"certification program","zh":"认证项目"},{"phrase":"obtain certification","zh":"取得认证"},{"phrase":"certification requirement","zh":"认证要求"}],"forms":[{"label":"单数","form":"certification"},{"label":"复数（指多项认证）","form":"certifications"},{"label":"动词形式","form":"certify"}],"derivatives":[{"word":"certify","pos":"v.","zh":"证明；认证；确认"},{"word":"certificate","pos":"n.","zh":"证书；证明书"},{"word":"certified","pos":"adj.","zh":"已认证的；有执照的"},{"word":"certifiable","pos":"adj.","zh":"可证明的；可认证的"}],"senses":[{"no":"01","title":"The act of officially certifying","titleCN":"官方认证的行为","definition":"the process by which an authority formally confirms that something meets a standard","definitionCN":"权威机构正式确认某事物符合标准的程序","example":"Certification of the new aircraft took three years.","exampleCN":"这款新飞机的认证花了三年。","why":"The suffix -ation names the action, not the result. Certification is the review, testing and stamping, considered as a process.","whyCN":"后缀 -ation 命名动作，而不是结果。certification 是把审查、检测与盖章作为一个过程来看。"},{"no":"02","title":"The document that records it","titleCN":"记录认证的证书","definition":"the paper or digital record issued after a successful review","definitionCN":"审查通过后签发的纸质或数字记录","example":"The inspector asked to see the safety certification.","exampleCN":"检查员要求查看安全认证文件。","why":"Metonymy turns the act into its product. Speakers often say certification when they mean the certificate itself, because the paper is the visible trace of the process.","whyCN":"转喻把行为变成产物。说话人常说的 certification 其实指证书本身，因为那张纸是过程留下的可见痕迹。"},{"no":"03","title":"Professional credentialing","titleCN":"职业资格认定","definition":"the recognition that a person has the training and skills required for a profession","definitionCN":"对某人具备某职业所需训练与技能的承认","example":"She earned her teaching certification in her thirties.","exampleCN":"她三十多岁时取得了教师资格。","why":"Here the object certified is a person, not a thing. The word marks the boundary between being able to do a job and being allowed to do it.","whyCN":"这里被认证的对象是人，不是物。这个词划出“会做某工作”与“被允许做某工作”之间的界线。"},{"no":"04","title":"Product or standard certification","titleCN":"产品或标准认证","definition":"confirmation that a product complies with a technical or safety standard","definitionCN":"确认某产品符合技术或安全标准","example":"The label shows the device has international certification.","exampleCN":"标签显示该设备拥有国际认证。","why":"Industrial certification removes the need for every buyer to test every product. The stamp stands in for a test the buyer cannot perform.","whyCN":"工业认证免去了每个买家逐一检测每件产品的必要。那枚印章代替了买家无法执行的检测。"},{"no":"05","title":"Legal attestation","titleCN":"法律上的正式确认","definition":"the formal confirmation of a document, signature or fact by an authorised officer","definitionCN":"由授权官员对文件、签名或事实的正式确认","example":"The will requires certification by two witnesses.","exampleCN":"这份遗嘱需要两名见证人的正式确认。","why":"In law the word keeps its oldest function: making a fact safe to rely on. The certification does not create the fact, it makes the fact usable in court.","whyCN":"在法律中，这个词保留最古老的功能：让一个事实可以被依赖。认证不创造事实，而是让事实可以在法庭上使用。"},{"no":"06","title":"Medical certification of cause","titleCN":"医学上的死因认定","definition":"a doctor's formal statement of the cause of death or of fitness for work","definitionCN":"医生对死因或是否适合工作的正式陈述","example":"The death certificate is a form of medical certification.","exampleCN":"死亡证明是一种医学认证。","why":"This sense shows the word at its narrowest: one named professional, one signature, one legally defined fact. The authority is the licence, not the opinion.","whyCN":"这一义展示这个词最窄的用法：一位具名专业人士、一个签名、一项法律定义的事实。权威来自执照，而不是意见。"},{"no":"07","title":"Financial audit certification","titleCN":"财务审计认证","definition":"an auditor's formal statement that financial statements are fairly presented","definitionCN":"审计师对财务报表公允表达的正式陈述","example":"The bank will not lend without audited certification.","exampleCN":"没有经审计的认证，银行不会放贷。","why":"Finance uses certification to transfer trust. The auditor does not guarantee future profit, only that the numbers were prepared according to rules.","whyCN":"金融用认证来转移信任。审计师不保证未来利润，只保证数字是按规则编制的。"},{"no":"08","title":"Environmental or sustainability certification","titleCN":"环保或可持续认证","definition":"a third-party confirmation that a product or practice meets environmental criteria","definitionCN":"第三方对产品或做法符合环境标准的确认","example":"The coffee carries a fair-trade certification.","exampleCN":"这款咖啡带有公平贸易认证。","why":"Modern certification has expanded from safety to values. Buyers cannot verify a supply chain, so a third-party mark certifies claims they would otherwise have to take on trust.","whyCN":"现代认证从安全扩展到价值观。买家无法核实供应链，于是第三方标志为那些原本只能凭信任接受的声明作担保。"},{"no":"09","title":"Digital certification","titleCN":"数字证书认证","definition":"the issuing of a digital certificate that binds a public key to an identity","definitionCN":"签发数字证书，把公钥与某一身份绑定","example":"The website's certification had expired, so the browser warned users.","exampleCN":"该网站的证书已过期，浏览器向用户发出警告。","why":"The oldest meaning returns in a new medium: an authority vouches for an identity that the user cannot check directly. The stamp becomes a cryptographic signature.","whyCN":"最古老的含义在新媒介中回归：权威为一个用户无法直接核实的身份作担保。印章变成了密码学签名。"}],"etymology":{"intro":{"en":"Certification is certify plus -ation. Certify itself is a Late Latin compound: certus, 'settled', plus facere, 'to make', giving certificare, 'to make certain'. The word therefore does not mean 'to make a certificate' but 'to make something certain', and the modern document sense is a later narrowing.","cn":"certification 是 certify 加 -ation。certify 本身是晚期拉丁复合词：certus“已定”加 facere“做”，构成 certificare“使确定”。所以这个词本义不是“制作证书”，而是“使某事确定”；现代“证书”义是后来的窄化。"},"items":[{"era":"LATIN certus","en":"Certus meant 'settled, decided', from the verb cernere, 'to sift'. It supplied the first half of the compound and the idea of a matter no longer open.","cn":"certus 意为“已定、已决”，来自动词 cernere“筛分”。它提供了复合词的前半，以及“事情不再开放”的意思。"},{"era":"LATIN facere","en":"Facere, 'to make, to do', is one of the most productive Latin verbs. In compounds it means 'to cause to be', which is exactly the force it has here.","cn":"facere“做、造”是拉丁语最能产的动词之一。在复合词中它表示“使成为”，这正是它在此处的力量。"},{"era":"LATE LATIN certificare","en":"Certificare appears in Late Latin with the sense 'to make certain, to assure'. It was a legal and administrative verb before it was a commercial one.","cn":"certificare 在晚期拉丁中出现，意为“使确定、使确信”。在成为商业用语之前，它先是法律与行政动词。"},{"era":"OLD FRENCH certifier","en":"Old French took the verb as certifier, and English borrowed it in the 14th century as certify. The noun certificate came through Medieval Latin certificatum, 'a certified document'.","cn":"古法语把这个动词接为 certifier，英语在 14 世纪借入为 certify。名词 certificate 则经中世纪拉丁 certificatum“经认证的文件”而来。"},{"era":"17C. ENGLISH certification","en":"Certification, the noun of action, is recorded from the 17th century. Its early use was chiefly legal: the act of formally assuring a fact before an authority.","cn":"表示动作的名词 certification 自 17 世纪有记录。早期主要用于法律：在权威面前正式确认某一事实的行为。"},{"era":"MODERN ENGLISH","en":"Industry and the professions widened the word in the 19th and 20th centuries. Certification now covers people, products, accounts, supply chains and digital identities, while certificate stays with the paper.","cn":"工业与专业界在 19、20 世纪拓宽了这个词。certification 如今覆盖人、产品、账目、供应链与数字身份，而 certificate 仍留在纸张上。"}]},"similar":{"note":{"en":"The first group separates the noun of action from the verb, the document and the adjective. The second group compares the institutions that grant official recognition.","cn":"第一组把表示动作的名词与动词、文件、形容词分开。第二组比较授予官方认可的不同制度。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"certificate","ipa":"/ˈsɜːtɪfɪkət/","tag":"the document","definition":"the piece of paper or digital record itself. Certification is the process or the status; certificate is the object you can hang on a wall.","definitionCN":"证书本身那张纸或数字记录。certification 是过程或状态；certificate 是可以挂在墙上的物件。"},{"word":"certify","ipa":"/ˈsɜːtɪfaɪ/","tag":"the verb","definition":"to confirm officially. The verb takes the action; certification names it.","definitionCN":"正式确认。动词承担动作；certification 命名该动作。"},{"word":"certified","ipa":"/ˈsɜːtɪfaɪd/","tag":"the adjective","definition":"having received certification. It describes the person or product, not the process.","definitionCN":"已获得认证的。它描述人或产品，而不是过程。"}]},{"heading":"NEAR MEANING","entries":[{"word":"accreditation","ipa":"/ˌækredɪˈteɪʃn/","tag":"institutional","definition":"official recognition given to an institution or programme rather than to a single person or product. It is usually one level above certification.","definitionCN":"授予机构或项目的官方认可，而非单个人或产品。它通常比 certification 高一级。"},{"word":"licensing","ipa":"/ˈlaɪsnsɪŋ/","tag":"permission","definition":"the granting of legal permission to do something. A licence is required by law; a certification may be voluntary.","definitionCN":"授予做某事的法律许可。执照由法律要求；认证可以是自愿的。"},{"word":"attestation","ipa":"/əˈtesteɪʃn/","tag":"witnessing","definition":"formal witnessing or confirmation of a fact, especially a signature. It is narrower and more legal than certification.","definitionCN":"对事实、尤指签名的正式见证或确认。它比 certification 更窄、更法律化。"},{"word":"validation","ipa":"/ˈvælɪdeɪʃn/","tag":"checking","definition":"proof that something is valid or correct. It can be an internal check, while certification usually involves an outside authority.","definitionCN":"证明某事物有效或正确的过程。它可以是内部核查，而 certification 通常涉及外部权威。"}]}]},"mnemonics":{"normalIntro":{"en":"These hooks split the word into its two Latin halves and then attach it to the settings where certification is issued.","cn":"这些记忆钩把词拆成两个拉丁半部，再把它系到签发认证的各类场景上。"},"normal":[{"en":"Split it: cert (settled) plus fic (make) plus ation (action). To certify is to make something settled.","cn":"拆开：cert（已定）加 fic（做）加 ation（动作）。certify 就是使某事定下来。"},{"en":"Keep certificate for the paper, certification for the process.","cn":"记住：certificate 是纸，certification 是过程。"},{"en":"See the stamp: the same sheet before and after it is inked.","cn":"看那枚章：同一张纸，盖章前后不同。"},{"en":"Link it to a profession: teaching, nursing, accounting all require certification.","cn":"联系职业：教书、护理、会计都需要认证。"},{"en":"Link it to a product label: the mark on the box is someone else's test result.","cn":"联系产品标签：盒子上的标志是别人做过的检测结果。"}],"abstract":[{"en":"Hold one idea: certification transfers trust from a person to an authority, so a stranger can rely on the result.","cn":"抓住一个观念：认证把信任从个人转移到权威，使陌生人也能依赖这个结果。"},{"en":"Sort the senses by object: an act, a document, a person, a product, a signature, a cause of death, accounts, a supply chain, a digital identity.","cn":"按对象分组：行为、文件、人、产品、签名、死因、账目、供应链、数字身份。"},{"en":"Note the direction of history: the word began as 'make certain' and narrowed to 'issue a document'.","cn":"注意历史方向：这个词从“使确定”开始，后来窄化为“签发文件”。"}]},"examples":[{"en":"The laboratory lost its certification after the audit.","cn":"该实验室在审计后失去了认证资格。"},{"en":"Employers increasingly treat certification as a minimum requirement.","cn":"雇主越来越把认证当作最低要求。"},{"en":"Without certification, the device cannot be sold in the European Union.","cn":"没有认证，该设备无法在欧盟销售。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音“certain 飞 cation”：先 certain（确定），再“开审”（听成 cation），审完盖章发一张纸——certification 认证。","word":"certification"},"root":"拉丁语 certus“已定”加 facere“做”构成晚期拉丁 certificare“使确定”；经古法语 certifier 进入英语为 certify，再加 -ation 成 certification。","sensesIntro":{"en":"Certification is the modern name for a very old act: an authority says that something is settled. The object varies — a person's skills, a product's safety, a signature's authenticity, a company's accounts, a website's identity — but the structure does not. Someone who cannot check for themselves accepts a mark made by someone who can.","cn":"certification 是一个很古老行为在现代的名字：权威说某事已经确定。对象在变——人的技能、产品的安全、签名的真伪、公司的账目、网站的身份——结构却不变。无法自行核实的人，接受一个能够核实的人留下的标记。"},"semanticMap":{"core":{"en":"An outside authority turns a claim into a settled fact that strangers may rely on.","cn":"外部权威把一个声明变成陌生人可以依赖的已定事实。"},"chain":["CLAIM","REVIEW","TEST","CONFIRM","MARK","RELY"],"branches":[{"senses":"S1 · S2","en":"PROCESS AND PAPER: the act itself, and the record it leaves.","cn":"过程与纸张：行为本身，以及它留下的记录。"},{"senses":"S3","en":"PEOPLE: permission to practise a profession.","cn":"人：从事某职业的许可。"},{"senses":"S4 · S8","en":"THINGS: product standards and environmental claims.","cn":"物：产品标准与环保声明。"},{"senses":"S5 · S6 · S7","en":"RECORDS: signatures, causes of death, financial statements.","cn":"记录：签名、死因、财务报表。"},{"senses":"S9","en":"IDENTITY: the digital certificate, the old stamp in a new medium.","cn":"身份：数字证书，旧印章在新媒介中的版本。"}]},"affixes":{"intro":{"en":"Certification is built from certify plus -ation, and certify from the Latin pair certus and facere. The items follow that compound, then add the re- and de- forms that mark losing or regaining a credential.","cn":"certification 由 certify 加 -ation 构成，certify 又来自拉丁的 certus 与 facere 一对。条目沿这个复合词展开，再加上表示失去或重获资格的 re- 与 de- 形式。"},"latinIntro":{"en":"The Latin entries are the two halves of the compound and the Late Latin verb they produced. Together they explain why certification means 'making certain' rather than 'making a certificate'.","cn":"拉丁语条目是这个复合词的两个半部，以及它们产生的晚期拉丁动词。它们共同解释了为什么 certification 意为“使确定”，而不是“制作证书”。"},"items":[{"word":"certification","structure":"certify + -ation (action noun)","meaning":"the act or result of officially confirming a standard","meaningCN":"认证；证明","example":"The product received European certification.","exampleCN":"该产品获得了欧洲认证。"},{"word":"certify","structure":"Latin certificare, from certus + facere","meaning":"to confirm officially; to declare formally","meaningCN":"证明；认证；正式宣布","example":"The doctor certified him fit to work.","exampleCN":"医生证明他适合工作。"},{"word":"certificate","structure":"Medieval Latin certificatum, 'a certified document'","meaning":"an official document that records a fact or qualification","meaningCN":"证书；证明书","example":"Bring your birth certificate to the interview.","exampleCN":"面试时带上你的出生证明。"},{"word":"certified","structure":"certify + -ed (past participle adjective)","meaning":"having official confirmation","meaningCN":"已认证的；有执照的","example":"She is a certified accountant.","exampleCN":"她是一名注册会计师。"},{"word":"certifying","structure":"certify + -ing (present participle)","meaning":"performing the act of confirmation","meaningCN":"进行认证的","example":"The certifying body inspected the factory.","exampleCN":"认证机构检查了这家工厂。"},{"word":"certifier","structure":"certify + -er (agent noun)","meaning":"a person or body that certifies","meaningCN":"认证人；认证机构","example":"The certifier must be independent of the seller.","exampleCN":"认证方必须独立于卖方。"},{"word":"recertification","structure":"re- (again) + certification","meaning":"the renewal of an expired credential","meaningCN":"重新认证；换证","example":"Pilots need recertification every few years.","exampleCN":"飞行员每隔几年需要重新认证。"},{"word":"decertification","structure":"de- (remove) + certification","meaning":"the withdrawal of a certification","meaningCN":"撤销认证","example":"The union filed for decertification.","exampleCN":"工会提出了撤销认证的申请。"},{"word":"self-certification","structure":"self- + certification (compound)","meaning":"a declaration that one meets a standard, without outside inspection","meaningCN":"自我声明合规","example":"Small firms may use self-certification for low-risk work.","exampleCN":"小公司对低风险工程可采用自我声明。"},{"word":"certification body","structure":"certification + body (compound noun)","meaning":"an organisation authorised to issue certifications","meaningCN":"认证机构","example":"Only an accredited certification body can issue the mark.","exampleCN":"只有获认可的认证机构才能签发该标志。"}],"latinEntries":[{"word":"certus","structure":"adjective, participle of cernere","meaning":"settled, decided; sure","meaningCN":"已定的；确信的"},{"word":"facere","structure":"root verb (3rd conjugation)","meaning":"to make, to do; in compounds, to cause to be","meaningCN":"做；造；使成为"},{"word":"certificare","structure":"certus + facere, Late Latin","meaning":"to make certain, to assure formally","meaningCN":"使确定；正式保证"}]}},{"word":"chronological","ipa_uk":"/ˌkrɒnəˈlɒdʒɪkl/","ipa_us":"/ˌkrɑːnəˈlɑːdʒɪkl/","definition_zh":"按时间顺序的；年代学的；编年的","definition_en":"arranged in the order in which events happened, or relating to the study of dates and time sequences","core_image":"一条从左向右延伸的时间轴，事件像珠子一样按发生的先后串在上面","scene":"档案馆员把一叠信件摊在长桌上，按邮戳日期从最早排到最晚。The archivist spreads the letters on a long table and lays them out in chronological order by postmark date.","sceneCN":"这里 chronological 是「按时间顺序的」（第 1、3 个义项：时间排列与年代序列）；句意：馆员把信件摊在长桌上，按邮戳日期排成时间顺序。图中可辨识物件：长桌、邮戳、信纸、日期标签。","pos":[{"tag":"adj.","zh":"按时间顺序的；年代学的；编年的"}],"collocations":[{"phrase":"chronological order","zh":"时间顺序"},{"phrase":"chronological age","zh":"实际年龄"},{"phrase":"chronological sequence","zh":"时间序列"},{"phrase":"in chronological order","zh":"按时间顺序"},{"phrase":"reverse chronological order","zh":"倒序时间排列"},{"phrase":"chronological narrative","zh":"编年式叙述"}],"forms":[{"label":"原级","form":"chronological"},{"label":"比较级（更按时间顺序）","form":"more chronological"},{"label":"最高级（最按时间顺序）","form":"most chronological"}],"derivatives":[{"word":"chronology","pos":"n.","zh":"年代学；年表；时间顺序"},{"word":"chronologically","pos":"adv.","zh":"按时间顺序地"},{"word":"chronologist","pos":"n.","zh":"年代学家；年表学者"},{"word":"chronologer","pos":"n.","zh":"编年史家（较旧用法）"}],"senses":[{"no":"01","title":"Arranged by time of occurrence","titleCN":"按发生时间排列的","definition":"ordered from earliest to latest according to when things happened","definitionCN":"按照事情发生的先后，从最早到最晚排列","example":"The files are kept in chronological order.","exampleCN":"这些档案按时间顺序保存。","why":"Chronological answers one question only: which came first? It ignores importance, size and logic, and keeps a single axis.","whyCN":"chronological 只回答一个问题：哪个先发生？它不管重要性、规模与逻辑，只保留一条轴。"},{"no":"02","title":"Belonging to chronology as a discipline","titleCN":"属于年代学的","definition":"relating to the science of establishing and ordering dates","definitionCN":"与确定日期并排列日期的学问有关","example":"Chronological research fixed the date of the eclipse.","exampleCN":"年代学研究确定了那次日食的日期。","why":"Here the adjective describes a method, not an arrangement. The scholar is not sorting papers but testing whether a date can be trusted.","whyCN":"这里形容词描述一种方法，而不是一种排列。学者不是在整理纸堆，而是在检验一个日期是否可信。"},{"no":"03","title":"Of a sequence of records or events","titleCN":"指记录或事件的序列","definition":"describing a series whose items follow one another in time","definitionCN":"描述按时间先后相接的一系列项目","example":"The report gives a chronological account of the negotiations.","exampleCN":"报告按时间顺序叙述了谈判过程。","why":"A chronological account follows the clock rather than the argument. The reader learns what happened next, not what mattered most.","whyCN":"编年式叙述跟着时钟走，而不是跟着论点走。读者知道接下来发生了什么，而不是什么最重要。"},{"no":"04","title":"Of age order","titleCN":"按年龄顺序的","definition":"arranged by age, as of children in a class or siblings in a family","definitionCN":"按年龄排列，如班级里的孩子或家庭中的兄弟姐妹","example":"The children were seated in chronological order.","exampleCN":"孩子们按年龄顺序就座。","why":"Age is time made visible in a body. The adjective transfers the timeline from events to people, and the order becomes a seating plan.","whyCN":"年龄是时间在身体上的可见化。这个形容词把时间轴从事件移到人身上，顺序就变成了一张座位表。"},{"no":"05","title":"Chronological narrative form","titleCN":"编年体的叙述形式","definition":"a style of telling a story from beginning to end without flashbacks","definitionCN":"从头到尾讲述、不使用倒叙的叙事方式","example":"The film's chronological structure makes it feel like a documentary.","exampleCN":"影片的编年结构让它像一部纪录片。","why":"Storytellers usually rearrange time for effect. Calling a narrative chronological marks the absence of that rearrangement, and that absence is itself a style.","whyCN":"讲故事的人通常为了效果而重排时间。称一个叙述为 chronological，标示这种重排的缺席，而这种缺席本身就是一种风格。"},{"no":"06","title":"Geological time order","titleCN":"地质年代顺序","definition":"relating to the order of rock layers and past geological events","definitionCN":"与岩层及过去地质事件的先后有关","example":"Geologists established a chronological framework for the strata.","exampleCN":"地质学家为这些地层建立了年代框架。","why":"In geology the timeline is read from the ground up: lower layers are older. The adjective describes an order that the earth itself recorded.","whyCN":"在地质学中，时间轴要从下往上读：下层更古老。这个形容词描述的是大地自己记录下来的顺序。"},{"no":"07","title":"Chronological representation as a timeline","titleCN":"以时间轴呈现","definition":"shown on a line or chart where distance stands for elapsed time","definitionCN":"在一条线或图表上呈现，用距离表示流逝的时间","example":"The museum uses a chronological chart from 1800 to the present.","exampleCN":"博物馆使用一张从 1800 年至今的时间轴图。","why":"A timeline turns sequence into space. Once time is drawn as length, gaps and clusters become visible at a glance.","whyCN":"时间轴把先后变成空间。一旦时间被画成长度，空白与密集就一眼可见。"},{"no":"08","title":"Chronological age in contrast to other measures","titleCN":"与其它度量相对的实龄","definition":"in psychology and medicine, actual years lived, as opposed to mental or biological age","definitionCN":"在心理学与医学中，实际活过的年数，相对于心理年龄或生理年龄","example":"Her chronological age is seventy, but her biological age is closer to fifty.","exampleCN":"她的实际年龄是七十岁，但生理年龄接近五十。","why":"The adjective becomes a way of separating clocks from bodies. It marks the plain calendar count so that another, less visible count can be compared with it.","whyCN":"这个形容词成了一种把日历与身体分开的方式。它标出朴素的日历计数，好让另一种不那么可见的计数与之比较。"},{"no":"09","title":"In the fixed phrase chronological order","titleCN":"用于固定搭配 chronological order","definition":"in the phrase in chronological order, meaning following the actual sequence of events","definitionCN":"用于 in chronological order，表示依照事件的实际先后","example":"Please list the incidents in chronological order.","exampleCN":"请按时间顺序列出这些事件。","why":"The phrase is the most common use of the word. It functions almost as a single instruction: do not group by theme, do not rank by importance, follow the clock.","whyCN":"这个短语是该词最常见的用法。它几乎等于一条单一指令：不要按主题分组，不要按重要性排序，跟着钟表走。"}],"etymology":{"intro":{"en":"Chronological is chronology plus -ical. Chronology was rebuilt in Renaissance Latin from two Greek elements: khronos, 'time', and -logia, 'account or study'. The compound is not classical Greek but a scholarly construction, and chronological came to English through French. Its core meaning has stayed remarkably stable: put events on one line and read them in order.","cn":"chronological 是 chronology 加 -ical。chronology 是文艺复兴拉丁语用两个希腊成分重建的：khronos“时间”与 -logia“论述、学问”。这个复合词不是古典希腊语，而是学术构造；chronological 经法语进入英语。其核心义一直相当稳定：把事件放在一条线上，按顺序读。"},"items":[{"era":"GREEK khronos","en":"Khronos meant 'time' as a span or a period. Its deeper origin is uncertain; linguists have proposed connections with words for cutting or separating, but none is securely established.","cn":"khronos 指作为一段跨度或时期的时间。它的更深来源不确定；语言学家提出过与“切割、分离”类词的关联，但没有一种被可靠确立。"},{"era":"GREEK -logia","en":"Logia, from logos, meant 'speaking, account, reasoned study'. In compounds it named a field of inquiry, as in biology or theology.","cn":"logia 来自 logos，意为“言说、记述、有理据的探讨”。在复合词中它命名一个研究领域，如 biology 或 theology。"},{"era":"RENAISSANCE LATIN chronologia","en":"The compound chronologia was formed by early modern scholars, not attested in classical Greek. It named the study of dates and the arrangement of events in time.","cn":"复合词 chronologia 由近代早期学者构造，不见于古典希腊语。它命名对日期的研究以及把事件按时间排列的工作。"},{"era":"FRENCH chronologique","en":"French added -ique to form the adjective chronologique. English borrowed it as chronological in the 16th to 17th century, a date best given as approximate.","cn":"法语加 -ique 构成形容词 chronologique。英语在 16 至 17 世纪借入为 chronological，这个年代只能大致给出。"},{"era":"17C.-18C. ENGLISH","en":"In English the adjective was used for both the discipline and the arrangement. Historians applied it to annals; scientists later applied it to strata and to measured sequences.","cn":"在英语中，这个形容词既用于学科，也用于排列。历史学家用它指编年史；科学家后来用它指地层与可量度的序列。"},{"era":"MODERN ENGLISH","en":"Modern usage extends to timelines, data logs, age measures and reverse-ordered feeds. The suffix -ical merely marks the adjectival form; the meaning still comes from the two Greek parts.","cn":"现代用法扩展到时间轴、数据日志、年龄度量与倒序信息流。后缀 -ical 只标示形容词形式；意义仍来自两个希腊部分。"}]},"similar":{"note":{"en":"The first group separates chronological from two relatives from the same root and from one close adverb. The second group compares words that also deal with order in time.","cn":"第一组把 chronological 与两个同根亲属及一个形近副词分开。第二组比较同样处理时间顺序的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"chronic","ipa":"/ˈkrɒnɪk/","tag":"same root, different sense","definition":"lasting a long time, said of illness or problems. It shares the Greek root for time but means 'long-drawn-out', not 'in time order'.","definitionCN":"持续很久的，用于疾病或问题。它与“时间”共享希腊词根，但意为“长期的”，不是“按时间排列”。"},{"word":"chronology","ipa":"/krəˈnɒlədʒi/","tag":"base noun","definition":"the study of dates, or an ordered list of events. Chronological is its adjective.","definitionCN":"年代学，或按顺序排列的事件表。chronological 是它的形容词。"},{"word":"chronologically","ipa":"/ˌkrɒnəˈlɒdʒɪkli/","tag":"derived adverb","definition":"in time order. The adverb modifies a verb; the adjective modifies a noun.","definitionCN":"按时间顺序地。副词修饰动词；形容词修饰名词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"sequential","ipa":"/sɪˈkwenʃl/","tag":"one after another","definition":"following in a series. It stresses succession and can apply to steps that have no time element at all.","definitionCN":"依次相随的。它强调接续，也可用于完全没有时间要素的步骤。"},{"word":"temporal","ipa":"/ˈtempərəl/","tag":"of time itself","definition":"relating to time in general, as opposed to space or eternity. It does not by itself imply an order.","definitionCN":"与时间本身有关，相对于空间或永恒。它本身并不含“有序”。"},{"word":"successive","ipa":"/səkˈsesɪv/","tag":"consecutive","definition":"coming one after the other without interruption. It can describe generations or attempts, not only dates.","definitionCN":"接连不断相随的。它可描述世代或尝试，不只描述日期。"},{"word":"historical","ipa":"/hɪˈstɒrɪkl/","tag":"of the past","definition":"relating to past events as studied by history. A historical account may be thematic, while a chronological one must follow dates.","definitionCN":"与历史研究的过去事件有关。历史叙述可以按主题，而编年叙述必须跟着日期。"}]}]},"mnemonics":{"normalIntro":{"en":"These hooks use the two Greek halves of the word and then tie it to the everyday places where the order matters.","cn":"这些记忆钩利用词的两个希腊半部，再把它系到日常需要讲究次序的地方。"},"normal":[{"en":"Split it: chrono (time) plus logical (ordered). Time plus order is the whole word.","cn":"拆开：chrono（时间）加 logical（有逻辑的）。时间加秩序就是整个词。"},{"en":"Picture beads on a string, each bead one event.","cn":"想象一串珠子，每颗珠子是一个事件。"},{"en":"Contrast the pair: chronological order versus reverse chronological order.","cn":"对比这一对：正序时间与倒序时间。"},{"en":"Keep the psychology pair: chronological age against biological age.","cn":"记住心理学那一对：实际年龄与生理年龄。"},{"en":"Watch the trap word chronic: same root, completely different meaning.","cn":"提防陷阱词 chronic：同根，意义完全不同。"}],"abstract":[{"en":"Hold one axis: a single line from left to right. Every sense either puts something on that line or studies the line itself.","cn":"抓住一条轴：从左到右的一条线。每个义项要么把某物放上这条线，要么研究这条线本身。"},{"en":"Sort the senses by what is ordered: events, dates, records, people, stories, rocks, charts, ages, and the fixed phrase.","cn":"按被排序的对象分组：事件、日期、记录、人、故事、岩石、图表、年龄，以及固定短语。"},{"en":"Notice what the word refuses to do: it does not rank importance or explain causes, it only says what came first.","cn":"留意这个词拒绝做的事：它不排重要性，也不解释原因，只说明什么先发生。"}]},"examples":[{"en":"Read the chapters in chronological order to follow the argument.","cn":"按章节的时间顺序阅读，以跟上论证。"},{"en":"Her chronological age is forty, though she looks younger.","cn":"她的实际年龄是四十岁，虽然看起来更年轻。"},{"en":"The archive is organised in reverse chronological order.","cn":"该档案馆按倒序时间排列。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音“克若诺逻辑可”：chrono 是时间，logical 是讲逻辑——按时间的逻辑排下去，就是 chronological，按时间顺序的。","word":"chronological"},"root":"希腊语 khronos“时间”加 -logia“论述、学问”，文艺复兴拉丁语构造为 chronologia；法语加 -ique 成 chronologique，英语借入为 chronological（chronology + -ical）。","sensesIntro":{"en":"Chronological is one of the most obedient adjectives in English: it follows the clock and nothing else. Its nine senses all place something on a single line — letters, negotiations, children, film scenes, rock layers, timelines, ages — or describe the discipline that builds that line. When a text is called chronological, the point is usually that it has refused to reorganise time for effect.","cn":"chronological 是英语中最守规矩的形容词之一：它只跟着钟表，别的都不管。它的九个义项都把某物放上同一条线——信件、谈判、孩子、电影场景、岩层、时间轴、年龄——或者描述建立这条线的学问。当一段文字被称为 chronological，重点通常是它拒绝为了效果而重排时间。"},"semanticMap":{"core":{"en":"One axis only: what came first, what came next.","cn":"只有一条轴：什么先来，什么后到。"},"chain":["TIME","DATE","SEQUENCE","ORDER","LINE","COMPARE"],"branches":[{"senses":"S1 · S9","en":"ORDER: the plain arrangement and its fixed phrase.","cn":"顺序：朴素的排列及其固定短语。"},{"senses":"S2 · S3","en":"RECORD: the discipline of dating and the sequence it produces.","cn":"记录：断代的学问及其产生的序列。"},{"senses":"S4 · S8","en":"PEOPLE: age order, and actual age measured against other ages.","cn":"人：年龄顺序，以及与他种年龄对照的实际年龄。"},{"senses":"S5","en":"STORY: narrative that refuses flashbacks.","cn":"故事：拒绝倒叙的叙述。"},{"senses":"S6 · S7","en":"EARTH AND CHART: strata read upward, time drawn as length.","cn":"大地与图表：自下而上读的地层，被画成长度的时间。"}]},"affixes":{"intro":{"en":"Chronological carries two Greek pieces and one Latin suffix: khronos, -logia and -ical. The items below follow that build, then add the related forms that share the root for time, including two words that drifted far from 'order'.","cn":"chronological 带着两个希腊成分与一个拉丁后缀：khronos、-logia 与 -ical。下面的条目沿这个构造展开，再加上共享“时间”词根的关联形式，其中两个词已经远离“顺序”义。"},"latinIntro":{"en":"The entries are Latinised Greek rather than native Latin: chronologia is a Renaissance coinage, chronicus is the Latin form of Greek khronikos, and chronographia names the writing of time. They are included as the Latin channel through which English received these forms.","cn":"这些条目是拉丁化的希腊词，而非本土拉丁语：chronologia 是文艺复兴造词，chronicus 是希腊 khronikos 的拉丁形式，chronographia 指对时间的记录。列入它们，是因为英语正是通过拉丁渠道接收这些形式。"},"items":[{"word":"chronological","structure":"chronology + -ical (adjective suffix)","meaning":"arranged in order of time","meaningCN":"按时间顺序的","example":"Keep the receipts in chronological order.","exampleCN":"把收据按时间顺序保存。"},{"word":"chronology","structure":"Greek khronos + -logia, via Renaissance Latin","meaning":"the study of dates; an ordered list of events","meaningCN":"年代学；年表","example":"The chronology of the war is still disputed.","exampleCN":"这场战争的年表仍有争议。"},{"word":"chronologically","structure":"chronological + -ly (adverb suffix)","meaning":"in order of time","meaningCN":"按时间顺序地","example":"The events are listed chronologically.","exampleCN":"事件按时间顺序列出。"},{"word":"chronologist","structure":"chronology + -ist (person noun)","meaning":"a scholar who establishes dates","meaningCN":"年代学家","example":"A chronologist dated the inscription to the third century.","exampleCN":"一位年代学家把铭文断为三世纪。"},{"word":"chronic","structure":"Greek khronikos, 'of time', through Latin chronicus","meaning":"long-lasting, of illness or problems","meaningCN":"慢性的；长期的","example":"He suffers from chronic back pain.","exampleCN":"他患有慢性背痛。"},{"word":"anachronism","structure":"ana- (against) + khronos + -ism","meaning":"something placed in the wrong period","meaningCN":"时代错置；不合时宜的事物","example":"A telephone in a medieval scene is an anachronism.","exampleCN":"中世纪场景里出现电话是时代错置。"},{"word":"synchronize","structure":"syn- (together) + khronos + -ize","meaning":"to make things happen at the same time","meaningCN":"使同步","example":"Synchronize the two clocks before the experiment.","exampleCN":"实验前把两个钟对准。"},{"word":"chronological age","structure":"chronological + age (compound noun)","meaning":"actual years lived, as opposed to perceived or biological age","meaningCN":"实际年龄","example":"His chronological age is sixty-five.","exampleCN":"他的实际年龄是六十五岁。"},{"word":"reverse chronological order","structure":"reverse + chronological + order (compound phrase)","meaning":"newest first, oldest last","meaningCN":"倒序时间排列","example":"Blog posts appear in reverse chronological order.","exampleCN":"博客文章按倒序时间显示。"},{"word":"chronological order","structure":"chronological + order (compound phrase)","meaning":"the sequence in which events actually happened","meaningCN":"时间顺序","example":"The timeline presents the reigns in chronological order.","exampleCN":"时间轴按时间顺序呈现各朝统治。"}],"latinEntries":[{"word":"chronologia","structure":"Renaissance Latin, from Greek khronos + -logia","meaning":"the study and ordering of dates","meaningCN":"年代学；日期编排"},{"word":"chronicus","structure":"Latin adjective from Greek khronikos","meaning":"of time; long-lasting","meaningCN":"时间的；长期的"},{"word":"chronographia","structure":"Greek khronos + graphein, Latinised","meaning":"the recording or writing of time","meaningCN":"时间记录；年代记述"}]}},{"word":"chronology","ipa_uk":"/krəˈnɒlədʒi/","ipa_us":"/krəˈnɑːlədʒi/","definition_zh":"年表；年代学；时间顺序；大事记","definition_en":"the study of dates and time order, or an ordered list of events arranged by when they happened","core_image":"一串日期标签钉在一条长线上，最早的在左端，最近的在右端","scene":"侦探在白板上画出一条横线，把案发、报警、到场、离开的时刻依次写上去。The detective draws a line on the board and writes the times of the crime, the call, the arrival and the departure: that line is the chronology of the case.","sceneCN":"这里 chronology 是「时间线、事件年表」（第 1、7 个义项：有序事件清单与案件时间线）；句意：侦探把案发、报警、到场、离开的时刻依次写在一条横线上，这条线就是案件的时间线。图中可辨识物件：白板、横线、时间标签、马克笔。","pos":[{"tag":"n.","zh":"年表；年代学；时间顺序"}],"collocations":[{"phrase":"chronology of events","zh":"事件时间表"},{"phrase":"establish a chronology","zh":"确定时间顺序"},{"phrase":"geological chronology","zh":"地质年代学"},{"phrase":"relative chronology","zh":"相对年代"},{"phrase":"absolute chronology","zh":"绝对年代"},{"phrase":"chronology of the case","zh":"案件时间线"}],"forms":[{"label":"单数","form":"chronology"},{"label":"复数（指多份年表或多种年代体系）","form":"chronologies"},{"label":"形容词形式","form":"chronological"}],"derivatives":[{"word":"chronological","pos":"adj.","zh":"按时间顺序的；年代学的"},{"word":"chronologically","pos":"adv.","zh":"按时间顺序地"},{"word":"chronologist","pos":"n.","zh":"年代学家"},{"word":"geochronology","pos":"n.","zh":"地质年代学"}],"senses":[{"no":"01","title":"An ordered list of events","titleCN":"按顺序排列的事件清单","definition":"a list that sets events out in the order in which they occurred","definitionCN":"按事件发生的先后顺序列出事件的清单","example":"The report opens with a chronology of the negotiations.","exampleCN":"报告开头是一份谈判事件的时间表。","why":"This is the most concrete sense: a list you could print. The noun names the product, not the method behind it.","whyCN":"这是最具体的义项：一份可以打印出来的清单。这个名词命名的是产物，而不是背后的方法。"},{"no":"02","title":"The discipline of dating","titleCN":"断代与年代学","definition":"the scholarly study of dates and how they are established","definitionCN":"对日期以及日期如何被确定的学术研究","example":"He teaches chronology at the institute of history.","exampleCN":"他在历史研究所教授年代学。","why":"The -logy in the word promises a field, not a list. This sense treats chronology as a method with rules for testing dates.","whyCN":"词中的 -logy 许诺的是一个领域，而不是一份清单。这一义把 chronology 当作一门有检验日期规则的方法。"},{"no":"03","title":"The order itself","titleCN":"先后顺序本身","definition":"the actual temporal relation between events, independent of any list","definitionCN":"事件之间真实的时间关系，不依赖任何清单","example":"The chronology of the two outbreaks is still unclear.","exampleCN":"两次爆发的先后仍不清楚。","why":"Here the word means the relation in the world, not a record of it. Disputes over chronology are disputes about what really came first.","whyCN":"这里这个词指世界中的关系，而不是对它的记录。关于年代顺序的争论，就是关于究竟什么先发生的争论。"},{"no":"04","title":"A historical account ordered by time","titleCN":"按时间编排的历史记述","definition":"a historical narrative or table that proceeds year by year","definitionCN":"逐年推进的历史叙述或表格","example":"Medieval chronicles often mix chronology with legend.","exampleCN":"中世纪编年史常把年代记述与传说混在一起。","why":"Older history was written as chronology: one year after another, with little analysis. The word still carries that plain, cumulative style.","whyCN":"较早的历史写作就是年表式的：一年接一年，分析很少。这个词至今带着那种朴素、累积的文体。"},{"no":"05","title":"Geological chronology","titleCN":"地质年代学","definition":"the ordering of earth history, by rock layers or by radiometric dating","definitionCN":"通过岩层或放射性测年排列地球历史","example":"Geological chronology places the extinction at the end of the Cretaceous.","exampleCN":"地质年代学把那场灭绝定位在白垩纪末。","why":"Earth history has no written dates, so chronology had to be rebuilt from layers and isotopes. The word moves from texts to stones.","whyCN":"地球历史没有写下的日期，年代顺序必须从岩层与同位素重建。这个词从文本移到了石头。"},{"no":"06","title":"A biography's timeline","titleCN":"个人生平年谱","definition":"a dated outline of a person's life and main works","definitionCN":"一个人生平与主要作品的带日期纲要","example":"The biography ends with a chronology of the poet's life.","exampleCN":"传记末尾附有诗人一生的年谱。","why":"A single life is small enough to be put on one line. Publishers use chronology as an appendix, because readers want dates without narrative.","whyCN":"一个人的一生小到可以放在一条线上。出版社把年谱作为附录，因为读者想要日期，而不想要叙述。"},{"no":"07","title":"A case or investigation timeline","titleCN":"案件或调查时间线","definition":"the reconstructed sequence of events in an investigation or dispute","definitionCN":"在调查或争议中被重建的事件顺序","example":"Police built a minute-by-minute chronology of the night.","exampleCN":"警方建立了那一夜逐分钟的时间线。","why":"In legal and investigative settings chronology is a tool of proof. Gaps in the line become the questions that have to be answered.","whyCN":"在法律与调查场景中，年表是证明的工具。线上的空白就成了必须回答的问题。"},{"no":"08","title":"Narrative order","titleCN":"叙事时序","definition":"the order in which a story presents events, which may differ from their actual order","definitionCN":"故事呈现事件的顺序，它可以与实际发生的顺序不同","example":"The novel's chronology is broken by long flashbacks.","exampleCN":"这部长篇的时间顺序被长段倒叙打断。","why":"Literary criticism uses chronology for the story's own clock. The word can therefore describe a deliberate distortion of time, not only a faithful record.","whyCN":"文学批评用 chronology 指故事自身的时钟。因此这个词也能描述对时间的有意扭曲，而不只是忠实记录。"},{"no":"09","title":"Cosmic or evolutionary chronology","titleCN":"宇宙或演化的年表","definition":"the very long sequence of natural history, from the universe's origin to the present","definitionCN":"从宇宙起源至今的极长的自然史序列","example":"Cosmic chronology compresses thirteen billion years into one chart.","exampleCN":"宇宙年表把一百三十亿年压缩进一张图表。","why":"The word scales up without changing shape. Whether the units are minutes or millions of years, chronology still means one line with events placed on it.","whyCN":"这个词可以无限放大而不变形。无论单位是分钟还是百万年，chronology 仍指一条线以及线上的事件。"}],"etymology":{"intro":{"en":"Chronology was coined in Renaissance Latin from Greek parts: khronos, 'time', and -logia, 'account, study'. It is not an ancient Greek word. English took it from French in the 16th century, and only later derived the adjective chronological from it. The noun therefore came first, and it named both a science and the tables that science produced.","cn":"chronology 是文艺复兴拉丁语用希腊成分造的：khronos“时间”与 -logia“记述、学问”。它不是古希腊语词。英语在 16 世纪从法语接过来，之后才由它派生出形容词 chronological。所以名词先出现，并且同时命名一门学问和这门学问产出的表格。"},"items":[{"era":"GREEK khronos","en":"Khronos meant 'time' as duration or period. Its own etymology is uncertain; suggested links with roots meaning 'cut' are not accepted as proven.","cn":"khronos 指作为时长或时期的时间。它自身的词源不确定；与“切割”类词根的关联只是提议，并未被证明。"},{"era":"GREEK -logia","en":"From logos, 'word, account, reason', -logia named a branch of study. It promised a reasoned body of knowledge rather than a mere list.","cn":"来自 logos“言词、记述、理据”，-logia 命名一门研究分支。它许诺的是有理由的知识体系，而不只是一份清单。"},{"era":"RENAISSANCE LATIN chronologia","en":"The compound was assembled by late 16th-century scholars, and it is associated with the period's work on correcting historical dates. It was a technical coinage, not an inherited word.","cn":"这个复合词由 16 世纪晚期学者组装而成，与该时代校正历史日期的工作相关。它是技术造词，不是继承来的词。"},{"era":"FRENCH chronologie","en":"French adopted the Latin form as chronologie. English borrowed it in the 16th century. The early English word covered both the science and the tabulated result.","cn":"法语把拉丁形式接为 chronologie。英语在 16 世纪借入。早期英语中，这个词同时涵盖学问与制表结果。"},{"era":"17C.-18C. ENGLISH","en":"The two branches separated: chronology as a discipline with rules, and chronology as an appendix of dates in a book. Historians and geologists pushed the second branch into new material.","cn":"两个分支分开：作为有规则之学问的 chronology，以及作为书中日期附录的 chronology。历史学家与地质学家把后一支推进到新材料上。"},{"era":"MODERN ENGLISH","en":"Modern use adds geological, cosmic and investigative chronologies, and the plural chronologies for rival dating systems. The word still names both a line of events and the study of how that line is drawn.","cn":"现代用法增加了地质、宇宙与调查年表，以及指相互竞争的断代体系的复数 chronologies。这个词仍同时命名一条事件线，以及研究这条线如何被画出的学问。"}]},"similar":{"note":{"en":"The first group separates chronology from two derived relatives and one look-alike word from the same root. The second group compares other ways of recording ordered time.","cn":"第一组把 chronology 与两个派生亲属及一个同根形近词分开。第二组比较记录有序时间的其它方式。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"chronological","ipa":"/ˌkrɒnəˈlɒdʒɪkl/","tag":"derived adjective","definition":"arranged in time order. The adjective describes the arrangement; chronology names it.","definitionCN":"按时间顺序排列的。形容词描述排列；chronology 命名排列。"},{"word":"chronologist","ipa":"/krəˈnɒlədʒɪst/","tag":"person noun","definition":"a person who studies or establishes dates. The -ist marks the practitioner.","definitionCN":"研究或确定日期的人。后缀 -ist 标示从业者。"},{"word":"chronicle","ipa":"/ˈkrɒnɪkl/","tag":"look-alike relative","definition":"a written record of events year by year. It comes from the same Greek root but is a different formation and usually names a text.","definitionCN":"逐年记录事件的文字。它同出希腊词根，但构词不同，通常指一部文本。"}]},{"heading":"NEAR MEANING","entries":[{"word":"timeline","ipa":"/ˈtaɪmlaɪn/","tag":"visual ordering","definition":"a graphical line showing when events happened. It is the everyday word for what chronology often means in practice.","definitionCN":"显示事件发生时间的图形线。它是 chronology 在实际使用中常指之物的日常说法。"},{"word":"chronicle","ipa":"/ˈkrɒnɪkl/","tag":"historical text","definition":"a narrative record arranged year by year. A chronicle is a document; a chronology can be a bare list or a science.","definitionCN":"逐年编排的叙述记录。chronicle 是一份文献；chronology 可以是纯清单，也可以是一门学问。"},{"word":"annals","ipa":"/ˈænlz/","tag":"yearly records","definition":"historical records kept year by year, often official. It is narrower and more institutional than chronology.","definitionCN":"逐年保存的历史记录，常为官方所修。它比 chronology 更窄、更制度化。"},{"word":"sequence","ipa":"/ˈsiːkwəns/","tag":"general order","definition":"a set of things in a fixed order. It need not involve dates and is the broadest term of the group.","definitionCN":"按固定次序排列的一组事物。它不必涉及日期，是这组词中最宽的。"}]}]},"mnemonics":{"normalIntro":{"en":"These hooks build the word from its Greek halves and then attach it to the places where people actually draw a line of dates.","cn":"这些记忆钩用两个希腊半部搭起这个词，再把它系到人们真正画出日期线的地方。"},"normal":[{"en":"Split it: chrono (time) plus logy (study or account). The study of time order, or the account itself.","cn":"拆开：chrono（时间）加 logy（学问或记述）。对时间顺序的研究，或那份记述本身。"},{"en":"Picture the police whiteboard: one horizontal line, dates pinned along it.","cn":"想象警方的白板：一条横线，日期钉在上面。"},{"en":"Keep the pair relative and absolute chronology: order without numbers, then order with them.","cn":"记住相对年代与绝对年代这一对：先是不带数字的顺序，再是带数字的顺序。"},{"en":"See the appendix: biographies end with a bare list of dates.","cn":"看附录：传记末尾是一串纯日期。"},{"en":"Watch out for chronicle: it looks like chronology but names a book.","cn":"当心 chronicle：它看起来像 chronology，但指的是一本书。"}],"abstract":[{"en":"Hold one line: everything the word does is either drawn on that line or is the craft of drawing it.","cn":"抓住一条线：这个词所做的一切，要么是画在这条线上，要么是画这条线的手艺。"},{"en":"Sort the senses by scale: a list, a science, a relation, a history, the earth, a life, a case, a story, the universe.","cn":"按尺度分组：清单、学问、关系、历史、地球、一生、案件、故事、宇宙。"},{"en":"Notice the honesty of the word: a chronology records order and refuses to explain why.","cn":"留意这个词的诚实：年表只记录先后，拒绝解释原因。"}]},"examples":[{"en":"The court asked for a detailed chronology of the payments.","cn":"法庭要求提供付款的详细时间线。"},{"en":"Radiocarbon dating transformed the chronology of early settlements.","cn":"放射性碳测年改变了早期定居点的年代序列。"},{"en":"The book includes a chronology of the author's travels.","cn":"书中附有作者游历的年表。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音“克若诺逻辑”：chrono 是时间，logy 是学问——研究时间先后的学问，就是 chronology，年表与年代学。","word":"chronology"},"root":"希腊语 khronos“时间”加 -logia“记述、学问”，16 世纪文艺复兴拉丁语构造为 chronologia；经法语 chronologie 进入英语为 chronology。","sensesIntro":{"en":"Chronology names both the line and the craft of drawing it. Concretely it is a dated list; academically it is the science of establishing dates; abstractly it is the real order of events. It scales from a single night's police timeline to the thirteen-billion-year cosmic one, and at every scale it does the same thing: place events on one axis and let the gaps show.","cn":"chronology 既命名那条线，也命名画线的手艺。具体地说，它是一份带日期的清单；学术地说，它是确定日期的学问；抽象地说，它是事件真实的先后。它可以从一夜的警方时间线扩展到一百三十亿年的宇宙年表，而在每个尺度上它做的都是同一件事：把事件放上一条轴，让空白自己显现。"},"semanticMap":{"core":{"en":"One line of dates, and the craft of deciding where each mark belongs.","cn":"一条日期线，以及决定每个标记该放哪里的手艺。"},"chain":["TIME","DATE","LIST","RELATION","SCALE","STUDY"],"branches":[{"senses":"S1 · S4","en":"RECORD: the printed list and the older year-by-year history.","cn":"记录：印出的清单与较早的逐年史书。"},{"senses":"S2 · S3","en":"METHOD AND FACT: the discipline, and the order it tries to recover.","cn":"方法与事实：学问本身，以及它试图复原的先后。"},{"senses":"S5 · S9","en":"DEEP TIME: earth history and cosmic history.","cn":"深时：地球史与宇宙史。"},{"senses":"S6 · S7","en":"SMALL SCALE: one life, one case.","cn":"小尺度：一个人的一生，一个案件。"},{"senses":"S8","en":"STORY: the order a narrative chooses to use.","cn":"故事：叙述选择使用的顺序。"}]},"affixes":{"intro":{"en":"Chronology has two Greek parts and no Latin suffix of its own. The items below follow that build, then add the compound fields that place the word in geology and archaeology, plus the related words for same-time and wrong-time.","cn":"chronology 有两个希腊成分，自身不带拉丁后缀。下面的条目沿这个构造展开，再加上把它放进地质学与考古学的复合领域词，以及与“同时”“错时”相关的词。"},"latinIntro":{"en":"These are Latinised Greek forms, not native Latin. Chronologia is the Renaissance coinage, chronica is the Latin name for a year-by-year record, and chronicus is the Latin adjective from Greek khronikos. They are the channel through which English received the family.","cn":"这些是拉丁化的希腊形式，而非本土拉丁语。chronologia 是文艺复兴造词，chronica 是逐年记录的拉丁名称，chronicus 是希腊 khronikos 的拉丁形容词。英语正是通过这个渠道接收这一词族。"},"items":[{"word":"chronology","structure":"Greek khronos + -logia, through Renaissance Latin","meaning":"the study of dates; an ordered list of events","meaningCN":"年代学；年表","example":"The chronology of the revolt is well documented.","exampleCN":"这场起义的经过有详细记载。"},{"word":"chronological","structure":"chronology + -ical","meaning":"arranged in time order","meaningCN":"按时间顺序的","example":"Arrange the photographs in chronological order.","exampleCN":"把照片按时间顺序排列。"},{"word":"chronologically","structure":"chronological + -ly","meaning":"in order of time","meaningCN":"按时间顺序地","example":"The diary entries are printed chronologically.","exampleCN":"日记条目按时间顺序印出。"},{"word":"chronologist","structure":"chronology + -ist","meaning":"one who studies or fixes dates","meaningCN":"年代学家","example":"The chronologist disputed the accepted date.","exampleCN":"这位年代学家质疑了公认的日期。"},{"word":"geochronology","structure":"geo- (earth) + chronology","meaning":"the dating of rocks and earth history","meaningCN":"地质年代学","example":"Geochronology relies on radioactive decay.","exampleCN":"地质年代学依靠放射性衰变。"},{"word":"dendrochronology","structure":"dendro- (tree) + chronology","meaning":"dating by tree rings","meaningCN":"树木年代学","example":"Dendrochronology dated the beam to the fifteenth century.","exampleCN":"树木年代学把这根梁断为十五世纪。"},{"word":"anachronism","structure":"ana- (against) + khronos + -ism","meaning":"a thing out of its proper time","meaningCN":"时代错置","example":"The clock in the painting is an anachronism.","exampleCN":"画中的时钟是时代错置。"},{"word":"synchronous","structure":"syn- (together) + khronos + -ous","meaning":"happening at the same time","meaningCN":"同时发生的","example":"The two revolutions were not synchronous.","exampleCN":"这两场革命并非同时发生。"},{"word":"relative chronology","structure":"relative + chronology (archaeology term)","meaning":"ordering by before and after, without calendar dates","meaningCN":"相对年代","example":"Relative chronology places the later tomb above the earlier one.","exampleCN":"相对年代把较晚的墓排在较早的墓之上。"},{"word":"absolute chronology","structure":"absolute + chronology (archaeology term)","meaning":"ordering with numerical dates","meaningCN":"绝对年代","example":"Absolute chronology depends on radiocarbon results.","exampleCN":"绝对年代依赖碳十四结果。"}],"latinEntries":[{"word":"chronologia","structure":"Renaissance Latin, Greek khronos + -logia","meaning":"the study and ordering of dates","meaningCN":"年代学；日期编排"},{"word":"chronica","structure":"Latin neuter plural of Greek khronika","meaning":"a year-by-year record of events","meaningCN":"编年史；逐年记录"},{"word":"chronicus","structure":"Latin adjective from Greek khronikos","meaning":"of time; long-lasting","meaningCN":"时间的；长期的"}]}},{"word":"circulation","ipa_uk":"/ˌsɜːkjəˈleɪʃn/","ipa_us":"/ˌsɜːrkjəˈleɪʃn/","definition_zh":"循环；流通；发行量；传播","definition_en":"the movement of something around a closed path or through a group of people, or the number of copies of a publication that are sold","core_image":"一条首尾相接的环，箭头沿环不断前进，没有起点也没有终点","scene":"清晨的图书馆还书台，一本被借出的书被推回书车。At the returns desk in the early morning, a borrowed book is pushed back onto the trolley and returns to circulation.","sceneCN":"这里 circulation 是「（图书）流通、借阅流转」（第 6 个义项：馆藏流通）；句意：清晨的还书台，一本被借出的书回到书车，重新进入流通。图中可辨识物件：还书箱、书车、借阅条码、馆员。","pos":[{"tag":"n.","zh":"循环；流通；发行量；传播"}],"collocations":[{"phrase":"blood circulation","zh":"血液循环"},{"phrase":"in circulation","zh":"在流通中；在市面上"},{"phrase":"circulation of money","zh":"货币流通"},{"phrase":"newspaper circulation","zh":"报纸发行量"},{"phrase":"circulation desk","zh":"借还书处"},{"phrase":"air circulation","zh":"空气流通"}],"forms":[{"label":"单数","form":"circulation"},{"label":"复数（指多种流通量或多次循环）","form":"circulations"},{"label":"动词形式","form":"circulate"}],"derivatives":[{"word":"circulate","pos":"v.","zh":"循环；流通；传播"},{"word":"circulatory","pos":"adj.","zh":"循环的（尤指血液循环）"},{"word":"circular","pos":"adj.","zh":"圆形的；循环论证的"},{"word":"circle","pos":"n.","zh":"圆；圈子"}],"senses":[{"no":"01","title":"Blood circulation","titleCN":"血液循环","definition":"the continuous movement of blood through the heart and vessels","definitionCN":"血液经心脏与血管的持续流动","example":"Cold hands are a sign of poor circulation.","exampleCN":"手冷是循环不畅的一个迹象。","why":"This is the sense that made the word famous: Harvey's demonstration that blood travels in a closed loop rather than ebbing and flowing. The ring is literal.","whyCN":"这是让这个词出名的义项：哈维证明血液在一个闭合环路中运行，而不是涨落往复。这里的环是字面的。"},{"no":"02","title":"Air or water circulation","titleCN":"空气或水的环流","definition":"the movement of air or water through a space or system","definitionCN":"空气或水通过某一空间或系统的流动","example":"The greenhouse needs good air circulation.","exampleCN":"温室需要良好的空气流通。","why":"The same geometry applies to fluids: what enters must leave, and stagnation is the failure of the loop.","whyCN":"同一几何适用于流体：进来的必须出去，停滞就是环路的失效。"},{"no":"03","title":"Money in circulation","titleCN":"货币流通","definition":"the movement of currency and credit through an economy","definitionCN":"货币与信用在经济体中流动","example":"The central bank controls the amount of money in circulation.","exampleCN":"央行控制流通中的货币量。","why":"Economics borrowed the word because money behaves like blood: it does work only while moving, and hoarding is a kind of clot.","whyCN":"经济学借用这个词，是因为货币像血液：只有流动时才起作用，囤积则是一种堵塞。"},{"no":"04","title":"Publication circulation","titleCN":"报刊发行量","definition":"the number of copies of a newspaper or magazine distributed or sold","definitionCN":"报纸或杂志发行或售出的份数","example":"The magazine's circulation fell by half in five years.","exampleCN":"这本杂志的发行量五年内下降了一半。","why":"Here the loop is replaced by a count: each copy passes from publisher to reader. The word shifts from motion to a figure advertisers can price.","whyCN":"这里的环被一个数字替代：每一份从出版者传到读者。这个词从运动转向一个广告商可以定价的数字。"},{"no":"05","title":"Circulation of information","titleCN":"信息传播","definition":"the spreading of news, rumours or ideas among people","definitionCN":"新闻、谣言或观念在人群中扩散","example":"The rumour circulated for weeks before it was denied.","exampleCN":"这个谣言流传了数周才被否认。","why":"Information circulates through people the way blood circulates through vessels. The metaphor makes the word available for gossip as well as journalism.","whyCN":"信息通过人群传播，如同血液通过血管循环。这个比喻让这个词既可用于闲话，也可用于新闻业。"},{"no":"06","title":"Library circulation","titleCN":"图书馆流通","definition":"the lending and returning of books and other items","definitionCN":"图书及其它资料的借出与归还","example":"Rare books are excluded from circulation.","exampleCN":"珍本不参与外借流通。","why":"In a library the loop is physical: an item leaves the shelf, returns, and leaves again. The word measures how often that happens.","whyCN":"在图书馆里，环是物理的：一本书离开书架、回来、再离开。这个词衡量这件事发生的频率。"},{"no":"07","title":"In the phrase in circulation","titleCN":"用于 in circulation","definition":"in the phrase in circulation, meaning in use, available, or present among people","definitionCN":"用于 in circulation，表示在使用中、可获得的，或存在于人群之中","example":"There are many fake notes in circulation.","exampleCN":"市面上流通着许多假钞。","why":"The phrase marks something as currently moving through the system. To withdraw it from circulation is to stop its movement without destroying it.","whyCN":"这个短语标示某物正在系统中流动。把它撤出流通，就是停止它的移动而不销毁它。"},{"no":"08","title":"Money supply as a quantity","titleCN":"作为数量的货币供应","definition":"in economics, the total value of money held and used outside banks","definitionCN":"在经济学中，银行体系之外持有并使用的货币总值","example":"Currency in circulation rose sharply during the panic.","exampleCN":"恐慌期间流通货币量急剧上升。","why":"The abstract motion becomes a stock that can be measured at a moment. The word now names a quantity, not an activity.","whyCN":"抽象的运动变成一个可在某一时刻量度的存量。这个词现在命名一个数量，而不是一种活动。"},{"no":"09","title":"Turnover of goods or resources","titleCN":"商品或资源的周转","definition":"the rate at which stock is used up and replaced in a business","definitionCN":"商业中存货被消耗并补回的速率","example":"Fast circulation of stock keeps the shop profitable.","exampleCN":"存货快速周转使店铺保持盈利。","why":"Retail uses the word for the loop of buying, selling and restocking. The faster the loop, the less capital sits still.","whyCN":"零售业用这个词指买进、卖出、补货的环。环转得越快，闲置的资本就越少。"}],"etymology":{"intro":{"en":"Circulation comes from Latin circulatio, a noun of action from circulare, 'to move in a circle'. The base is circulus, a diminutive of circus, 'ring'. The word therefore begins with a small ring, not with blood or money; those applications came later and made the metaphor concrete.","cn":"circulation 来自拉丁 circulatio，是由 circulare“绕圈运动”构成的动作名词。基础是 circulus，即 circus“环”的指小形式。所以这个词从一个小环开始，而不是从血液或金钱开始；后两者是后来的应用，把比喻落到实处。"},"items":[{"era":"LATIN circus","en":"Circus meant a ring or circle, and by extension the oval track where chariot races were held. English circus, the performance tent, descends from the same word.","cn":"circus 指环或圆圈，进而指举行战车赛的椭圆形赛道。英语的 circus（马戏）同出此词。"},{"era":"LATIN circulus","en":"Circulus was the diminutive: a little ring, a small circle. It could name a group of people standing round, a hoop, or a geometric figure.","cn":"circulus 是指小形式：小环、小圆圈。它可以指围站的一群人、一个箍，或一个几何图形。"},{"era":"LATIN circulare","en":"Circulare meant 'to make circular, to move round'. It described both shaping something into a ring and travelling around one.","cn":"circulare 意为“使成圆、绕行”。它既描述把某物做成环，也描述沿环行进。"},{"era":"LATE LATIN circulatio","en":"Circulatio, the action noun, named a going round. It was available for technical use long before physiology adopted it.","cn":"动作名词 circulatio 指绕行一圈。在生理学采用它之前很久，它就已经可供技术使用。"},{"era":"15C.-17C. ENGLISH","en":"English took circulation in the 15th century with the general sense of circular movement. Harvey's account of the blood in 1628 gave the word its most famous application.","cn":"英语在 15 世纪接来 circulation，带一般性的“环行运动”义。1628 年哈维对血液的论述，给了这个词最著名的应用。"},{"era":"MODERN ENGLISH","en":"From the 18th century the word spread to money, newspapers and information. Each new field kept the shape: something moves through a loop and returns, or passes through many hands.","cn":"从 18 世纪起，这个词扩展到货币、报刊与信息。每个新领域都保留同一形状：某物沿环运行并返回，或在许多手中传递。"}]},"similar":{"note":{"en":"The first group separates circulation from three words built on the same ring-root. The second group compares the kinds of movement the word can describe.","cn":"第一组把 circulation 与三个同出“环”词根的词分开。第二组比较这个词所能描述的运动类型。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"circulate","ipa":"/ˈsɜːkjəleɪt/","tag":"the verb","definition":"to move round or spread through a group. Circulation is the noun of that action.","definitionCN":"绕行或在群体中传布。circulation 是这一动作的名词。"},{"word":"circulatory","ipa":"/ˈsɜːkjələtəri/","tag":"the adjective","definition":"relating to circulation, especially the blood system. It describes the system, not the movement.","definitionCN":"与循环有关的，尤指血液系统。它描述系统，不描述运动。"},{"word":"circular","ipa":"/ˈsɜːkjələ/","tag":"shape word","definition":"shaped like a circle, or of an argument that assumes what it proves. It names a form, not a process.","definitionCN":"圆形的，或指预设结论的论证。它命名形状，不命名过程。"}]},{"heading":"NEAR MEANING","entries":[{"word":"flow","ipa":"/fləʊ/","tag":"movement","definition":"steady movement of a liquid, gas or quantity. It does not require a closed loop.","definitionCN":"液体、气体或数量的稳定移动。它不要求闭合环路。"},{"word":"rotation","ipa":"/rəʊˈteɪʃn/","tag":"turning","definition":"turning around an axis. It is geometric and regular, while circulation can be social or economic.","definitionCN":"绕轴转动。它是几何性的、规则的，而 circulation 可以是社会的或经济的。"},{"word":"distribution","ipa":"/ˌdɪstrɪˈbjuːʃn/","tag":"allocation","definition":"the spreading of goods to places or people. It is one-way delivery, not a return loop.","definitionCN":"把货物分送到各地或各人。它是单向配送，不是回环。"},{"word":"dissemination","ipa":"/dɪˌsemɪˈneɪʃn/","tag":"spreading","definition":"the wide spreading of information or ideas. It stresses reach rather than return.","definitionCN":"信息或观念的广泛散布。它强调覆盖范围，而不是返回。"}]}]},"mnemonics":{"normalIntro":{"en":"These hooks start from the small ring inside the word and then follow it into blood, money, print, gossip and shelves.","cn":"这些记忆钩从词里那个小环出发，再跟着它进入血液、金钱、印刷品、闲话与书架。"},"normal":[{"en":"See the ring: circus, circulus, circulate, circulation. Each step keeps the circle.","cn":"看见那个环：circus、circulus、circulate、circulation。每一步都保留圆圈。"},{"en":"Link it to blood first: the word became famous through Harvey's loop.","cn":"先连到血液：这个词因哈维的环路而出名。"},{"en":"Link it to money: only moving money does work.","cn":"连到金钱：只有流动的钱才起作用。"},{"en":"Link it to a magazine: circulation is the count advertisers buy.","cn":"连到杂志：发行量是广告商购买的那个数字。"},{"en":"Keep the phrase in circulation for anything currently in use.","cn":"记住 in circulation，用于任何正在使用中的东西。"}],"abstract":[{"en":"Hold one shape: a closed loop. Every sense is something travelling that loop, or a measure of how fast it travels.","cn":"抓住一个形状：闭合的环。每个义项都是某物沿环运行，或衡量它运行得多快。"},{"en":"Sort the senses by what moves: blood, air, money, copies, news, books, use, supply, stock.","cn":"按移动之物分组：血液、空气、货币、份数、消息、图书、使用、供应、存货。"},{"en":"Notice the two measurements: a rate of movement, and a count of copies or currency.","cn":"留意两种量度：运动的速率，以及份数或货币的计数。"}]},"examples":[{"en":"Exercise improves circulation and lowers blood pressure.","cn":"运动改善循环并降低血压。"},{"en":"Several counterfeit notes are still in circulation.","cn":"仍有若干假钞在市面上流通。"},{"en":"The paper's circulation has fallen every year since 2010.","cn":"该报发行量自 2010 年以来逐年下降。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音“色Q来神”：想象一条 circle（圆环）不停地转，转一圈又一圈——这就是 circulation，循环流通。","word":"circulation"},"root":"拉丁语 circus“环、圆圈”的指小形式 circulus“小环”，动词 circulare“绕行”，动作名词 circulatio；经法语进入英语为 circulation。","sensesIntro":{"en":"Circulation is a shape before it is a subject. The shape is a loop, and the word asks what travels around it: blood through the body, air through a room, money through an economy, copies through readers, news through a crowd, books through a library. Two of its senses step outside the loop and simply count how much is moving, which is how a metaphor becomes a statistic.","cn":"circulation 先是一个形状，然后才是一个主题。形状是环，而这个词追问的是什么在沿环绕行：血液过身体、空气过房间、货币过经济、份数过读者、消息过人群、图书过图书馆。其中两个义项走出环外，只数有多少在流动——比喻就是这样变成一个统计数字的。"},"semanticMap":{"core":{"en":"Something travels a closed loop and comes back, doing its work only while in motion.","cn":"某物沿闭合环运行并返回，只在运动中才起作用。"},"chain":["RING","MOVE","RETURN","SPREAD","COUNT","SUPPLY"],"branches":[{"senses":"S1 · S2","en":"BODY AND AIR: the physical loops inside organisms and rooms.","cn":"身体与空气：生物体内与房间里的物理环。"},{"senses":"S3 · S8","en":"MONEY: the motion of currency, and the stock it forms.","cn":"货币：通货的运动，以及它形成的存量。"},{"senses":"S4 · S9","en":"COMMERCE: copies sold and stock turned over.","cn":"商业：售出的份数与周转的存货。"},{"senses":"S5","en":"INFORMATION: news and rumour passing through people.","cn":"信息：新闻与谣言在人群中传递。"},{"senses":"S6 · S7","en":"USE: library lending, and the phrase for anything currently available.","cn":"使用：图书馆借阅，以及表示“正在使用中”的短语。"}]},"affixes":{"intro":{"en":"Circulation is circulate plus -ion, and circulate goes back to the ring-root circus. The items below follow that chain, then add the re- form and three compounds that carry the word into libraries, plumbing and medicine.","cn":"circulation 是 circulate 加 -ion，circulate 又上溯到“环”词根 circus。下面的条目沿这条链展开，再加上 re- 形式，以及三个把这个词带入图书馆、管道与医学的复合词。"},"latinIntro":{"en":"The Latin entries give the ring, its diminutive, and the action noun. The diminutive is the crucial step: circulus narrows a public circus to a small closed curve, which is what the modern word still pictures.","cn":"拉丁语条目给出“环”、其指小形式，以及动作名词。指小这一步最关键：circulus 把公共的 circus 缩小为一条闭合曲线，现代这个词描绘的仍是这个。"},"items":[{"word":"circulation","structure":"circulate + -ion (action noun)","meaning":"movement around a loop; the number of copies distributed","meaningCN":"循环；流通；发行量","example":"Poor circulation causes cold feet.","exampleCN":"循环不畅会导致脚冷。"},{"word":"circulate","structure":"Latin circulare, from circulus","meaning":"to move round; to spread among people","meaningCN":"循环；流通；传播","example":"The draft circulated among the members.","exampleCN":"草案在成员之间传阅。"},{"word":"circulatory","structure":"circulate + -ory (adjective suffix)","meaning":"relating to the blood system","meaningCN":"循环的","example":"The circulatory system includes the heart and vessels.","exampleCN":"循环系统包括心脏与血管。"},{"word":"circulator","structure":"circulate + -or (agent noun)","meaning":"a person or device that circulates something","meaningCN":"循环器；传播者","example":"The pump is a water circulator.","exampleCN":"这台泵是水循环器。"},{"word":"circular","structure":"Latin circularis, from circulus","meaning":"round; also, of an argument that assumes its conclusion","meaningCN":"圆形的；循环论证的","example":"They sat at a circular table.","exampleCN":"他们围坐一张圆桌。"},{"word":"circle","structure":"Latin circulus, through Old French","meaning":"a round shape; a group of people with a shared interest","meaningCN":"圆；圈子","example":"Draw a circle around the answer.","exampleCN":"在答案周围画一个圈。"},{"word":"recirculation","structure":"re- (again) + circulation","meaning":"the act of sending something round again","meaningCN":"再循环","example":"The building uses recirculation to save heat.","exampleCN":"这栋建筑用再循环来保温。"},{"word":"circulation desk","structure":"circulation + desk (compound noun)","meaning":"the library counter where items are borrowed and returned","meaningCN":"借还书处","example":"Ask at the circulation desk for a new card.","exampleCN":"到借还书处办理新借书证。"},{"word":"circulation pump","structure":"circulation + pump (compound noun)","meaning":"a pump that keeps fluid moving round a system","meaningCN":"循环泵","example":"The boiler's circulation pump failed.","exampleCN":"锅炉的循环泵坏了。"},{"word":"blood circulation","structure":"blood + circulation (compound noun)","meaning":"the movement of blood through the body","meaningCN":"血液循环","example":"Massage improves blood circulation.","exampleCN":"按摩改善血液循环。"}],"latinEntries":[{"word":"circus","structure":"Latin noun, 'ring, circle, racecourse'","meaning":"a ring or oval track","meaningCN":"环；圆圈；赛道"},{"word":"circulus","structure":"diminutive of circus","meaning":"a small ring or circle","meaningCN":"小环；圆圈"},{"word":"circulatio","structure":"circulare + -tio (action noun), Late Latin","meaning":"a going round, circular movement","meaningCN":"绕行；循环运动"}]}},{"word":"classification","ipa_uk":"/ˌklæsɪfɪˈkeɪʃn/","ipa_us":"/ˌklæsəfəˈkeɪʃn/","definition_zh":"分类；类别；分类体系；密级","definition_en":"the act of arranging things into groups, the system used for it, or the group into which something is placed","core_image":"一堆混杂的物件被逐一放进贴着标签的格子里","scene":"图书馆员推着书车，把书按主题标签分到不同的书架区。The librarian pushes a trolley and sorts the books by subject label, and this classification keeps every shelf in order.","sceneCN":"这里 classification 是「分类行为与分类体系」（第 1、2、4 个义项：分类、类别系统、图书馆分类法）；句意：馆员推着书车按主题标签把书分到各个书架区，这种分类让每排书架井然有序。图中可辨识物件：书架区、主题标签、书车、索引卡。","pos":[{"tag":"n.","zh":"分类；类别；分类体系；密级"}],"collocations":[{"phrase":"classification system","zh":"分类体系"},{"phrase":"biological classification","zh":"生物分类"},{"phrase":"classification scheme","zh":"分类方案"},{"phrase":"security classification","zh":"安全密级"},{"phrase":"classification of data","zh":"数据分类"},{"phrase":"broad classification","zh":"粗略的分类"}],"forms":[{"label":"单数","form":"classification"},{"label":"复数（指多种分类体系或类别）","form":"classifications"},{"label":"动词形式","form":"classify"}],"derivatives":[{"word":"classify","pos":"v.","zh":"分类；把……归类"},{"word":"classified","pos":"adj.","zh":"已分类的；机密的"},{"word":"classifier","pos":"n.","zh":"分类者；分类器"},{"word":"declassify","pos":"v.","zh":"解密；撤销密级"}],"senses":[{"no":"01","title":"The act of sorting into groups","titleCN":"把事物分组的动作","definition":"the process of putting things into groups according to shared features","definitionCN":"按共同特征把事物归入不同组别的过程","example":"The classification of the samples took several weeks.","exampleCN":"对这些样本进行分类花了数周。","why":"The -ation suffix names the activity. Classification is first a verb made into a noun: someone decides which pile each thing belongs to.","whyCN":"后缀 -ation 命名活动。classification 首先是把动词变成名词：某人决定每样东西属于哪一堆。"},{"no":"02","title":"A system of classes","titleCN":"类别体系","definition":"an organised scheme of groups, with rules for what belongs in each","definitionCN":"有组织的组别方案，并带有判断归属的规则","example":"The new classification replaced three older systems.","exampleCN":"新的分类体系取代了三套旧体系。","why":"The word shifts from act to structure. A classification is the grid itself, not the person filling it.","whyCN":"这个词从动作转向结构。classification 是那张格子本身，而不是往里填东西的人。"},{"no":"03","title":"Biological classification","titleCN":"生物分类","definition":"the grouping of organisms into species, genera and higher ranks","definitionCN":"把生物归入种、属及更高阶元","example":"The classification of the plant was revised after DNA analysis.","exampleCN":"DNA 分析之后，这种植物的分类被修订。","why":"Biology made the word technical: rank is not arbitrary but must reflect ancestry. A reclassification here is a claim about kinship.","whyCN":"生物学把这个词技术化：阶元不是随意的，而必须反映亲缘。这里的重新分类是关于亲缘关系的断言。"},{"no":"04","title":"Library classification","titleCN":"图书馆分类法","definition":"a scheme that assigns shelf numbers to books by subject","definitionCN":"按主题为图书分配书架号的方案","example":"The library uses the Dewey classification.","exampleCN":"该图书馆使用杜威分类法。","why":"A library classification is a physical plan as much as an intellectual one: each class must have a place on a shelf, and a book can stand in only one.","whyCN":"图书馆分类法既是知识方案，也是物理方案：每个类都必须在书架上有一处位置，而一本书只能站在一处。"},{"no":"05","title":"Security classification","titleCN":"保密等级划定","definition":"the official assignment of a document to a secrecy level","definitionCN":"把文件正式划入某一保密等级","example":"The report's classification was raised to top secret.","exampleCN":"这份报告的密级被提高到绝密。","why":"Here sorting determines who may read, not where a thing belongs. The classes are levels of access, and the verb's object is information.","whyCN":"这里的归类决定的是谁能读，而不是东西属于哪里。这些“类”是访问级别，而动词的宾语是信息。"},{"no":"06","title":"Data classification","titleCN":"数据分类","definition":"in computing, the assignment of data to categories for storage, analysis or protection","definitionCN":"在计算中，把数据归入类别以便存储、分析或保护","example":"Machine learning models perform automatic classification of images.","exampleCN":"机器学习模型对图像进行自动分类。","why":"Computing borrowed the word for a task a machine can do: given features, assign the item to a label. The human act becomes an algorithm.","whyCN":"计算领域借用这个词，指一项机器能做的任务：给出一组特征，把项目分配到标签。人的动作变成了算法。"},{"no":"07","title":"Occupational classification","titleCN":"职业或行业分类","definition":"the grouping of jobs into standard categories for statistics and policy","definitionCN":"把职业归入标准类别，以便统计与政策使用","example":"Nurses fall under a different occupational classification than doctors.","exampleCN":"护士与医生属于不同的职业分类。","why":"Governments classify work so that unlike things can be counted together. The categories are administrative decisions with real consequences for pay and rights.","whyCN":"政府给职业分类，好让不同的事物可以被合并计数。这些类别是行政决定，对薪酬与权利有实际后果。"},{"no":"08","title":"Grading of goods","titleCN":"商品分级","definition":"the sorting of a product into quality grades, as of wool, tea or eggs","definitionCN":"把产品按质量等级分选，如羊毛、茶叶或鸡蛋","example":"The wool receives a fine classification before sale.","exampleCN":"羊毛在出售前被分为细毛等级。","why":"This is the oldest commercial sense: the class is a price band. The word connects the sorting table to the market.","whyCN":"这是最古老的商业义项：类别就是价格带。这个词把分选台与市场连起来。"},{"no":"09","title":"The resulting category","titleCN":"归类所得的结果","definition":"the class or label into which something has been placed","definitionCN":"某物被归入的类别或标签","example":"The species belongs to a broad classification of flowering plants.","exampleCN":"该物种属于被子植物的一个宽泛类别。","why":"Metonymy again: the act's name comes to mean its output. The classification is what you find when you look up the item.","whyCN":"又是转喻：动作的名称变成了它的产物。classification 就是你查这个项目时看到的那个类别。"}],"etymology":{"intro":{"en":"Classification is classify plus -ation. Classify was built in the 18th century from the Latin pair classis, 'a division or class', and facere, 'to make': to make classes. Classis itself is an old Roman word whose deeper origin is disputed. The compound is modern, but both halves are ancient.","cn":"classification 是 classify 加 -ation。classify 由 18 世纪用拉丁一对词构造：classis“划分、等级”与 facere“做”，意为“做出类别”。classis 本身是古老的罗马词，其更深来源有争议。复合词是现代的，两个半部却是古老的。"},"items":[{"era":"LATIN classis","en":"Classis named a division of the Roman people, and also a fleet. Its deeper origin is debated; one proposal links it to calare, 'to summon', since a class was a body called together.","cn":"classis 指罗马人的一个等级划分，也指舰队。其更深来源有争议；一种说法把它连到 calare“召集”，因为一个等级就是被召集起来的一群人。"},{"era":"LATIN facere","en":"Facere, 'to make', supplied the second half of many Latin compounds. Here it turns a noun of division into a verb of dividing.","cn":"facere“做”是许多拉丁复合词的后半。这里它把表示划分的名词变成表示划分的动词。"},{"era":"MEDIEVAL LATIN classificare","en":"Classificare, 'to divide into classes', appears in medieval Latin, where scholars were arranging knowledge into ranked orders.","cn":"classificare“分为等级”出现在中世纪拉丁，当时学者正把知识编排成有等级的秩序。"},{"era":"18C. FRENCH classifier","en":"French formed classifier, and English took classify in the 18th century. The period's natural history, especially Linnaeus, made the practice central to science.","cn":"法语造出 classifier，英语在 18 世纪接来 classify。这一时期的博物学，尤其是林奈的工作，使分类成为科学的核心实践。"},{"era":"18C. ENGLISH classification","en":"The noun classification is recorded from the late 18th century, a date best given as approximate. Its first strong use was in natural history and library work.","cn":"名词 classification 自 18 世纪晚期有记录，这个年代只能大致给出。它最早的重要用法在博物学与图书馆工作中。"},{"era":"MODERN ENGLISH","en":"In the 20th century the word expanded into computing, security and administration. The class became a data label, an access level or a job code, while the act of sorting stayed the same.","cn":"在 20 世纪，这个词扩展到计算、保密与行政。类别变成数据标签、访问级别或职业代码，而分选这个动作没有变。"}]},"similar":{"note":{"en":"The first group separates the noun from the verb, the adjective and the agent. The second group compares ways of dividing the world into groups.","cn":"第一组把名词与动词、形容词、施动者分开。第二组比较把世界分成组别的不同方式。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"classify","ipa":"/ˈklæsɪfaɪ/","tag":"the verb","definition":"to put into a class. The verb names the act; classification names the act or its result.","definitionCN":"把……归入某类。动词命名动作；classification 命名动作或结果。"},{"word":"classified","ipa":"/ˈklæsɪfaɪd/","tag":"the adjective","definition":"placed in a class, or officially secret. It describes the thing rather than the system.","definitionCN":"已归类的，或官方机密的。它描述事物，而不是体系。"},{"word":"classifier","ipa":"/ˈklæsɪfaɪə/","tag":"agent noun","definition":"a person or algorithm that assigns classes. It is the -er form of the verb.","definitionCN":"分配类别的人或算法。它是动词的 -er 形式。"}]},{"heading":"NEAR MEANING","entries":[{"word":"categorization","ipa":"/ˌkætəɡəraɪˈzeɪʃn/","tag":"grouping","definition":"the placing of things into categories. It is close to classification but more common in psychology and everyday speech.","definitionCN":"把事物放入类别。它接近 classification，但在心理学与日常语言中更常用。"},{"word":"taxonomy","ipa":"/tækˈsɒnəmi/","tag":"biological scheme","definition":"the science or scheme of biological classification. It is narrower and usually implies ranks and names.","definitionCN":"生物分类的学问或体系。它更窄，通常含等级与命名。"},{"word":"sorting","ipa":"/ˈsɔːtɪŋ/","tag":"physical act","definition":"the physical arranging of items into groups. It stresses the handling of objects rather than the scheme behind it.","definitionCN":"把物件实际分组的动作。它强调对物品的操作，而不是背后的方案。"},{"word":"grading","ipa":"/ˈɡreɪdɪŋ/","tag":"quality levels","definition":"the assignment of quality levels. It ranks within a scale, while classification only separates groups.","definitionCN":"划定质量等级。它在一个尺度内排序，而 classification 只把组别分开。"}]}]},"mnemonics":{"normalIntro":{"en":"These hooks use the two Latin halves of the word and then attach it to the shelves, the lab, the archive and the server room.","cn":"这些记忆钩利用词的两个拉丁半部，再把它系到书架、实验室、档案库与机房。"},"normal":[{"en":"Split it: class (group) plus ification (making). To classify is to make groups.","cn":"拆开：class（组）加 ification（做成）。classify 就是做出组别。"},{"en":"See the labelled pigeonholes: one object, one slot.","cn":"看那些贴标签的格子：一个物件，一个格子。"},{"en":"Remember the library shelf: a book can stand in only one place.","cn":"记住图书馆书架：一本书只能站一处。"},{"en":"Remember the security sense: a stamp that decides who may read.","cn":"记住保密义：一枚决定谁能读的章。"},{"en":"Beware the cousin classic: same root, but it drifted to 'of the highest class'.","cn":"提防表亲 classic：同根，却漂移到“最高等级的”。"}],"abstract":[{"en":"Hold one act: put each thing in exactly one box. Every sense is either that act, the box system, or the box chosen.","cn":"抓住一个动作：把每样东西放进恰好一个盒子。每个义项要么是这个动作，要么是盒子系统，要么是被选中的盒子。"},{"en":"Sort the senses by purpose: knowledge, shelves, secrecy, computation, statistics, price, result.","cn":"按目的分组：知识、书架、保密、计算、统计、价格、结果。"},{"en":"Notice what classification cannot do: it cannot leave an item unplaced, and it cannot put one item in two classes at once.","cn":"留意分类做不到的事：它不能让一个项目无处可放，也不能把同一项目同时放进两类。"}]},"examples":[{"en":"The classification of the documents delayed their release.","cn":"文件的密级划定推迟了它们的公开。"},{"en":"Linnaeus built a classification that is still in use.","cn":"林奈建立了一套至今仍在使用的分类体系。"},{"en":"The algorithm assigns each image a classification.","cn":"该算法为每张图像指定一个分类。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音“克拉斯飞 K 神”：先看 class（类别），再“飞”快地把东西分进格子里——classification 分类。","word":"classification"},"root":"拉丁语 classis“等级、划分”加 facere“做”，中世纪拉丁 classificare“分为等级”；18 世纪经法语 classifier 进入英语为 classify，再加 -ation 成 classification。","sensesIntro":{"en":"Classification is the act of putting one thing into one box, and everything else into others. The boxes change with the world being sorted: species in biology, shelf numbers in a library, secrecy levels in government, labels in a dataset, job codes in statistics, grades in a market. In every case the same two rules hold: an item must land somewhere, and it must not land in two places at once.","cn":"classification 是把一样东西放进一个盒子、把其余放进别的盒子的动作。盒子随被分类的世界而变：生物学里的物种、图书馆里的书架号、政府里的密级、数据集里的标签、统计里的职业代码、市场里的等级。每种情形都遵守同两条规则：一个项目必须落在某处，且不能同时落在两处。"},"semanticMap":{"core":{"en":"One item, one box: divide the world and place each thing exactly once.","cn":"一项一格：划分世界，把每样东西恰好放一次。"},"chain":["DIVIDE","GROUP","RULE","SCHEME","LABEL","ORDER"],"branches":[{"senses":"S1 · S9","en":"ACT AND RESULT: the sorting, and the category it produces.","cn":"动作与结果：分选，以及它产生的类别。"},{"senses":"S2 · S4","en":"SYSTEMS: the scheme itself, and the library's shelf plan.","cn":"体系：方案本身，以及图书馆的书架规划。"},{"senses":"S3","en":"LIFE: biological ranks that must reflect ancestry.","cn":"生命：必须反映亲缘的生物阶元。"},{"senses":"S5 · S6 · S7","en":"ADMINISTRATION: secrecy, data labels, job codes.","cn":"行政：保密、数据标签、职业代码。"},{"senses":"S8","en":"MARKET: quality grades as price bands.","cn":"市场：作为价格带的质量等级。"}]},"affixes":{"intro":{"en":"Classification is classify plus -ation, and classify is classis plus facere. The items follow that build, then add the de-, re- and mis- forms that mark the removal, repetition and error of classification.","cn":"classification 是 classify 加 -ation，classify 又是 classis 加 facere。条目沿这个构造展开，再加上表示撤销、重复与错误分类的 de-、re-、mis- 形式。"},"latinIntro":{"en":"The Latin entries give the noun of division, the medieval verb built on it, and the adjective classicus. The last one matters because it explains why classic looks like class but means 'of the highest rank'.","cn":"拉丁语条目给出表示划分的名词、由它构成的中世纪动词，以及形容词 classicus。最后一条很重要，因为它解释了 classic 为何形似 class，却意为“最高等级的”。"},"items":[{"word":"classification","structure":"classify + -ation (action noun)","meaning":"the act or system of grouping things","meaningCN":"分类；分类体系","example":"The classification of plants follows family lines.","exampleCN":"植物的分类沿科属线展开。"},{"word":"classify","structure":"Latin classis + facere, through French classifier","meaning":"to arrange into classes","meaningCN":"把……分类；归类","example":"Scientists classify the fossils by age.","exampleCN":"科学家按年代给化石分类。"},{"word":"classified","structure":"classify + -ed (past participle adjective)","meaning":"placed in a class; officially secret","meaningCN":"已分类的；机密的","example":"The report remains classified.","exampleCN":"该报告仍属机密。"},{"word":"classifier","structure":"classify + -er (agent noun)","meaning":"a person or system that assigns classes","meaningCN":"分类者；分类器","example":"The classifier sorted the emails automatically.","exampleCN":"分类器自动分拣邮件。"},{"word":"class","structure":"Latin classis, through French","meaning":"a group sharing a feature; a social rank; a school lesson","meaningCN":"类别；阶级；班级","example":"The two species belong to the same class.","exampleCN":"这两个物种属于同一纲。"},{"word":"classic","structure":"Latin classicus, 'of the highest class'","meaning":"a work of the highest rank","meaningCN":"经典作品","example":"The novel is a classic of modern literature.","exampleCN":"这部小说是现代文学的经典。"},{"word":"declassify","structure":"de- (remove) + classify","meaning":"to remove a secrecy classification","meaningCN":"解密；撤销密级","example":"The archive declassified the files after fifty years.","exampleCN":"五十年后档案馆解密了这些文件。"},{"word":"reclassify","structure":"re- (again) + classify","meaning":"to place in a different class","meaningCN":"重新分类；改类","example":"The plant was reclassified as a separate genus.","exampleCN":"该植物被重新归入一个独立的属。"},{"word":"misclassify","structure":"mis- (wrongly) + classify","meaning":"to place in the wrong class","meaningCN":"错误分类","example":"The software misclassified the rare species.","exampleCN":"该软件错误分类了这种稀有物种。"},{"word":"classification scheme","structure":"classification + scheme (compound noun)","meaning":"an organised plan of classes and their rules","meaningCN":"分类方案","example":"The archive adopted a new classification scheme.","exampleCN":"档案馆采用了新的分类方案。"}],"latinEntries":[{"word":"classis","structure":"Latin noun, 'division, class, fleet'","meaning":"a division of citizens; a fleet","meaningCN":"等级；公民划分；舰队"},{"word":"classificare","structure":"classis + facere, Medieval Latin","meaning":"to divide into classes","meaningCN":"分为等级；分类"},{"word":"classicus","structure":"classis + -icus (adjective)","meaning":"of the highest class of citizens; hence, first-rate","meaningCN":"最高等级的；一流的"}]}},{"word":"classified","ipa_uk":"/ˈklæsɪfaɪd/","ipa_us":"/ˈklæsəfaɪd/","definition_zh":"机密的；已分类的；分类的（广告、目录）","definition_en":"officially secret and restricted in access, or arranged into classes; also used of small advertisements grouped by category","core_image":"一份文件封面上盖着红色密级章，旁边挂着一把锁","scene":"档案馆的接待室里，工作人员把一份文件放进保险柜，访客只能看到空空的桌面。In the reading room a clerk locks a classified file in the safe, so visitors see only an empty desk.","sceneCN":"这里 classified 是「机密的」（第 1 个义项：受保密限制的信息）；句意：接待室里，工作人员把一份机密文件锁进保险柜，访客只能看到空桌面。图中可辨识物件：保险柜、红色密级章、文件封套、访客登记簿。","pos":[{"tag":"adj.","zh":"机密的；已分类的"},{"tag":"n.","zh":"分类广告（常用复数 classifieds）"}],"collocations":[{"phrase":"classified information","zh":"机密信息"},{"phrase":"classified documents","zh":"机密文件"},{"phrase":"classified ads","zh":"分类广告"},{"phrase":"classified as","zh":"被归为"},{"phrase":"highly classified","zh":"高度机密的"},{"phrase":"classified catalogue","zh":"分类目录"}],"forms":[{"label":"原级（形容词）","form":"classified"},{"label":"原形（动词）","form":"classify"},{"label":"名词复数（分类广告）","form":"classifieds"}],"derivatives":[{"word":"classify","pos":"v.","zh":"分类；把……列为机密"},{"word":"classification","pos":"n.","zh":"分类；分类体系；密级"},{"word":"classifier","pos":"n.","zh":"分类者；分类器"},{"word":"declassify","pos":"v.","zh":"解密；撤销密级"}],"senses":[{"no":"01","title":"Officially secret","titleCN":"官方机密的","definition":"of information or documents, marked as restricted and available only to authorised people","definitionCN":"指信息或文件被标记为受限，只有获授权者可以接触","example":"The general refused to discuss the classified report.","exampleCN":"将军拒绝讨论这份机密报告。","why":"This is the dominant modern sense. The past participle freezes an official act: someone has already placed this document in a restricted class, and the adjective records that decision.","whyCN":"这是现代最主要的义项。过去分词冻结了一个官方动作：某人已经把这份文件归入受限类别，形容词记录的就是这个决定。"},{"no":"02","title":"Placed in a category","titleCN":"被归入某一类别的","definition":"assigned to a group according to shared features","definitionCN":"按共同特征被分配到某一组","example":"The insects are classified by wing structure.","exampleCN":"这些昆虫按翅的结构被分类。","why":"Here the participle keeps the plain verbal sense: an item has received a class. Nothing is hidden; the point is where the item was put.","whyCN":"这里分词保留朴素的动词义：一个项目已经获得了类别。没有隐藏任何东西，重点在于它被放到了哪里。"},{"no":"03","title":"Classified advertisements","titleCN":"分类广告","definition":"short advertisements printed together under subject headings, or the section containing them","definitionCN":"按主题归在一起刊登的短广告，或刊载它们的版面","example":"He found the apartment through the classifieds.","exampleCN":"他通过分类广告找到了那套公寓。","why":"Newspapers sorted small ads into columns by category, so the adjective became a noun. The word now names a whole genre of paid notices.","whyCN":"报纸把小块广告按类别排进专栏，于是形容词变成了名词。这个词现在命名一整类付费启事。"},{"no":"04","title":"Graded by quality","titleCN":"按质量分级的","definition":"sorted into quality grades, as of wool, timber or eggs","definitionCN":"按质量等级分选，如羊毛、木材或鸡蛋","example":"Classified wool sells at a higher price.","exampleCN":"分级羊毛卖价更高。","why":"Market grading uses the same verb: the class is a price band. The participle tells the buyer that inspection has already happened.","whyCN":"市场分级用的是同一个动词：类别就是价格带。这个分词告诉买家，检验已经做过了。"},{"no":"05","title":"A post requiring security clearance","titleCN":"需安全审查的岗位","definition":"of a job or position, requiring access to secret material and therefore a clearance check","definitionCN":"指需要接触机密材料、因而须通过安全审查的工作或职位","example":"She applied for a classified position at the ministry.","exampleCN":"她申请了部里的一个涉密职位。","why":"This sense shifts the restriction from the document to the person. The class no longer marks the paper but the level of trust granted to an employee.","whyCN":"这一义把限制从文件移到人身上。这个“类”不再标记纸张，而是标记授予雇员的信任等级。"},{"no":"06","title":"Assigned a biological taxon","titleCN":"在生物分类中被归入的","definition":"placed in a species, genus or higher rank by taxonomy","definitionCN":"由分类学归入某一物种、属或更高阶元","example":"The fossil was classified as a new species.","exampleCN":"该化石被归为一个新物种。","why":"Biology uses the participle for a completed judgement. Once classified, a specimen has a name and a place in the tree, and later work may move it.","whyCN":"生物学用这个分词表示已完成的判断。一旦被分类，标本就有了名称与在树上的位置，后来的工作可能把它移走。"},{"no":"07","title":"Labelled in a dataset","titleCN":"在数据集中被标注的","definition":"in computing, assigned a category label in training or reference data","definitionCN":"在计算中，在训练或参考数据里被指定类别标签","example":"The model learns from thousands of classified images.","exampleCN":"模型从上万张已标注图像中学习。","why":"Machine learning borrows the participle for data whose category is already known. The adjective marks the difference between raw input and answered input.","whyCN":"机器学习借用这个分词，指类别已知的数据。这个形容词标出原始输入与已给答案的输入之间的差别。"},{"no":"08","title":"Officially listed as a status","titleCN":"被正式列为某种状态","definition":"formally designated as having a particular status, such as endangered or a controlled substance","definitionCN":"被正式指定具有某种身份，如濒危或受管制物质","example":"The bird is classified as endangered.","exampleCN":"这种鸟被列为濒危。","why":"The phrase classified as marks an official designation with legal force. It is not a description but a decision that changes what may be done.","whyCN":"短语 classified as 标示具有法律效力的官方认定。它不是描述，而是一个改变“可以做什么”的决定。"},{"no":"09","title":"Arranged in a classified catalogue","titleCN":"按分类编排的目录","definition":"of a catalogue or index, arranged by subject class rather than alphabetically","definitionCN":"指目录或索引按主题类别而非字母顺序编排","example":"The old library used a classified catalogue.","exampleCN":"旧图书馆使用分类目录。","why":"A classified catalogue lets a reader browse by subject. The adjective describes the arrangement of the finding aid, not the secrecy of its contents.","whyCN":"分类目录让读者按主题浏览。这个形容词描述检索工具的编排，而不是其内容的机密性。"}],"etymology":{"intro":{"en":"Classified is the past participle of classify plus the native English suffix -ed, so its history is the history of classify. The Latin halves are classis, 'division', and facere, 'to make'. What is worth noting is that the suffix is English, not Latin, and that the secrecy sense is a 20th-century specialization of a much older idea of sorting.","cn":"classified 是 classify 的过去分词，加上英语本族后缀 -ed，所以它的历史就是 classify 的历史。拉丁的两个半部是 classis“划分”与 facere“做”。值得注意的是：后缀是英语的，不是拉丁的；而“机密”义是 20 世纪对一个更古老的“分选”观念的特殊化。"},"items":[{"era":"LATIN classis","en":"Classis named a division of Roman citizens and also a fleet. Its deeper origin is disputed; a link with calare, 'to summon', has been proposed but not settled.","cn":"classis 指罗马公民的一个等级划分，也指舰队。其更深来源有争议；与 calare“召集”的关联被提出过，但未有定论。"},{"era":"LATIN facere","en":"Facere, 'to make', is the second half of the compound. In classificare it carries the sense 'to make into classes'.","cn":"facere“做”是复合词的后半。在 classificare 中，它带有“使成为类别”的意思。"},{"era":"MEDIEVAL LATIN classificare","en":"Classificare appears in medieval Latin for the arranging of knowledge or objects into ranks. Its participle classificatus is the formal ancestor of the English adjective.","cn":"classificare 出现在中世纪拉丁，指把知识或物件编排成等级。它的分词 classificatus 是英语形容词的形式祖先。"},{"era":"18C. ENGLISH classify","en":"English took classify from French classifier in the 18th century, when natural history made classification a central science. The verb was then regular: classify, classified, classified.","cn":"英语在 18 世纪从法语 classifier 接来 classify，当时博物学使分类成为核心科学。随后动词按规则变化：classify、classified、classified。"},{"era":"19C.-20C. ENGLISH classified","en":"The adjective first meant simply 'arranged in classes', and classified ads belong to 19th-century newspapers. The secrecy sense developed in the 20th century, especially through military and government practice.","cn":"这个形容词最初只表示“按类别编排”，分类广告属于 19 世纪报纸的做法。“机密”义在 20 世纪发展起来，尤其通过军事与政府实践。"},{"era":"MODERN ENGLISH","en":"Modern English uses classified for documents, jobs, species, data labels, official statuses and catalogues. The same participle now covers both 'sorted' and 'hidden', two outcomes of the same administrative act.","cn":"现代英语把 classified 用于文件、职位、物种、数据标签、官方身份与目录。同一个分词现在同时覆盖“已分选”与“被隐藏”，这是同一行政动作的两种结果。"}]},"similar":{"note":{"en":"The first group separates the adjective from the verb, the noun of action and the plural noun for advertisements. The second group compares levels of restriction and of labelling.","cn":"第一组把形容词与动词、动作名词、表示广告的复数名词分开。第二组比较限制与标注的不同层级。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"classify","ipa":"/ˈklæsɪfaɪ/","tag":"the verb","definition":"to assign to a class. Classified is what has happened to the thing; classify is what someone did.","definitionCN":"把……归入某类。classified 是事物经历的结果；classify 是某人做的动作。"},{"word":"classification","ipa":"/ˌklæsɪfɪˈkeɪʃn/","tag":"the noun of action","definition":"the act or system of grouping. It names the process or scheme, not the item.","definitionCN":"分组的行为或体系。它命名过程或方案，而不是项目。"},{"word":"classifieds","ipa":"/ˈklæsɪfaɪdz/","tag":"plural noun","definition":"the section of a newspaper containing small category-sorted advertisements. The plural is a separate noun, not just a plural adjective.","definitionCN":"报纸中刊登按类别归置的小广告的版面。这个复数是独立名词，不只是形容词的复数。"}]},{"heading":"NEAR MEANING","entries":[{"word":"confidential","ipa":"/kənˈfɪdenʃl/","tag":"private trust","definition":"meant to be kept private between the parties concerned. It stresses a relationship of trust rather than an official secrecy level.","definitionCN":"意图在相关方之间保密的。它强调信任关系，而不是官方密级。"},{"word":"secret","ipa":"/ˈsiːkrət/","tag":"hidden","definition":"known only to a few. It is the plain word; classified is the administrative and legal term.","definitionCN":"只有少数人知道的。它是朴素说法；classified 是行政与法律术语。"},{"word":"restricted","ipa":"/rɪˈstrɪktɪd/","tag":"limited access","definition":"available only to people with permission. It describes the limit itself, while classified names the system that imposes it.","definitionCN":"只对获许可者开放。它描述限制本身，而 classified 命名施加限制的制度。"},{"word":"graded","ipa":"/ˈɡreɪdɪd/","tag":"ranked by quality","definition":"sorted into quality levels. It ranks within a scale, while classified usually separates into categories.","definitionCN":"按质量层级分选。它在一个尺度内排序，而 classified 通常把事物分成类别。"}]}]},"mnemonics":{"normalIntro":{"en":"These hooks build the adjective from classify and then attach it to the two worlds it now serves: secrecy and sorting.","cn":"这些记忆钩从 classify 搭起这个形容词，再把它系到它现在服务的两个世界：保密与分选。"},"normal":[{"en":"See the chain: class, classify, classified. The -ed means the job is done.","cn":"看见链条：class、classify、classified。后缀 -ed 表示事情已经做完。"},{"en":"Picture the red stamp on a folder: that is the secrecy sense.","cn":"想象文件夹上的红色印章：那就是机密义。"},{"en":"Picture the newspaper columns: small ads sorted by category.","cn":"想象报纸的专栏：小块广告按类别归置。"},{"en":"Keep the phrase classified as for official designations such as endangered.","cn":"记住 classified as，用于濒危等官方认定。"},{"en":"Contrast it with unclassified: the same word with the lid removed.","cn":"与 unclassified 对比：同一个词，盖子被拿掉。"}],"abstract":[{"en":"Hold one act: a decision has been made about where this belongs. Everything else follows from that decision.","cn":"抓住一个动作：关于它属于哪里，已经作出了决定。其余一切都从这个决定而来。"},{"en":"Sort the senses by what is classified: documents, things, ads, goods, jobs, species, data, statuses, catalogues.","cn":"按被分类的对象分组：文件、物品、广告、货物、职位、物种、数据、身份、目录。"},{"en":"Notice the double edge: the same stamp that sorts a thing can also hide it.","cn":"留意双刃：同一个印章既能给事物分类，也能把它藏起来。"}]},"examples":[{"en":"The minister was shown classified intelligence before the meeting.","cn":"会前部长看到了机密情报。"},{"en":"The tablets are classified as controlled substances.","cn":"这些药片被列为受管制物质。"},{"en":"He sold his old bicycle through the classified ads.","cn":"他通过分类广告卖掉了旧自行车。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"谐音“克拉斯法爱德”：class 是类别，-fied 是“被做成”——已经被分进某个类里，文件进了“机密”这一类，就是 classified。","word":"classified"},"root":"拉丁语 classis“等级、划分”加 facere“做”，中世纪拉丁 classificare“分为等级”；18 世纪英语 classify，其过去分词 classified 加本族后缀 -ed。","sensesIntro":{"en":"Classified is a decision already made, seen from the side of the thing decided about. That thing may be a document placed in a secrecy level, a species placed in a genus, a sheep's fleece placed in a grade, a job placed under clearance rules, or an image placed in a training label. The two modern poles are sorting and hiding, and both come from the same administrative act: someone with authority said where this belongs.","cn":"classified 是一个已经作出的决定，从被决定者的角度看到的结果。这个被决定者可以是归入某密级的文件、归入某属的物种、归入某等级的羊毛、归入审查规则的职位，或归入训练标签的图像。现代的两极是“分选”与“隐藏”，两者都来自同一个行政动作：有权限的人说了它属于哪里。"},"semanticMap":{"core":{"en":"A decision has been made: this belongs here, and access follows from that.","cn":"决定已经作出：它属于这里，接触权限由此而来。"},"chain":["DECIDE","ASSIGN","GROUP","LABEL","RESTRICT","RECORD"],"branches":[{"senses":"S1 · S5","en":"SECRECY: the document and the post that guard it.","cn":"保密：文件本身，以及守着它的岗位。"},{"senses":"S2 · S9","en":"ORDER: the plain assignment, and the catalogue built from it.","cn":"秩序：朴素的归类，以及由此建立的目录。"},{"senses":"S3 · S4","en":"MARKET: advertisements and quality grades.","cn":"市场：广告与质量等级。"},{"senses":"S6 · S8","en":"OFFICIAL STATUS: species names and legal designations.","cn":"官方身份：物种名称与法律认定。"},{"senses":"S7","en":"DATA: labels that teach a machine.","cn":"数据：教机器认类的标签。"}]},"affixes":{"intro":{"en":"Classified is classify plus the native English -ed. The items below follow that chain, then add the un-, de- and re- forms and three compounds where the adjective has become a fixed label.","cn":"classified 是 classify 加英语本族后缀 -ed。下面的条目沿这条链展开，再加上 un-、de-、re- 形式，以及三个形容词已成固定标签的复合词。"},"latinIntro":{"en":"The Latin entries give the noun of division, the medieval verb, and its participle. The participle is the formal model behind the English adjective, even though the English suffix itself is native.","cn":"拉丁语条目给出表示划分的名词、中世纪动词及其分词。尽管英语后缀本身是本族的，这个分词仍是英语形容词背后的形式样板。"},"items":[{"word":"classified","structure":"classify + -ed (English past participle)","meaning":"placed in a class; officially secret","meaningCN":"已分类的；机密的","example":"The files are classified until 2030.","exampleCN":"这些文件保密至 2030 年。"},{"word":"classify","structure":"Latin classis + facere, via French classifier","meaning":"to assign to a class","meaningCN":"分类；归类","example":"The library classifies books by subject.","exampleCN":"图书馆按主题给书分类。"},{"word":"classification","structure":"classify + -ation","meaning":"the act or system of grouping","meaningCN":"分类；分类体系","example":"The classification of the archive took months.","exampleCN":"档案的分类花了几个月。"},{"word":"classifier","structure":"classify + -er","meaning":"one that assigns classes","meaningCN":"分类者；分类器","example":"The classifier flagged the suspicious file.","exampleCN":"分类器标记了可疑文件。"},{"word":"unclassified","structure":"un- (not) + classified","meaning":"not secret; open to the public","meaningCN":"非机密的；公开的","example":"Only unclassified material was released.","exampleCN":"只公开了非机密材料。"},{"word":"declassified","structure":"de- (remove) + classified","meaning":"no longer officially secret","meaningCN":"已解密的","example":"The declassified papers revealed the plan.","exampleCN":"解密文件揭示了该计划。"},{"word":"reclassified","structure":"re- (again) + classified","meaning":"given a different class or level","meaningCN":"被重新分类的","example":"The substance was reclassified as hazardous.","exampleCN":"该物质被重新归类为危险品。"},{"word":"classified ad","structure":"classified + ad (compound noun)","meaning":"a short newspaper advertisement placed under a category","meaningCN":"分类广告","example":"She placed a classified ad for the room.","exampleCN":"她登了一则出租房间的分类广告。"},{"word":"classified information","structure":"classified + information (compound noun)","meaning":"material whose access is legally restricted","meaningCN":"机密信息","example":"Handling classified information requires clearance.","exampleCN":"处理机密信息需要安全许可。"},{"word":"classified catalogue","structure":"classified + catalogue (compound noun)","meaning":"a library catalogue arranged by subject class","meaningCN":"分类目录","example":"Search the classified catalogue for the shelf number.","exampleCN":"在分类目录中查书架号。"}],"latinEntries":[{"word":"classis","structure":"Latin noun, 'division, class, fleet'","meaning":"a division of citizens; a fleet","meaningCN":"等级；公民划分；舰队"},{"word":"classificare","structure":"classis + facere, Medieval Latin","meaning":"to divide into classes","meaningCN":"分为等级；分类"},{"word":"classificatus","structure":"past participle of classificare","meaning":"having been divided into classes","meaningCN":"已被分为等级的"}]}}]);
